    # Minimale Fallbacks
    def safe_execute(func, *args, default=None, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception:
            return default
    def safe_int(v, default=0):
        try:
            return int(v)
        except Exception:
            return default
    def safe_float(v, default=0.0):
        try:
            return float(v)
        except Exception:
            return default

