# =============================================================================
# TYPING SIMULATOR - Realistische Tipp-Simulation
# =============================================================================

class TypingSimulator:
    """
    Simuliert realistisches Tippen mit variablen Geschwindigkeiten.

    Features:
    - Variable Tippgeschwindigkeit (schneller bei einfachen Wörtern)
    - Denk-Pausen vor komplexen Antworten
    - Energie-basierte Geschwindigkeit (müde = langsamer)
    - Natürliche Varianz (kein roboterhaftes gleichmäßiges Tippen)
    """

    # Basis-Geschwindigkeiten (Zeichen pro Sekunde)
    TYPING_SPEEDS = {
        "fast": 80,      # Energiegeladen, kurze Antwort
        "normal": 50,    # Standard
        "slow": 30,      # Müde oder nachdenklich
        "thinking": 15,  # Bei komplexen Themen
    }

    # Denk-Pausen (Sekunden)
    THINKING_PAUSES = {
        "short": (0.3, 0.8),    # Kurze Überlegung
        "medium": (0.8, 1.5),   # Nachdenken
        "long": (1.5, 3.0),     # Komplexe Frage
    }

    # Wörter die Pausen auslösen
    PAUSE_TRIGGERS = {
        "hmm": "short",
        "also": "short",
        "...": "medium",
        "lass mich überlegen": "long",
        "gute frage": "medium",
        "interessant": "short",
    }

    def __init__(self, energy_system=None):
        self.energy = energy_system
        self.enabled = True
        self.speed_multiplier = 1.0

    def get_typing_speed(self, mood: str = "normal") -> float:
        """Berechne aktuelle Tippgeschwindigkeit basierend auf Energie und Stimmung."""
        base_speed = self.TYPING_SPEEDS.get(mood, self.TYPING_SPEEDS["normal"])

        # Energie-Modifikator
        if self.energy:
            try:
                status = self.energy.get_status()
                energy_level = status.get('total_energy', 0.5)

                if energy_level < 0.3:
                    base_speed *= 0.6  # Müde = langsamer
                elif energy_level > 0.7:
                    base_speed *= 1.3  # Energiegeladen = schneller
            except Exception as e:
                logger.debug(f"Energy level retrieval failed: {e}")

        return base_speed * self.speed_multiplier

    def calculate_delay(self, text: str, mood: str = "normal") -> float:
        """
        Berechne Verzögerung für einen Text-Chunk.

        Args:
            text: Der zu "tippende" Text
            mood: Aktuelle Stimmung

        Returns:
            Verzögerung in Sekunden
        """
        if not self.enabled or not text:
            return 0

        speed = self.get_typing_speed(mood)
        base_delay = len(text) / speed

        # Natürliche Varianz hinzufügen (±20%)
        variance = random.uniform(0.8, 1.2)

        return base_delay * variance

    def get_thinking_pause(self, text: str) -> float:
        """
        Prüfe ob eine Denk-Pause nötig ist.

        Args:
            text: Der Text der geprüft wird

        Returns:
            Pause in Sekunden (0 wenn keine Pause)
        """
        text_lower = text.lower()

        for trigger, pause_type in self.PAUSE_TRIGGERS.items():
            if trigger in text_lower:
                min_pause, max_pause = self.THINKING_PAUSES[pause_type]
                return random.uniform(min_pause, max_pause)

        return 0

    def chunk_text(self, text: str, chunk_size: int = 5) -> List[str]:
        """
        Teile Text in natürliche Chunks (Wort-Gruppen).

        Args:
            text: Der zu teilende Text
            chunk_size: Anzahl Wörter pro Chunk

        Returns:
            Liste von Text-Chunks
        """
        words = text.split()
        chunks = []

        for i in range(0, len(words), chunk_size):
            chunk = ' '.join(words[i:i+chunk_size])
            if i + chunk_size < len(words):
                chunk += ' '
            chunks.append(chunk)

        return chunks if chunks else [text]

    async def stream_with_typing(self, text: str, mood: str = "normal"):
        """
        Async Generator der Text mit Tipp-Verzögerungen streamt.

        Usage:
            async for chunk in simulator.stream_with_typing("Hello World"):
                yield chunk
        """
        import asyncio

        # Initiale Denk-Pause
        think_pause = self.get_thinking_pause(text[:50])
        if think_pause > 0:
            await asyncio.sleep(think_pause)

        # Text in Chunks teilen
        chunks = self.chunk_text(text)

        for chunk in chunks:
            delay = self.calculate_delay(chunk, mood)
            await asyncio.sleep(delay)
            yield chunk

    def stream_with_typing_sync(self, text: str, mood: str = "normal"):
        """
        Synchroner Generator für Tipp-Simulation.

        Usage:
            for chunk, delay in simulator.stream_with_typing_sync("Hello"):
                time.sleep(delay)
                yield chunk
        """
        # Initiale Denk-Pause
        think_pause = self.get_thinking_pause(text[:50])
        if think_pause > 0:
            yield ("", think_pause)  # Leerer Chunk mit Pause

        # Text in Chunks teilen
        chunks = self.chunk_text(text)

        for chunk in chunks:
            delay = self.calculate_delay(chunk, mood)
            yield (chunk, delay)


