    @staticmethod
    def calculate_easter(year: int) -> tuple:
        """Berechnet Ostersonntag nach Gauss-Algorithmus"""
        a = year % 19
        b = year // 100
        c = year % 100
        d = b // 4
        e = b % 4
        f = (b + 8) // 25
        g = (b - f + 1) // 3
        h = (19 * a + b - d - g + 15) % 30
        i = c // 4
        k = c % 4
        l = (32 + 2 * e + 2 * i - h - k) % 7
        m = (a + 11 * h + 22 * l) // 451
        month = (h + l - 7 * m + 114) // 31
        day = ((h + l - 7 * m + 114) % 31) + 1
        return (month, day)

    @staticmethod
    def calculate_karneval(year: int) -> tuple:
        """Rosenmontag = 48 Tage vor Ostersonntag"""
        easter = SeasonalEvents.calculate_easter(year)
        easter_date = datetime(year, easter[0], easter[1])
        rosenmontag = easter_date - timedelta(days=48)
        return (rosenmontag.month, rosenmontag.day)

    @staticmethod
    def calculate_muttertag(year: int) -> tuple:
        """2. Sonntag im Mai"""
        may_first = datetime(year, 5, 1)
        days_until_sunday = (6 - may_first.weekday()) % 7
        first_sunday = may_first + timedelta(days=days_until_sunday)
        second_sunday = first_sunday + timedelta(days=7)
        return (5, second_sunday.day)

    @staticmethod
    def calculate_vatertag(year: int) -> tuple:
        """Christi Himmelfahrt = 39 Tage nach Ostersonntag"""
        easter = SeasonalEvents.calculate_easter(year)
        easter_date = datetime(year, easter[0], easter[1])
        himmelfahrt = easter_date + timedelta(days=39)
        return (himmelfahrt.month, himmelfahrt.day)

    @classmethod
    def get_event_date(cls, event_name: str, year: int) -> Optional[tuple]:
        """Holt das Datum eines Events"""
        event = cls.EVENTS.get(event_name)
        if not event:
            return None

        date_info = event["date"]
        if isinstance(date_info, tuple):
            return date_info
        elif date_info == "calculate_easter":
            return cls.calculate_easter(year)
        elif date_info == "calculate_karneval":
            return cls.calculate_karneval(year)
        elif date_info == "calculate_muttertag":
            return cls.calculate_muttertag(year)
        elif date_info == "calculate_vatertag":
            return cls.calculate_vatertag(year)
        return None

    @classmethod
    def get_current_events(cls) -> List[Dict]:
        """Holt alle aktuell relevanten Events (heute oder bald)"""
        now = datetime.now()
        year = now.year
        today = (now.month, now.day)

        relevant = []

        for name, event in cls.EVENTS.items():
            event_date = cls.get_event_date(name, year)
            if not event_date:
                continue

            # Event-Datum als datetime
            try:
                event_dt = datetime(year, event_date[0], event_date[1])
            except Exception:
                continue

            # Wenn Event schon vorbei, nächstes Jahr prüfen
            if event_dt < now:
                event_date = cls.get_event_date(name, year + 1)
                if event_date:
                    event_dt = datetime(year + 1, event_date[0], event_date[1])

            days_until = (event_dt - now).days

            # Ist es heute?
            if days_until == 0:
                relevant.append({
                    "name": name,
                    "event": event,
                    "days_until": 0,
                    "is_today": True,
                    "date": event_dt
                })
            # Ist es bald?
            elif 0 < days_until <= event.get("days_before", 7):
                relevant.append({
                    "name": name,
                    "event": event,
                    "days_until": days_until,
                    "is_today": False,
                    "date": event_dt
                })

        # Sortiert nach Nähe
        return sorted(relevant, key=lambda x: x["days_until"])

    @classmethod
    def get_current_season(cls) -> Dict:
        """Holt die aktuelle Jahreszeit"""
        month = datetime.now().month
        for name, season in cls.SEASONS.items():
            if month in season["months"]:
                return {"name": name, **season}
        return {"name": "unbekannt", "themes": [], "mood_modifier": 0, "emojis": [], "writing_style": "neutral"}


