def setup_logging():
    os.makedirs(BrainConfig.LOG_DIR, exist_ok=True)
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s [%(levelname)s] %(name)s: %(message)s',
        handlers=[
            logging.FileHandler(BrainConfig.LOG_DIR / "holo_brain.log"),
            logging.StreamHandler()
        ]
    )
    return logging.getLogger("HoloBrain")

logger = setup_logging()

# =============================================================================
# STARTUP DIAGNOSTICS - Log missing/degraded modules
# =============================================================================
def _log_startup_status():
    """Log status of all optional modules after logger is available"""
    critical_modules = {
        "SmartUnderstanding": SMART_UNDERSTANDING_AVAILABLE,
        "UnifiedLLM": UNIFIED_LLM_AVAILABLE,
        "HoloConfig": HOLO_CONFIG_AVAILABLE,
        "ErrorHandling": HOLO_ERROR_HANDLING_AVAILABLE,
    }
    optional_modules = {
        "Personality": PERSONALITY_AVAILABLE,
        "Consciousness": CONSCIOUSNESS_AVAILABLE,
        "InnerLife": INNER_LIFE_AVAILABLE,
        "ContextMind": CONTEXT_MIND_AVAILABLE,
        "HoloTools": HOLO_TOOLS_AVAILABLE,
        "Router": ROUTER_AVAILABLE,
        "Curiosity": CURIOSITY_SYSTEM_AVAILABLE,
        "MediaIndex": MEDIA_INDEX_AVAILABLE,
    }

    # Check critical modules
    missing_critical = [name for name, avail in critical_modules.items() if not avail]
    if missing_critical:
        logger.warning(f"⚠️ DEGRADED START: Critical modules missing: {', '.join(missing_critical)}")

    # Check optional modules
    missing_optional = [name for name, avail in optional_modules.items() if not avail]
    if missing_optional:
        logger.info(f"📦 Optional modules not loaded: {', '.join(missing_optional)}")

    # All good
    if not missing_critical and not missing_optional:
        logger.info("✅ All modules loaded successfully")
    elif not missing_critical:
        logger.info("✅ All critical modules loaded")

_log_startup_status()

