    def learn_fact(self, category: str, key: str, value: str, confidence: float = 0.5, source: str = "obs") -> None:
        now = datetime.now().isoformat()
        with self._get_connection() as conn:
            conn.execute("""
                INSERT OR REPLACE INTO knowledge (id, category, key, value, confidence, source, last_confirmed)
                VALUES (?, ?, ?, ?, ?, ?, ?)
            """, (hashlib.md5(f"{category}:{key}".encode()).hexdigest()[:12], category, key, value, confidence, source, now))

    def get_knowledge(self, category: str = None) -> Dict[str, Any]:
        with self._get_connection() as conn:
            conn.row_factory = sqlite3.Row
            if category:
                rows = conn.execute("SELECT key, value FROM knowledge WHERE category = ?", (category,)).fetchall()
                return {row["key"]: row["value"] for row in rows}
            else:
                rows = conn.execute("SELECT category, key, value FROM knowledge").fetchall()
                res = defaultdict(dict)
                for r in rows:
                    res[r["category"]][r["key"]] = r["value"]
                return dict(res)

