    # --- HOLO LIFE LOG v15 (Autonomes Leben dokumentieren) ---
    def log_life_event(self, category: str, event_type: str, description: str,
                       details: Dict = None, energy_level: float = None, mood: str = None):
        """
        Loggt ein Event aus Holos autonomem Leben.

        Categories:
        - thought: Gedanken, Überlegungen
        - activity: Aktivitäten (lesen, recherchieren, kreativ)
        - emotion: Emotionale Veränderungen
        - curiosity: Neugier, Fragen
        - boredom: Langeweile-Momente
        - dream: Träume
        - idle: Idle-Aktionen
        - social: Soziale Interaktionen
        - learning: Lernmomente
        - creative: Kreative Funken

        Event Types (je nach Category):
        - thought: philosophical, random, memory, question
        - activity: research, read, create, observe, rest
        - curiosity: question, interest, wonder
        - etc.
        """
        try:
            with self._get_connection() as conn:
                conn.execute("""
                    INSERT INTO holo_life_log
                    (timestamp, category, event_type, description, details_json, energy_level, mood)
                    VALUES (?, ?, ?, ?, ?, ?, ?)
                """, (
                    datetime.now().isoformat(),
                    category,
                    event_type,
                    description,
                    json.dumps(details) if details else None,
                    energy_level,
                    mood
                ))
        except Exception as e:
            logger.debug(f"Life log error: {e}")

    def get_life_history(self, category: str = None, hours: int = None,
                         days: int = None, limit: int = 100) -> List[Dict]:
        """
        Holt die Life-Events.

        Args:
            category: Optional - nur Events dieser Kategorie
            hours: Zeitraum in Stunden (z.B. 24 für letzten Tag)
            days: Zeitraum in Tagen (z.B. 30 für letzten Monat)
            limit: Max Anzahl (default: 100)

        Returns:
            Liste von Life-Events

        Beispiele:
            get_life_history(hours=24)        # Letzte 24 Stunden
            get_life_history(days=7)          # Letzte Woche
            get_life_history(days=30)         # Letzter Monat
            get_life_history(days=365)        # Letztes Jahr
            get_life_history(limit=1000)      # Alle (bis 1000)
        """
        try:
            with self._get_connection() as conn:
                conn.row_factory = sqlite3.Row

                # Zeitfilter berechnen
                if hours:
                    cutoff = (datetime.now() - timedelta(hours=hours)).isoformat()
                elif days:
                    cutoff = (datetime.now() - timedelta(days=days)).isoformat()
                else:
                    cutoff = None

                if cutoff and category:
                    rows = conn.execute("""
                        SELECT * FROM holo_life_log
                        WHERE timestamp > ? AND category = ?
                        ORDER BY timestamp DESC LIMIT ?
                    """, (cutoff, category, limit)).fetchall()
                elif cutoff:
                    rows = conn.execute("""
                        SELECT * FROM holo_life_log
                        WHERE timestamp > ?
                        ORDER BY timestamp DESC LIMIT ?
                    """, (cutoff, limit)).fetchall()
                elif category:
                    rows = conn.execute("""
                        SELECT * FROM holo_life_log
                        WHERE category = ?
                        ORDER BY timestamp DESC LIMIT ?
                    """, (category, limit)).fetchall()
                else:
                    rows = conn.execute("""
                        SELECT * FROM holo_life_log
                        ORDER BY timestamp DESC LIMIT ?
                    """, (limit,)).fetchall()

                return [dict(row) for row in rows]
        except Exception as e:
            logger.debug(f"Life history error: {e}")
            return []

    def get_life_summary(self, hours: int = None, days: int = None) -> Dict:
        """
        Erstellt eine Zusammenfassung des autonomen Lebens.

        Args:
            hours: Zeitraum in Stunden
            days: Zeitraum in Tagen

        Returns:
            Dict mit Statistiken und Highlights
        """
        try:
            events = self.get_life_history(hours=hours, days=days, limit=500)

            # Kategorien zählen
            categories = {}
            for event in events:
                cat = event.get("category", "unknown")
                categories[cat] = categories.get(cat, 0) + 1

            # Events pro Tag
            events_per_day = {}
            for event in events:
                ts = event.get("timestamp", "")[:10]  # YYYY-MM-DD
                events_per_day[ts] = events_per_day.get(ts, 0) + 1

            # Durchschnittliche Energie
            energies = [e.get("energy_level") for e in events if e.get("energy_level")]
            avg_energy = sum(energies) / len(energies) if energies else 0.5

            # Letzte Events pro Kategorie
            latest_by_category = {}
            for event in events:
                cat = event.get("category", "unknown")
                if cat not in latest_by_category:
                    latest_by_category[cat] = event

            return {
                "total_events": len(events),
                "time_period": f"{days} Tage" if days else f"{hours} Stunden" if hours else "Alle",
                "categories": categories,
                "events_per_day": events_per_day,
                "average_energy": round(avg_energy, 2),
                "latest_by_category": latest_by_category,
                "most_active": max(categories, key=categories.get) if categories else None,
                "least_active": min(categories, key=categories.get) if categories else None
            }
        except Exception as e:
            logger.debug(f"Life summary error: {e}")
            return {"total_events": 0, "categories": {}}

