class PiCommunicator:
    def __init__(self, memory: MemoryStore):
        self.memory = memory
        self._pi_api_url = "http://localhost:8008"
        self._cached_status: Dict = {}
        self._cache_time: float = 0
        self._cache_ttl: float = 5.0
        self._ensure_files()
        self.pi = PiControlBridge(self._pi_api_url)
        try:
            self.nlp = NaturalLanguageHelper(self.pi)
        except TypeError:
            self.nlp = NaturalLanguageHelper()

        # Check if we have access to StateDatabase via MemoryStoreWrapper
        self.db_manager = getattr(memory, 'db', None)
        logger.info("PiCommunicator bereit")

    def _ensure_files(self):
        os.makedirs(BrainConfig.STATE_DIR, exist_ok=True)
        if not BrainConfig.HOLO_TO_PI.exists():
            BrainConfig.HOLO_TO_PI.write_text(json.dumps({"commands": []}))

    def create_suggestion(self, action: str, parameters: Dict, reason: str, priority: CommandPriority = CommandPriority.NORMAL) -> HoloCommand:
        cmd_type = CommandType.NOTIFICATION if action == "send_notification" else CommandType.SUGGESTION
        return HoloCommand(
            f"cmd_{int(time.time())}_{random.randint(100,999)}",
            cmd_type, action, parameters, reason, priority
        )

    def send_command(self, cmd: HoloCommand) -> bool:
        try:
            # Load existing commands from StateDatabase or JSON
            data = {"commands": [], "timestamp": datetime.now().isoformat()}

            # Try StateDatabase first
            if self.db_manager:
                try:
                    db_data = self.db_manager.state.load_state('pi_communication_holo_to_pi')
                    if db_data:
                        data = db_data
                        logger.debug("Loaded holo_to_pi from StateDatabase")
                except Exception as e:
                    logger.debug(f"StateDB load failed: {e}")

            # Fallback to JSON file
            if not data.get("commands") and BrainConfig.HOLO_TO_PI.exists():
                try:
                    data = json.loads(BrainConfig.HOLO_TO_PI.read_text())
                except Exception as e:
                    logger.debug(f"JSON load failed: {e}")

            # Add new command
            data["commands"].append(cmd.to_dict())
            data["timestamp"] = datetime.now().isoformat()

            # Save to StateDatabase first
            if self.db_manager:
                try:
                    self.db_manager.state.save_state('pi_communication_holo_to_pi', data)
                    logger.debug("Saved holo_to_pi to StateDatabase")
                except Exception as e:
                    logger.debug(f"StateDB save failed: {e}")

            # Also save to JSON file as backup
            BrainConfig.HOLO_TO_PI.write_text(json.dumps(data, indent=2))

            # Direct HTTP Push
            try:
                requests.post(f"{self._pi_api_url}/api/command", json=cmd.to_dict(), timeout=1)
            except Exception as e:
                logger.debug(f"Direct HTTP push to Pi failed (non-critical): {e}")

            logger.info(f"Gesendet: {cmd.action} ({cmd.id})")
            return True
        except Exception as e:
            logger.error(f"Send failed: {e}")
            return False

    def send_notification(self, title: str, message: str, priority: CommandPriority = CommandPriority.NORMAL):
        """Sendet eine Benachrichtigung ans Dashboard/Pi"""
        cmd = self.create_suggestion(
            "send_notification",
            {"title": title, "message": message, "sound": priority.value >= 3},
            f"Holo-Notification: {title}",
            priority
        )
        return self.send_command(cmd)

    def request_nas_wake(self, reason: str = "Holo") -> dict:
        """NAS aufwecken - Pi-Control entscheidet!"""
        return self.pi.wake_nas(reason)

    def request_nas_suspend(self, reason: str = "Holo") -> dict:
        """NAS schlafen legen - Pi-Control entscheidet!"""
        return self.pi.suspend_nas(reason)

    def get_nas_status(self) -> dict:
        return self.pi.nas_status

    def is_nas_online(self) -> bool:
        return self.pi.nas_online

    def create_calendar_event(
        self,
        summary: str,
        start_datetime: str,
        end_datetime: str,
        description: str = "",
        location: str = ""
    ) -> dict:
        """Erstellt einen Kalender-Eintrag"""
        return self.pi.create_calendar_event(
            summary=summary,
            start_datetime=start_datetime,
            end_datetime=end_datetime,
            description=description,
            location=location
        )

    def call_skill(self, skill_name: str, method: str, params: dict = None) -> dict:
        return self.pi.skill(skill_name, method, params)

    def get_news(self, limit: int = 5) -> dict:
        return self.pi.get_news(limit)

    def get_pi_status(self) -> Dict:
        """Holt Status vom Pi-Control (mit Cache)"""
        now = time.time()

        if self._cached_status and (now - self._cache_time) < self._cache_ttl:
            return self._cached_status

        try:
            resp = requests.get(f"{self._pi_api_url}/api/state", timeout=3)
            if resp.status_code == 200:
                data = resp.json()
                data["_heartbeat_ok"] = True
                data["_source"] = "http_api"
                self._cached_status = data
                self._cache_time = now
                return data
        except Exception as e:
            logger.debug(f"HTTP API nicht erreichbar: {e}")

        # Try StateDatabase first
        if self.db_manager:
            try:
                data = self.db_manager.state.load_state('ultimate_state')
                if data:
                    ts = data.get("timestamp", "")
                    if ts:
                        age = (datetime.now() - datetime.fromisoformat(ts)).total_seconds()
                        data["_heartbeat_ok"] = age < 120
                    else:
                        data["_heartbeat_ok"] = False
                    data["_source"] = "state_database"
                    self._cached_status = data
                    self._cache_time = now
                    logger.debug("Loaded ultimate_state from StateDatabase")
                    return data
            except Exception as e:
                logger.debug(f"StateDB load failed: {e}")

        # Fallback: JSON file
        if BrainConfig.STATE_FILE.exists():
            try:
                data = json.loads(BrainConfig.STATE_FILE.read_text())
                ts = data.get("timestamp", "")
                if ts:
                    age = (datetime.now() - datetime.fromisoformat(ts)).total_seconds()
                    data["_heartbeat_ok"] = age < 120
                else:
                    data["_heartbeat_ok"] = False
                data["_source"] = "json_file"
                self._cached_status = data
                self._cache_time = now
                return data
            except Exception:
                pass

        return {"_heartbeat_ok": False, "_source": "none"}

    def check_feedback(self) -> List[PiFeedback]:
        data = None

        # Try StateDatabase first
        if self.db_manager:
            try:
                data = self.db_manager.state.load_state('pi_communication_pi_to_holo')
                if data:
                    logger.debug("Loaded pi_to_holo from StateDatabase")
            except Exception as e:
                logger.debug(f"StateDB load failed: {e}")

        # Fallback to JSON file
        if not data and BrainConfig.PI_TO_HOLO.exists():
            try:
                data = json.loads(BrainConfig.PI_TO_HOLO.read_text())
            except Exception as e:
                logger.debug(f"JSON load failed: {e}")

        if data and data.get("feedbacks"):
            feedbacks = [PiFeedback(f["command_id"], f.get("accepted"), f.get("executed"), f.get("result")) for f in data["feedbacks"]]

            # Clear feedbacks after reading
            empty_data = {"feedbacks": []}

            # Save to StateDatabase
            if self.db_manager:
                try:
                    self.db_manager.state.save_state('pi_communication_pi_to_holo', empty_data)
                    logger.debug("Cleared pi_to_holo in StateDatabase")
                except Exception as e:
                    logger.debug(f"StateDB save failed: {e}")

            # Also clear JSON file
            BrainConfig.PI_TO_HOLO.write_text(json.dumps(empty_data))

            return feedbacks

        return []


