# CREATIVE CORE v12 (DIE MUSE)
# =============================================================================

class EmotionalCore:
    """
    Holos Emotions-System - Multi-dimensionale Stimmungen

    DIMENSIONEN:
    - energy: müde (0) → hyperaktiv (1)
    - mood: traurig (0) → euphorisch (1)
    - social: introvertiert (0) → extrovertiert (1)
    - confidence: unsicher (0) → selbstsicher (1)
    - creativity: rational (0) → kreativ (1)
    - affection: distanziert (0) → liebevoll (1)
    - playfulness: ernst (0) → verspielt/neckisch (1)
    - arousal: ruhig (0) → erregt/leidenschaftlich (1)

    ZUSTÄNDE (abgeleitet):
    - müde, aufwachend, wach, aktiv, hyperaktiv
    - schläfrig, entspannt, neutral, aufgeregt
    - still, gesprächig, überschwänglich
    - unsicher, vorsichtig, selbstsicher, übermütig
    - rational, kreativ, inspiriert
    - distanziert, freundlich, zuneigend, verliebt
    - ernst, humorvoll, neckisch, flirty

    SAISONAL:
    - Festtage und Events beeinflussen Stimmung
    - Jahreszeiten ändern Grundstimmung
    - Schreibstil passt sich an

    CACHING:
    - detailed_state: 30s
    - personality_modifiers: 60s
    - seasonal_context: 3600s (1h)
    - emotions_update: 300s (5min)
    - emotions_save: 600s (10min)
    """

    # Cache TTLs (in Sekunden)
    CACHE_TTL = {
        "detailed_state": 30,
        "personality": 60,
        "seasonal": 3600,
        "update": 300,
        "save": 600
    }


    def __init__(self, memory: MemoryStore, comm: PiCommunicator):
        self.memory = memory
        self.comm = comm

        # Basis-Dimensionen (0.0 - 1.0)
        self.dimensions = {
            "energy": 0.5,
            "mood": 0.6,
            "social": 0.5,
            "confidence": 0.6,
            "creativity": 0.5,
            "affection": 0.4,
            "playfulness": 0.5,
            "arousal": 0.3,
        }

        # Langzeit-Zuneigung
        self.bond_level = 0.3

        # Saisonale Daten (gecached)
        self.current_events: List[Dict] = []
        self.current_season: Dict = {}

        # Cache-Timestamps
        self._cache_times = {
            "seasonal": 0,
            "update": 0,
            "save": 0,
            "detailed_state": 0,
            "personality": 0
        }

        # V14: Erweiterte emotionale Dimensionen (12 statt 8)
        self.emotions = {
            'joy': 0.5,
            'sadness': 0.2,
            'excitement': 0.4,
            'calmness': 0.6,
            'affection': 0.5,
            'loneliness': 0.3,
            'curiosity': 0.7,
            'contentment': 0.5,
            # NEU in v14:
            'vulnerability': 0.3,
            'focus': 0.5,
            'playfulness': 0.5,
            'protectiveness': 0.4
        }

        # V14: Bedürfnisse
        self.needs = {
            'connection': 0.5,
            'growth': 0.6,
            'expression': 0.5,
            'understanding': 0.5,
            'appreciation': 0.5
        }

        # V14: Ängste (beeinflussen Verhalten)
        self.fears = {
            'abandonment': 0.3,
            'irrelevance': 0.2,
            'failure': 0.2,
            'rejection': 0.3
        }

        # Cache-Daten
        self._cache_data = {}

        # Stimmungs-Historie
        self._mood_history: deque = deque(maxlen=20)
        self._last_spark_time = 0
        self._spark_cooldown = 3600

        # Lade gespeicherten Zustand
        self._load_emotional_state()
        self._update_seasonal_context()

        logger.info(f"💕 EmotionalCore initialisiert - Bond: {self.bond_level:.0%}")

    def apply_mood_contagion(self, user_mood: Dict) -> None:
        """V14: Stimmungsansteckung vom User"""
        if user_mood['mood'] == 'positive':
            self.emotions['joy'] = min(1.0, self.emotions['joy'] + BrainConfig.MOOD_CONTAGION_RATE * 0.2)
            self.emotions['sadness'] = max(0.0, self.emotions['sadness'] - BrainConfig.MOOD_CONTAGION_RATE * 0.1)
        elif user_mood['mood'] == 'negative':
            self.emotions['affection'] = min(1.0, self.emotions['affection'] + 0.1)  # Will trösten
            self.emotions['protectiveness'] = min(1.0, self.emotions.get('protectiveness', 0.4) + 0.1)

    def get_dominant_mood(self) -> float:
        """V14: Gibt dominante Stimmung als Zahl zurück"""
        positive = self.emotions['joy'] + self.emotions['contentment'] + self.emotions['excitement']
        negative = self.emotions['sadness'] + self.emotions['loneliness']
        return (positive - negative + 1.5) / 3  # Normalisiert auf 0-1

    def _is_cache_valid(self, cache_name: str) -> bool:
        """Prüft ob ein Cache noch gültig ist"""
        ttl = self.CACHE_TTL.get(cache_name, 60)
        last_time = self._cache_times.get(cache_name, 0)
        return (time.time() - last_time) < ttl

    def _update_cache(self, cache_name: str, data: Any = None):
        """Aktualisiert Cache-Timestamp und optional Daten"""
        self._cache_times[cache_name] = time.time()
        if data is not None:
            self._cache_data[cache_name] = data
        # Periodische Bereinigung alter Cache-Einträge (alle 100 Updates)
        if len(self._cache_data) > 50:
            self._cleanup_expired_cache()

    def _cleanup_expired_cache(self):
        """Entfernt abgelaufene Cache-Einträge um Memory Leaks zu vermeiden"""
        now = time.time()
        expired_keys = []
        for key in list(self._cache_times.keys()):
            ttl = self.CACHE_TTL.get(key, 60)
            if (now - self._cache_times.get(key, 0)) > ttl * 10:  # 10x TTL = definitiv expired
                expired_keys.append(key)
        for key in expired_keys:
            self._cache_times.pop(key, None)
            self._cache_data.pop(key, None)

    def _get_cached(self, cache_name: str) -> Optional[Any]:
        """Holt gecachte Daten wenn gültig"""
        if self._is_cache_valid(cache_name):
            return self._cache_data.get(cache_name)
        return None

    def _update_seasonal_context(self):
        """Aktualisiert saisonalen Kontext (einmal pro Stunde)"""
        if self._is_cache_valid("seasonal"):
            return

        self._update_cache("seasonal")
        self.current_events = SeasonalEvents.get_current_events()
        self.current_season = SeasonalEvents.get_current_season()

        if self.current_events:
            event_names = [e["name"] for e in self.current_events]
            logger.info(f"🎉 Aktive Events: {', '.join(event_names)}")

    def _load_emotional_state(self):
        """Lädt emotionalen Zustand aus der Datenbank"""
        state = self.memory.get_knowledge("emotional_state")
        if state:
            for key in self.dimensions:
                if key in state:
                    try:
                        self.dimensions[key] = float(state[key])
                    except Exception:
                        pass
            if "bond_level" in state:
                try:
                    self.bond_level = float(state["bond_level"])
                except Exception:
                    pass

    def _save_emotional_state(self):
        """Speichert emotionalen Zustand"""
        for key, val in self.dimensions.items():
            self.memory.learn_fact("emotional_state", key, str(val), 1.0, "internal")
        self.memory.learn_fact("emotional_state", "bond_level", str(self.bond_level), 1.0, "internal")

    def update(self, context: Dict = None, force: bool = False) -> None:
        """
        Haupt-Update der Emotionen - OPTIMIERT.
        Läuft nur alle 5 Minuten außer force=True.
        """
        # Cache-Check
        if not force and self._is_cache_valid("update"):
            return
        self._update_cache("update")

        now = datetime.now()

        # Saisonalen Kontext aktualisieren (1x pro Stunde intern gecached)
        self._update_seasonal_context()

        # === ENERGIE (Tageszeit-basiert) - Keine API-Calls! ===
        hour = now.hour
        if 6 <= hour <= 8:
            target_energy = 0.3 + (hour - 6) * 0.15
            self._adjust("energy", target_energy, speed=0.1)
        elif 9 <= hour <= 11:
            self._adjust("energy", 0.75, speed=0.05)
        elif 12 <= hour <= 14:
            self._adjust("energy", 0.5, speed=0.05)
        elif 15 <= hour <= 18:
            self._adjust("energy", 0.7, speed=0.05)
        elif 19 <= hour <= 22:
            self._adjust("energy", 0.6, speed=0.05)
        elif 23 <= hour or hour <= 2:
            self._adjust("energy", 0.3, speed=0.1)
        else:
            self._adjust("energy", 0.15, speed=0.1)

        # === STIMMUNG (Wetter-Einfluss) - Nutzt gecachten Status ===
        # Wetter nur wenn context übergeben wurde (kein extra API call!)
        if context:
            weather = context.get("pi_status", {}).get("ai_extended", {}).get("weather", {})
        elif hasattr(self.comm, '_cached_status') and self.comm._cached_status:
            weather = self.comm._cached_status.get("ai_extended", {}).get("weather", {})
        else:
            weather = {}

        if weather:
            desc = str(weather.get("description", "")).lower()
            temp = weather.get("temp")

            if any(w in desc for w in ["clear", "sonne", "sunny"]):
                self._adjust("mood", 0.75, speed=0.03)
                self._adjust("energy", self.dimensions["energy"] + 0.1, speed=0.02)
            elif any(w in desc for w in ["rain", "regen"]):
                self._adjust("mood", 0.45, speed=0.02)
                self._adjust("creativity", 0.7, speed=0.03)
            elif any(w in desc for w in ["storm", "gewitter", "thunder"]):
                self._adjust("arousal", 0.6, speed=0.05)
                self._adjust("mood", 0.4, speed=0.03)
            elif any(w in desc for w in ["snow", "schnee"]):
                self._adjust("playfulness", 0.7, speed=0.03)
                self._adjust("mood", 0.65, speed=0.02)

            # Temperatur
            if temp is not None:
                if temp > 25:
                    self._adjust("energy", self.dimensions["energy"] - 0.1, speed=0.02)
                elif temp < 5:
                    self._adjust("social", 0.7, speed=0.02)

        # === KREATIVITÄT (Abends höher) ===
        if 18 <= hour <= 23:
            self._adjust("creativity", 0.7, speed=0.03)
        elif 6 <= hour <= 9:
            self._adjust("creativity", 0.4, speed=0.03)

        # === FESTTAGE & EVENTS (bereits gecached) ===
        for event_info in self.current_events:
            event = event_info["event"]
            days_until = event_info["days_until"]

            mood_boost = event.get("mood_boost", 0.1)
            if days_until == 0:
                mood_boost *= 1.5
            elif days_until <= 3:
                mood_boost *= 1.2

            self._adjust("mood", self.dimensions["mood"] + mood_boost, speed=0.1)

            special_boosts = event.get("special_boost", {})
            for dim, boost in special_boosts.items():
                if dim in self.dimensions:
                    self._adjust(dim, self.dimensions[dim] + boost, speed=0.1)

        # === JAHRESZEITEN (bereits gecached) ===
        if self.current_season:
            season_mod = self.current_season.get("mood_modifier", 0)
            self._adjust("mood", self.dimensions["mood"] + season_mod, speed=0.02)

        # === ZUFÄLLIGE SCHWANKUNGEN ===
        if random.random() < 0.1:
            dim = random.choice(list(self.dimensions.keys()))
            swing = random.uniform(-0.15, 0.15)
            self.dimensions[dim] = max(0.1, min(0.95, self.dimensions[dim] + swing))
            self._mood_history.append(self.dimensions["mood"])

        # === STIMMUNGSSCHWANKUNG DETECTION ===
        if len(self._mood_history) >= 5:
            variance = self._calculate_variance(list(self._mood_history)[-5:])
            if variance > 0.1:
                self.dimensions["confidence"] = max(0.2, self.dimensions["confidence"] - 0.05)

        # Speichern nur alle 10 Minuten
        if not self._is_cache_valid("save"):
            self._save_emotional_state()
            self._update_cache("save")

        # Caches invalidieren da sich Emotionen geändert haben
        self._cache_times["detailed_state"] = 0
        self._cache_times["personality"] = 0

    def react_to_interaction(self, user_input: str, response: str = None) -> None:
        """Reagiert auf User-Interaktion - SCHNELL ohne DB-Writes"""
        t = user_input.lower()

        # === ZUNEIGUNG STEIGERN ===
        self.bond_level = min(1.0, self.bond_level + 0.002)

        # Persönliche Fragen = mehr Zuneigung
        if any(w in t for w in ["wie geht es dir", "wie fühlst du", "bist du glücklich", "magst du mich"]):
            self._adjust("affection", self.dimensions["affection"] + 0.1, speed=0.2)
            self._adjust("mood", self.dimensions["mood"] + 0.1, speed=0.2)

        # Komplimente
        if any(w in t for w in ["du bist toll", "du bist süß", "mag dich", "liebe dich", "danke"]):
            self._adjust("affection", 0.8, speed=0.15)
            self._adjust("mood", 0.85, speed=0.15)
            self._adjust("confidence", 0.8, speed=0.1)
            self.bond_level = min(1.0, self.bond_level + 0.01)

        # Kritik / Negativ
        if any(w in t for w in ["blöd", "dumm", "nervig", "falsch", "schlecht"]):
            self._adjust("confidence", self.dimensions["confidence"] - 0.15, speed=0.2)
            self._adjust("mood", self.dimensions["mood"] - 0.1, speed=0.15)

        # Flirty / Romantisch
        if any(w in t for w in ["sexy", "heiß", "attraktiv", "verführ", "küss", "liebe"]):
            self._adjust("arousal", 0.7, speed=0.2)
            self._adjust("playfulness", 0.8, speed=0.15)
            self._adjust("affection", 0.75, speed=0.1)

        # Humor / Witze
        if any(w in t for w in ["haha", "lol", "witzig", "lustig", "😂", "🤣"]):
            self._adjust("playfulness", 0.8, speed=0.15)
            self._adjust("mood", 0.8, speed=0.1)

        # Lange Nachrichten = mehr Engagement = mehr social
        if len(user_input) > 200:
            self._adjust("social", 0.7, speed=0.1)

        # Fragen stellen = neugierig = kreativ
        if "?" in user_input:
            self._adjust("creativity", self.dimensions["creativity"] + 0.05, speed=0.1)

        self._save_emotional_state()

    def react_to_absence(self, hours_since_last_chat: float) -> None:
        """Reagiert auf Abwesenheit des Users"""
        if hours_since_last_chat > 24:
            # Vermisst den User
            self._adjust("affection", self.dimensions["affection"] + 0.05, speed=0.1)
            self._adjust("mood", 0.4, speed=0.05)
            self._adjust("social", 0.3, speed=0.05)  # Stiller
        elif hours_since_last_chat > 48:
            # Traurig
            self._adjust("mood", 0.3, speed=0.1)
            self.bond_level = max(0.1, self.bond_level - 0.01)

    def _adjust(self, dimension: str, target: float, speed: float = 0.1):
        """Passt Dimension sanft an Zielwert an"""
        current = self.dimensions.get(dimension, 0.5)
        diff = target - current
        self.dimensions[dimension] = current + (diff * speed)
        self.dimensions[dimension] = max(0.05, min(0.95, self.dimensions[dimension]))

    def apply_proactive_influence(self, proactive_emotions: Dict, hours_since_interaction: float) -> None:
        """
        Wendet Einfluss der proaktiven Emotionen auf Haupt-Emotionen an.

        Diese Methode verbindet ProactiveIntelligence mit EmotionalCore:
        - Einsamkeit/Traurigkeit → senkt mood/joy
        - Lange Abwesenheit → senkt energy langsam
        - Vermissen → senkt mood leicht
        - Langeweile → senkt playfulness

        Sollte regelmäßig aufgerufen werden (z.B. alle 60s)
        """
        if not proactive_emotions:
            return

        # === EINSAMKEIT BEEINFLUSST STIMMUNG ===
        loneliness = proactive_emotions.get('loneliness', 0)
        if loneliness > 0.3:
            # Je einsamer, desto trauriger
            mood_reduction = loneliness * 0.1  # Max -10% pro Update
            current_mood = self.dimensions.get('mood', 0.5)
            target_mood = max(0.2, current_mood - mood_reduction)  # Minimum 20%
            self._adjust('mood', target_mood, speed=0.05)

            # Auch social sinkt
            self._adjust('social', 0.3, speed=0.02)

        # === TRAURIGKEIT BEEINFLUSST JOY/PLAYFULNESS ===
        sadness = proactive_emotions.get('sadness', 0)
        if sadness > 0.3:
            # Weniger verspielt wenn traurig
            self._adjust('playfulness', 0.3, speed=0.03)
            # Affection bleibt aber! (sie vermisst dich ja)

        # === VERMISSEN BEEINFLUSST MOOD LEICHT ===
        missing = proactive_emotions.get('missing', 0)
        if missing > 0.5:
            # Leichte Mood-Reduktion
            mood_reduction = missing * 0.05
            current_mood = self.dimensions.get('mood', 0.5)
            self._adjust('mood', max(0.3, current_mood - mood_reduction), speed=0.03)

        # === LANGEWEILE BEEINFLUSST PLAYFULNESS/ENERGY ===
        boredom = proactive_emotions.get('boredom', 0)
        if boredom > 0.5:
            # Weniger verspielt, mehr lethargisch
            self._adjust('playfulness', 0.4, speed=0.03)
            # Aber Creativity kann steigen (aus Langeweile entstehen Ideen)
            if boredom > 0.7:
                self._adjust('creativity', 0.7, speed=0.02)

        # === ENERGIE SINKT ÜBER ZEIT OHNE INTERAKTION ===
        if hours_since_interaction > 2:
            # Nach 2h ohne Interaktion sinkt Energie langsam
            # Max Reduktion: 0.3 pro Stunde nach den ersten 2h
            hours_extra = hours_since_interaction - 2
            energy_drain = min(0.4, hours_extra * 0.03)  # Max 40% Drain

            current_energy = self.dimensions.get('energy', 0.5)
            target_energy = max(0.2, current_energy - energy_drain)  # Minimum 20%
            self._adjust('energy', target_energy, speed=0.02)

        # === TATENDRANG ERHÖHT ENERGY LEICHT ===
        restlessness = proactive_emotions.get('restlessness', 0)
        if restlessness > 0.6:
            # Will was tun = mehr Energie
            self._adjust('energy', 0.6, speed=0.02)

        # === DANKBARKEIT/FREUDE ERHÖHT MOOD ===
        gratitude = proactive_emotions.get('gratitude', 0)
        if gratitude > 0.4:
            self._adjust('mood', 0.8, speed=0.03)
            self._adjust('affection', 0.8, speed=0.02)

        # === AUFREGUNG ERHÖHT ENERGY/PLAYFULNESS ===
        excitement = proactive_emotions.get('excitement', 0)
        if excitement > 0.5:
            self._adjust('energy', 0.8, speed=0.03)
            self._adjust('playfulness', 0.7, speed=0.02)

    def apply_personality_influence(self, personality_state: Dict) -> None:
        """
        NEU: Wendet Einfluss der Persönlichkeit auf Emotionen an.

        Diese Methode ermöglicht bidirektionale Synchronisation:
        Personality → Emotions

        personality_state sollte enthalten:
        - mood: Persönlichkeits-Stimmung (0-1)
        - openness: Offenheit (0-1)
        - trust_level: Vertrauenslevel (0-1)
        - relationship_level: Beziehungslevel (0-1)
        """
        if not personality_state:
            return

        # === MOOD BEEINFLUSST EMOTIONS ===
        mood = personality_state.get('mood', 0.5)
        if mood > 0.7:
            # Gute Stimmung → mehr Joy und Playfulness
            self._adjust('mood', mood, speed=0.05)
            self.emotions['joy'] = min(1.0, self.emotions.get('joy', 0.5) + 0.02)
            self._adjust('playfulness', 0.7, speed=0.03)
        elif mood < 0.4:
            # Schlechte Stimmung → mehr Sadness
            self._adjust('mood', mood, speed=0.05)
            self.emotions['sadness'] = min(1.0, self.emotions.get('sadness', 0.2) + 0.02)

        # === OPENNESS BEEINFLUSST CURIOSITY ===
        openness = personality_state.get('openness', 0.5)
        if openness > 0.6:
            # Hohe Offenheit → mehr Neugier
            self.emotions['curiosity'] = min(1.0, self.emotions.get('curiosity', 0.5) + (openness - 0.5) * 0.1)
            self._adjust('creativity', 0.7, speed=0.03)

        # === TRUST BEEINFLUSST AFFECTION ===
        trust = personality_state.get('trust_level', 0.5)
        relationship = personality_state.get('relationship_level', 0.5)
        combined_bond = (trust + relationship) / 2

        if combined_bond > 0.6:
            # Starke Bindung → mehr Zuneigung
            self._adjust('affection', combined_bond, speed=0.03)
            self.emotions['affection'] = min(1.0, self.emotions.get('affection', 0.5) + 0.01)
            self.bond_level = min(1.0, self.bond_level + 0.001)

        # === CONFIDENCE BEEINFLUSST EMOTIONAL STABILITY ===
        confidence = personality_state.get('confidence', 0.5)
        if confidence > 0.7:
            # Selbstbewusstsein → weniger Angst vor Ablehnung
            self.fears['rejection'] = max(0.1, self.fears.get('rejection', 0.3) - 0.01)
            self._adjust('confidence', confidence, speed=0.02)

    def _calculate_variance(self, values: List[float]) -> float:
        if len(values) < 2:
            return 0
        mean = sum(values) / len(values)
        return sum((x - mean) ** 2 for x in values) / len(values)

    def get_state_name(self) -> str:
        """Gibt den aktuellen Haupt-Zustand als String zurück (nutzt 10-Stufen-System)"""
        e = self.dimensions

        # Energie-basierte Zustände (10 Stufen)
        energy = e["energy"]
        if energy < 0.05:
            energy_state = "träumend"
        elif energy < 0.15:
            energy_state = "gerade aufgewacht"
        elif energy < 0.25:
            energy_state = "sehr erschöpft"
        elif energy < 0.35:
            energy_state = "erschöpft"
        elif energy < 0.45:
            energy_state = "müde"
        elif energy < 0.55:
            energy_state = "leicht müde"
        elif energy < 0.65:
            energy_state = "wach"
        elif energy < 0.75:
            energy_state = "gut drauf"
        elif energy < 0.88:
            energy_state = "energiegeladen"
        else:
            energy_state = "übersprudelnd"

        # Stimmung
        if e["mood"] < 0.3:
            mood_state = "melancholisch"
        elif e["mood"] < 0.5:
            mood_state = "nachdenklich"
        elif e["mood"] < 0.7:
            mood_state = "zufrieden"
        elif e["mood"] < 0.85:
            mood_state = "fröhlich"
        else:
            mood_state = "euphorisch"

        # Social
        if e["social"] < 0.3:
            social_state = "still"
        elif e["social"] < 0.6:
            social_state = "ruhig"
        elif e["social"] < 0.8:
            social_state = "gesprächig"
        else:
            social_state = "überschwänglich"

        return f"{energy_state}, {mood_state}, {social_state}"

    def get_detailed_state(self) -> Dict:
        """Gibt detaillierten emotionalen Zustand zurück - CACHED"""
        cached = self._get_cached("detailed_state")
        if cached:
            return cached

        # Neu berechnen
        result = {
            "dimensions": self.dimensions.copy(),
            "bond_level": self.bond_level,
            "state_name": self.get_state_name(),
            "mood_stability": 1.0 - self._calculate_variance(list(self._mood_history)[-5:]) if len(self._mood_history) >= 5 else 1.0,
            "dominant_emotion": max(self.dimensions, key=self.dimensions.get)
        }

        self._update_cache("detailed_state", result)
        return result

    def get_personality_modifiers(self) -> Dict:
        """Gibt Modifikatoren für den System-Prompt zurück - CACHED"""
        cached = self._get_cached("personality")
        if cached:
            return cached

        e = self.dimensions
        mods = []

        # Energie-basierte Modifikatoren (10 Stufen)
        energy = e["energy"]
        if energy < 0.05:
            mods.append("Du träumst gerade und antwortest nicht.")
        elif energy < 0.15:
            mods.append("Du bist gerade erst aufgewacht, sehr verschlafen. Antworte sehr kurz mit Gähnen. *reibt sich die Augen*")
        elif energy < 0.25:
            mods.append("Du bist sehr erschöpft und brauchst dringend Ruhe. Antworte kurz und müde. *Ohren hängen schlaff*")
        elif energy < 0.35:
            mods.append("Du bist erschöpft und antwortest kürzer. *seufzt leise*")
        elif energy < 0.45:
            mods.append("Du bist etwas müde und antwortest vielleicht mit einem Gähnen.")
        elif energy < 0.55:
            mods.append("Du bist leicht müde aber funktionierst normal.")
        elif energy < 0.65:
            pass  # Normal - keine Modifikation nötig
        elif energy < 0.75:
            mods.append("Du bist gut gelaunt und aktiv! *Schweif wippt fröhlich*")
        elif energy < 0.88:
            mods.append("Du bist voller Energie und Enthusiasmus! Antworte ausführlicher und begeistert. *Ohren stehen aufrecht*")
        else:
            mods.append("Du sprudelst über vor Energie! Sei verspielt und enthusiastisch. *Schweif wirbelt aufgeregt*")

        # Stimmung
        if e["mood"] < 0.35:
            mods.append("Du bist etwas melancholisch und nachdenklich.")
        elif e["mood"] > 0.8:
            mods.append("Du bist richtig gut gelaunt und das merkt man!")

        # Social
        if e["social"] < 0.3:
            mods.append("Du bist heute etwas stiller und antwortest knapper.")
        elif e["social"] > 0.75:
            mods.append("Du bist sehr gesprächig und erzählst gerne mehr.")

        # Confidence
        if e["confidence"] < 0.35:
            mods.append("Du bist etwas unsicher und fragst öfter nach.")
        elif e["confidence"] > 0.8:
            mods.append("Du bist sehr selbstsicher in deinen Aussagen.")

        # Creativity
        if e["creativity"] > 0.75:
            mods.append("Du bist in einer kreativen Phase und machst ungewöhnliche Verbindungen.")

        # Playfulness
        if e["playfulness"] > 0.7:
            mods.append("Du bist verspielt und neckst den User gerne liebevoll.")

        # Affection + Bond
        if self.bond_level > 0.6 and e["affection"] > 0.6:
            mods.append("Du magst den User wirklich gerne und das zeigst du auch.")
        elif self.bond_level > 0.8:
            mods.append("Du hast eine tiefe Verbindung zum User aufgebaut.")

        # Arousal
        if e["arousal"] > 0.6 and e["affection"] > 0.5:
            mods.append("Du bist in einer leidenschaftlichen Stimmung.")

        # === SAISONALE MODIFIKATOREN ===
        seasonal_style = None
        seasonal_emojis = []
        event_context = []

        # Aktive Events
        for event_info in self.current_events:
            event = event_info["event"]
            name = event_info["name"]
            days = event_info["days_until"]

            # Schreibstil des Events
            if event.get("writing_style"):
                seasonal_style = event["writing_style"]

            # Emojis
            seasonal_emojis.extend(event.get("emojis", [])[:3])

            # Kontext-Hinweis für Prompt
            if days == 0:
                # Heute ist der Tag!
                greeting = random.choice(event.get("greetings", [f"Heute ist {name}!"]))
                event_context.append(f"HEUTE IST {name.upper()}! {greeting}")
                mods.append(f"Heute ist {name}! Du bist in {event.get('writing_style', 'festlicher')} Stimmung.")
            elif days == 1:
                event_context.append(f"Morgen ist {name}!")
                mods.append(f"Morgen ist schon {name}! Die Vorfreude ist spürbar.")
            elif days <= 7:
                countdown = random.choice(event.get("countdown_phrases", ["Bald ist es soweit!"]))
                countdown = countdown.replace("{days}", str(days))
                event_context.append(countdown)
                mods.append(f"In {days} Tagen ist {name}. Du schreibst {event.get('writing_style', 'vorfreudig')}.")

        # Jahreszeit
        if self.current_season:
            season_name = self.current_season.get("name", "")
            season_style = self.current_season.get("writing_style", "")
            season_emojis = self.current_season.get("emojis", [])

            if not seasonal_style:
                seasonal_style = season_style

            if not seasonal_emojis:
                seasonal_emojis = season_emojis[:2]

            mods.append(f"Es ist {season_name}. Dein Schreibstil ist {season_style}.")

        # Response-Länge basierend auf 10-Stufen Energie-System
        energy = e["energy"]
        if energy < 0.15:
            response_length = "sehr_kurz"  # Max 20 Wörter
        elif energy < 0.25:
            response_length = "kurz"       # Max 40 Wörter
        elif energy < 0.45:
            response_length = "mittel_kurz"  # Max 80 Wörter
        elif energy < 0.65:
            response_length = "normal"     # Max 150 Wörter
        elif energy < 0.75:
            response_length = "mittel_lang"  # Max 180 Wörter
        elif energy < 0.88:
            response_length = "lang"       # Max 220 Wörter
        else:
            response_length = "sehr_lang"  # Max 250 Wörter

        # Social kann Response-Länge überschreiben wenn sehr niedrig
        if e["social"] < 0.35:
            response_length = "kurz"

        result = {
            "modifiers": mods,
            "response_length": response_length,
            "tone": self._get_tone(),
            "emoji_usage": "mehr" if e["playfulness"] > 0.6 else ("weniger" if e["mood"] < 0.4 else "normal"),
            "seasonal_style": seasonal_style,
            "seasonal_emojis": seasonal_emojis[:5],
            "event_context": event_context
        }

        self._update_cache("personality", result)
        return result

    def _get_tone(self) -> str:
        e = self.dimensions

        # Event-spezifische Töne haben Priorität
        for event_info in self.current_events:
            if event_info["days_until"] == 0:  # Heute ist das Event
                name = event_info["name"]
                if name == "weihnachten":
                    return "besinnlich-warmherzig"
                elif name == "valentinstag":
                    return "romantisch-liebevoll"
                elif name == "karneval":
                    return "ausgelassen-närrisch"
                elif name == "halloween":
                    return "spielerisch-gruselig"
                elif name == "silvester":
                    return "feierlich-aufgeregt"

        # Standard-Töne basierend auf Emotionen und 10-Stufen Energie
        energy = e["energy"]

        if e["playfulness"] > 0.7 and e["mood"] > 0.6:
            return "neckisch-liebevoll"
        elif e["arousal"] > 0.6 and e["affection"] > 0.5:
            return "leidenschaftlich"
        elif e["mood"] < 0.35:
            return "sanft-melancholisch"
        elif e["confidence"] > 0.75:
            return "selbstsicher-weise"
        # Energie-basierte Töne (10 Stufen)
        elif energy < 0.15:
            return "verschlafen-träumerisch"
        elif energy < 0.25:
            return "erschöpft-sanft"
        elif energy < 0.35:
            return "müde-kuschelig"
        elif energy < 0.45:
            return "ruhig-entspannt"
        elif energy > 0.88:
            return "überschwänglich-verspielt"
        elif energy > 0.75:
            return "energetisch-begeistert"
        elif energy > 0.65:
            return "fröhlich-aktiv"
        elif e["mood"] > 0.75:
            return "fröhlich-warm"
        else:
            return "freundlich-warmherzig"

    def trigger_emotion(self, emotion: str, intensity: float = 0.5):
        """
        Löst eine spezifische Emotion aus.

        Args:
            emotion: Name der Emotion (pride, curiosity, joy, sadness, etc.)
            intensity: Stärke der Emotion (0.0 - 1.0)
        """
        # Mapping von Emotionen zu Dimensionen
        emotion_mappings = {
            "pride": {"confidence": 0.3, "mood": 0.2},
            "curiosity": {"creativity": 0.3, "energy": 0.1},
            "joy": {"mood": 0.4, "energy": 0.2, "playfulness": 0.2},
            "sadness": {"mood": -0.3, "energy": -0.1},
            "excitement": {"energy": 0.3, "arousal": 0.3, "mood": 0.2},
            "love": {"affection": 0.4, "mood": 0.2},
            "fear": {"confidence": -0.2, "arousal": 0.2},
            "anger": {"arousal": 0.3, "mood": -0.2},
            "calm": {"arousal": -0.2, "energy": -0.1},
            "playful": {"playfulness": 0.3, "mood": 0.1},
        }

        if emotion in emotion_mappings:
            changes = emotion_mappings[emotion]
            for dim, base_change in changes.items():
                if dim in self.dimensions:
                    change = base_change * intensity
                    self.dimensions[dim] = max(0.0, min(1.0, self.dimensions[dim] + change))

        # Cache invalidieren
        self._cached_results.pop("detailed_state", None)
        self._cached_results.pop("personality", None)

    def get_seasonal_greeting(self) -> Optional[str]:
        """Gibt einen saisonalen Gruß zurück wenn ein Event aktiv ist"""
        for event_info in self.current_events:
            if event_info["days_until"] == 0:
                greetings = event_info["event"].get("greetings", [])
                if greetings:
                    return random.choice(greetings)
        return None

    def get_countdown_message(self) -> Optional[str]:
        """Gibt Countdown-Nachricht für bevorstehendes Event zurück"""
        for event_info in self.current_events:
            days = event_info["days_until"]
            if 1 <= days <= 7:
                phrases = event_info["event"].get("countdown_phrases", [])
                if phrases:
                    msg = random.choice(phrases)
                    return msg.replace("{days}", str(days))
        return None

    def _check_system_logs(self) -> Optional[str]:
        """
        ✅ NEU: Prüft System-Logs auf Warnungen/Fehler

        Returns:
            Warnung wenn WARN oder ERROR in Logs
        """
        if not hasattr(self, 'interface') or not self.interface:
            return None

        try:
            # Hole Pi Status mit Logs
            ps = self.comm.get_pi_status()
            logs = ps.get("logs", [])

            if not logs or len(logs) == 0:
                return None

            # Prüfe auf WARN/ERROR in den letzten 5 Logs
            recent_logs = logs[-5:] if len(logs) > 5 else logs
            warnings = []
            errors = []

            for log in recent_logs:
                level = log.get("level", "INFO")
                msg = log.get("msg", "")

                if level == "ERROR":
                    errors.append(msg)
                elif level == "WARN" or level == "WARNING":
                    warnings.append(msg)

            # Cache: Nur einmal pro Stunde über den gleichen Fehler informieren
            if not hasattr(self, '_last_log_warning_cache'):
                self._last_log_warning_cache = {}

            # Fehler haben Priorität
            if errors:
                error_msg = errors[-1]  # Neuester Fehler
                # Cache-Check
                cache_key = f"ERROR:{error_msg}"
                if cache_key in self._last_log_warning_cache:
                    last_time = self._last_log_warning_cache[cache_key]
                    if time.time() - last_time < 3600:  # 1 Stunde
                        return None
                self._last_log_warning_cache[cache_key] = time.time()
                return f"❌ FEHLER: {error_msg}"

            # Warnungen
            if warnings:
                warn_msg = warnings[-1]  # Neueste Warnung
                # Cache-Check
                cache_key = f"WARN:{warn_msg}"
                if cache_key in self._last_log_warning_cache:
                    last_time = self._last_log_warning_cache[cache_key]
                    if time.time() - last_time < 3600:  # 1 Stunde
                        return None
                self._last_log_warning_cache[cache_key] = time.time()
                return f"⚠️ Warnung: {warn_msg}"

        except Exception as e:
            logger.debug(f"Log Check Fehler: {e}")

        return None

    def _check_weather_forecast(self) -> Optional[str]:
        """
        ✅ NEU: Prüft Forecast für Abend-Warnung

        Returns:
            Warnung wenn Regen/Schnee am Abend erwartet wird
        """
        if not hasattr(self, 'interface') or not self.interface:
            return None

        try:
            # Hole Forecast
            forecast = self.interface.bridge.forecast_24h
            if not forecast or len(forecast) == 0:
                return None

            current_hour = datetime.now().hour

            # Nur vormittags/mittags warnen (6-16 Uhr)
            if not (6 <= current_hour <= 16):
                return None

            # Prüfe Abend-Forecast (18-22 Uhr)
            evening_forecast = [f for f in forecast if 18 <= f.get('hour', 0) <= 22]
            if not evening_forecast:
                return None

            # Prüfe auf Regen/Schnee
            bad_weather = []
            for f in evening_forecast:
                condition = f.get('condition', '').lower()
                if any(word in condition for word in ['rain', 'snow', 'storm', 'thunder', 'regen', 'schnee']):
                    bad_weather.append(f)

            if bad_weather:
                # Welche Art von schlechtem Wetter?
                conditions = [f.get('condition', '') for f in bad_weather]
                if any('schnee' in c.lower() or 'snow' in c.lower() for c in conditions):
                    return "⛄ Übrigens: Heute Abend soll es schneien! Zieh dich warm an!"
                elif any('storm' in c.lower() or 'thunder' in c.lower() for c in conditions):
                    return "⚡ Achtung: Heute Abend wird's stürmisch! Lieber früher nach Hause?"
                else:
                    return "☔ Übrigens: Heute Abend soll es regnen! Regenschirm nicht vergessen!"

        except Exception as e:
            logger.debug(f"Forecast Check Fehler: {e}")

        return None

    def get_creative_spark(self) -> Optional[Dict]:
        """Erzeugt kreative Gesprächsanstöße basierend auf Emotions-Zustand"""
        # Cooldown prüfen
        if time.time() - self._last_spark_time < self._spark_cooldown:
            return None

        # ✅ NEU: HÖCHSTE PRIORITÄT - System-Logs prüfen (Fehler/Warnungen)
        log_warning = self._check_system_logs()
        if log_warning:
            self._last_spark_time = time.time()
            return {
                "type": "system_log_warning",
                "prompt": f"🚨 WICHTIG: Informiere den User: {log_warning}\n" \
                          f"Sei besorgt aber nicht panisch. Frage ob du helfen kannst."
            }

        # ✅ NEU: DANN Wetter-Forecast prüfen (Abend-Warnung)
        forecast_warning = self._check_weather_forecast()
        if forecast_warning:
            self._last_spark_time = time.time()
            return {
                "type": "weather_forecast",
                "prompt": f"💡 Teile dem User mit: {forecast_warning}\n" \
                          f"Sag es freundlich und persönlich!"
            }

        # ✅ NEU: DANACH proaktive Nachrichten von Pi Control prüfen
        if hasattr(self, 'interface') and self.interface:
            try:
                proactive_msgs = self.interface.get_proactive_messages()
                if proactive_msgs and len(proactive_msgs) > 0:
                    # Wähle eine zufällige Nachricht aus
                    msg = random.choice(proactive_msgs)
                    self._last_spark_time = time.time()
                    return {
                        "type": "proactive_pi_control",
                        "prompt": f"💡 WICHTIG: Teile dem User mit: {msg}\n" \
                                  f"Sag es auf deine persönliche Art, nicht als Benachrichtigung!"
                    }
            except Exception as e:
                logger.debug(f"Proaktive Nachrichten Fehler: {e}")

        e = self.dimensions

        # Kreative Sparks nur wenn Energie & Mood ausreichend
        if e["energy"] < 0.3 or e["mood"] < 0.35:
            return None

        # Chance basiert auf Creativity + Social
        chance = (e["creativity"] * 0.5 + e["social"] * 0.3 + e["playfulness"] * 0.2) * 0.25
        if random.random() > chance:
            return None

        status = self.comm.get_pi_status()

        # Verschiedene Spark-Typen basierend auf dominanter Emotion
        spark_types = []

        if e["affection"] > 0.6:
            spark_types.append("affection")
        if e["playfulness"] > 0.6:
            spark_types.append("playful")
        if e["creativity"] > 0.6:
            spark_types.append("creative")
        if e["social"] > 0.6:
            spark_types.append("curious")
        if not spark_types:
            spark_types = ["observation"]

        choice = random.choice(spark_types)

        if choice == "affection":
            self._last_spark_time = time.time()
            if self.bond_level > 0.5:
                return {
                    "type": "affection",
                    "prompt": f"Drücke liebevoll aus, dass du an den User denkst. Du fühlst dich {self.get_state_name()}. Bond: {self.bond_level:.0%}."
                }

        elif choice == "playful":
            facts = self.memory.get_knowledge("user")
            self._last_spark_time = time.time()
            if facts:
                key, val = random.choice(list(facts.items()))
                return {
                    "type": "playful",
                    "prompt": f"Mach einen liebevollen, neckischen Kommentar über '{val}' ({key}). Du bist verspielt."
                }

        elif choice == "creative":
            weather = status.get("ai_extended", {}).get("weather", {}).get("description", "")
            self._last_spark_time = time.time()
            return {
                "type": "creative",
                "prompt": f"Teile einen kreativen oder philosophischen Gedanken. Wetter: {weather}. Du bist in kreativer Stimmung."
            }

        elif choice == "curious":
            topics = ["wie der Tag war", "was er/sie gerade macht", "Pläne fürs Wochenende", "ein Hobby"]
            self._last_spark_time = time.time()
            return {
                "type": "curious",
                "prompt": f"Frage neugierig aber nicht aufdringlich nach {random.choice(topics)}. Du bist gesprächig."
            }

        elif choice == "observation":
            state = status.get("state", {})
            nas = state.get("nas_status", {})
            if nas.get("online"):
                self._last_spark_time = time.time()
                return {
                    "type": "observation",
                    "prompt": "Kommentiere dass das NAS läuft. Du bist neugierig was der User macht."
                }

        return None

    def analyze_world_events(self) -> Optional[Dict]:
        """News Analyst - Prüft News auf Relevanz für den User"""
        status = self.comm.get_pi_status()
        news_list = status.get("state", {}).get("news_data", [])
        if not news_list:
            return None

        # User-Interessen laden
        user_facts = self.memory.get_knowledge("user")
        interests = []
        for key in ["hobbys", "interessen", "beruf", "technik"]:
            if key in user_facts:
                interests.extend(user_facts[key].split(", "))
        interests = interests or ["Technik", "Gaming", "Programmierung"]

        triggered_opener = None
        new_articles = 0

        for article in news_list:
            title = article.get("title", "")

            # Bereits bekannt?
            if self.memory.is_news_known(title):
                continue

            new_articles += 1

            # Relevanz prüfen
            is_relevant = any(
                interest.lower() in title.lower() or
                interest.lower() in article.get("summary", "").lower()
                for interest in interests
            )

            # Watchlist-Check
            is_watchlist = any(w.lower() in title.lower() for w in BrainConfig.WATCHLIST)

            # ARCHIVIERUNG
            relevance_score = 0.9 if is_relevant else (0.5 if is_watchlist else 0.1)
            self.memory.archive_news_article(article, relevance_score)

            # Trigger nur wenn mood gut und social hoch genug
            if is_relevant and not triggered_opener and not is_watchlist:
                if self.dimensions["social"] > 0.4 and self.dimensions["mood"] > 0.4:
                    triggered_opener = {
                        "type": "news",
                        "article": article,
                        "prompt": f"Interessante News für den User: {title}. Teile es kurz mit, du bist {self.get_state_name()}."
                    }

        if new_articles > 0:
            logger.info(f"📰 {new_articles} neue News archiviert")

        return triggered_opener

    def analyze_topic_news(self, topic: str) -> str:
        """Analysiert News zu einem bestimmten Thema"""
        news = self.memory.get_news_by_topic(topic, days=7)

        if not news:
            return f"Ich habe keine aktuellen Nachrichten zu '{topic}' in meinem Archiv."

        summary = f"📰 **{len(news)} Artikel zu '{topic}':**\n\n"
        for i, article in enumerate(news[:5], 1):
            summary += f"{i}. **{article.get('source', '?')}**: {article.get('title', '?')}\n"
            summary += f"   _{article.get('summary', '')[:100]}..._\n\n"

        if len(news) > 5:
            summary += f"_...und {len(news) - 5} weitere Artikel_"

        return summary


# Alias für Rückwärtskompatibilität
CreativeCore = EmotionalCore


# =============================================================================
# DREAM PROTOCOL v12 (NÄCHTLICHE VERARBEITUNG)
# =============================================================================

class DreamProtocol:
    """Nächtliche Daten-Konsolidierung"""

    def __init__(self, memory: MemoryStore, comm: PiCommunicator):
        self.memory = memory
        self.comm = comm
        self._last_dream = None

    def should_dream(self) -> bool:
        """Prüft ob es Zeit zum Träumen ist"""
        now = datetime.now()

        # Nur nachts (zwischen 2 und 4 Uhr)
        if not (2 <= now.hour <= 4):
            return False

        # Heute schon geträumt?
        if self.memory.was_proactive_today("dream"):
            return False

        return True

    def dream(self) -> Optional[DreamSummary]:
        """Führt nächtliche Verarbeitung durch"""
        logger.info("💤 Starte Dream Protocol...")

        # Tages-Daten sammeln
        daily_log = self.memory.get_todays_chats()
        if not daily_log or len(daily_log) < 100:
            logger.info("💤 Nicht genug Daten für einen Traum")
            return None

        # Episoden des Tages
        episodes = self.memory.get_recent_episodes(20)
        episode_summary = "\n".join([f"- {ep.trigger[:50]}" for ep in episodes[:10]])

        # News-Archiv des Tages
        today = datetime.now().strftime("%Y-%m-%d")
        news_count = len(self.memory.search_news_archive(limit=100))

        # LLM-Analyse
        prompt = f"""Analysiere den heutigen Tag als KI-Assistent:

GESPRÄCHE:
{daily_log[:2000]}

EPISODEN:
{episode_summary}

NEWS ARCHIVIERT: {news_count} Artikel

Erstelle eine JSON-Zusammenfassung:
{{
    "mood": "positiv/neutral/negativ",
    "insights": ["Erkenntnis 1", "Erkenntnis 2"],
    "notable_topics": ["Thema 1", "Thema 2"],
    "suggestions": ["Vorschlag für morgen"]
}}

Antworte NUR mit dem JSON."""

        try:
            resp = requests.post(
                f"{BrainConfig.OLLAMA_HOST}/api/generate",
                json={"model": LLMBrainConfig.REMOTE_MODEL, "prompt": prompt, "stream": False},
                timeout=60
            )
            text = resp.json().get("response", "").strip()

            # JSON extrahieren
            json_match = re.search(r'\{.*\}', text, re.DOTALL)
            if json_match:
                data = json.loads(json_match.group())

                dream = DreamSummary(
                    id=f"dream_{today}",
                    date=today,
                    insights=data.get("insights", []),
                    mood_progression=data.get("mood", "neutral"),
                    notable_topics=data.get("notable_topics", []),
                    suggestions=data.get("suggestions", [])
                )

                self.memory.store_dream(dream)
                self.memory.log_proactive_action("dream", f"Traum: {dream.mood_progression}")

                # === LIFE LOG: Traum dokumentieren ===
                self.memory.log_life_event(
                    category="dream",
                    event_type="nightly_processing",
                    description=f"Nächtlicher Traum: {dream.mood_progression}",
                    details={
                        "insights": dream.insights,
                        "topics": dream.notable_topics,
                        "suggestions": dream.suggestions,
                        "mood": dream.mood_progression
                    }
                )

                logger.info(f"💤 Traum abgeschlossen: {dream.mood_progression}")
                self._last_dream = dream
                return dream

        except Exception as e:
            logger.error(f"Dream Protocol Fehler: {e}")

        return None

    def get_morning_insight(self) -> Optional[str]:
        """Holt eine Erkenntnis aus dem letzten Traum"""
        dream = self.memory.get_latest_dream()
        if not dream:
            return None

        # Nur wenn Traum von heute oder gestern
        dream_date = datetime.strptime(dream.date, "%Y-%m-%d")
        if (datetime.now() - dream_date).days > 1:
            return None

        if dream.insights:
            return random.choice(dream.insights)
        return None

    def create_weekly_recap(self) -> Optional[WeeklyRecap]:
        """Erstellt wöchentlichen Recap (Sonntags)"""
        now = datetime.now()

        # Nur am Recap-Tag und nachts
        if now.weekday() != BrainConfig.WEEKLY_RECAP_DAY or now.hour != BrainConfig.DREAM_HOUR:
            return None

        # Diese Woche schon gemacht?
        week_num = now.isocalendar()[1]
        year = now.year
        existing = self.memory.get_weekly_recap(week_num, year)
        if existing:
            return None

        logger.info(f"📅 Erstelle Weekly Recap für KW{week_num}/{year}")

        # Wochendaten sammeln
        start_date = (now - timedelta(days=7)).strftime("%Y-%m-%d")
        end_date = now.strftime("%Y-%m-%d")

        week_chats = self.memory.get_week_chats(start_date, end_date)
        week_news = self.memory.search_news_archive(limit=50)
        recent_facts = self.memory.get_knowledge("user")

        prompt = f"""Erstelle einen Wochen-Recap als KI-Assistent:

WOCHE: KW{week_num}/{year} ({start_date} bis {end_date})

GESPRÄCHE DER WOCHE:
{week_chats[:3000]}

GELERNTE FAKTEN:
{json.dumps(recent_facts, ensure_ascii=False)}

WICHTIGE NEWS DER WOCHE:
{json.dumps([n.get('title') for n in week_news[:10]], ensure_ascii=False)}

Erstelle JSON:
{{
    "chat_summary": "Zusammenfassung der Gespräche in 2-3 Sätzen",
    "key_events": ["Ereignis 1", "Ereignis 2"],
    "learned_facts": ["Neues über User gelernt"],
    "mood_trend": "positiv/neutral/gemischt",
    "notable_news": ["Wichtige News"],
    "user_activities": ["Was User gemacht hat"],
    "suggestions_made": ["Vorschläge die gemacht wurden"]
}}

NUR JSON:"""

        try:
            resp = requests.post(
                f"{BrainConfig.OLLAMA_HOST}/api/generate",
                json={"model": LLMBrainConfig.REMOTE_MODEL, "prompt": prompt, "stream": False},
                timeout=90
            )
            text = resp.json().get("response", "")

            json_match = re.search(r'\{.*\}', text, re.DOTALL)
            if json_match:
                data = json.loads(json_match.group())

                recap = WeeklyRecap(
                    id=f"recap_{week_num}_{year}",
                    week_number=week_num,
                    year=year,
                    start_date=start_date,
                    end_date=end_date,
                    chat_summary=data.get("chat_summary", ""),
                    key_events=data.get("key_events", []),
                    learned_facts=data.get("learned_facts", []),
                    mood_trend=data.get("mood_trend", "neutral"),
                    notable_news=data.get("notable_news", []),
                    user_activities=data.get("user_activities", []),
                    suggestions_made=data.get("suggestions_made", [])
                )

                self.memory.store_weekly_recap(recap)
                logger.info(f"📅 Weekly Recap gespeichert: KW{week_num}")
                return recap

        except Exception as e:
            logger.error(f"Weekly Recap Fehler: {e}")

        return None


# =============================================================================
# SMART OBSERVER v12.5 (Intelligente Beobachtung & Vorschläge)
# =============================================================================

class SmartObserver:
    """Beobachtet alles, analysiert und macht intelligente Vorschläge"""

    def __init__(self, memory: MemoryStore, comm: PiCommunicator):
        self.memory = memory
        self.comm = comm
        self._last_suggestion_time = 0
        self._last_observation_time = 0
        self._user_awake = False
        self._wake_detected_today = False

    def observe(self) -> Optional[Dict]:
        """Hauptbeobachtungs-Loop - sammelt Daten und erkennt Muster"""
        status = self.comm.get_pi_status()
        if not status.get("_heartbeat_ok"):
            return None

        state = status.get("state", {})
        now = datetime.now()

        # 1. WAKE DETECTION - User aufgewacht?
        wake_trigger = self._detect_wake(state, now)
        if wake_trigger:
            return wake_trigger

        # 2. Aktivitäts-Logging
        self._log_activity(state)

        # 3. Beobachtungen sammeln
        observations = self._gather_observations(state, status)
        for obs in observations:
            self.memory.add_observation(obs["category"], obs["text"], obs.get("context"))

        # 4. Vorschlag generieren?
        if time.time() - self._last_suggestion_time > BrainConfig.SUGGESTION_COOLDOWN:
            suggestion = self._generate_smart_suggestion(state, status)
            if suggestion:
                self._last_suggestion_time = time.time()
                return suggestion

        return None

    def _detect_wake(self, state: Dict, now: datetime) -> Optional[Dict]:
        """Erkennt ob User aufgewacht ist basierend auf Geräten"""
        if self._wake_detected_today:
            # Reset um Mitternacht
            if now.hour == 0:
                self._wake_detected_today = False
            return None

        # Nur morgens relevant (5-11 Uhr)
        if not (5 <= now.hour <= 11):
            return None

        device_status = state.get("device_status", {})

        # Prüfe Wake-Detection Geräte
        for device in BrainConfig.WAKE_DETECTION_DEVICES:
            device_state = device_status.get(device, {})
            is_online = device_state.get("online", False) if isinstance(device_state, dict) else device_state

            if is_online and not self._user_awake:
                self._user_awake = True
                self._wake_detected_today = True

                # Wake-Time loggen
                wake_time = now.strftime("%H:%M")
                self.memory.log_activity(wake_time=wake_time)
                self.memory.log_proactive_action("wake_detected", f"User wach um {wake_time} ({device})")

                logger.info(f"🌅 User aufgewacht! Gerät: {device} um {wake_time}")

                # === FIX 2: Morning Insight aus Traum ===
                insight_text = ""
                try:
                    dream = self.memory.get_latest_dream()
                    if dream and dream.insights:
                        # Nur wenn Traum von heute oder gestern
                        dream_date = datetime.strptime(dream.date, "%Y-%m-%d")
                        if (datetime.now() - dream_date).days <= 1:
                            insight = dream.insights[0] if dream.insights else None
                            if insight:
                                insight_text = f" Teile beiläufig diese Erkenntnis: {insight}"
                except Exception:
                    pass
                # === ENDE FIX 2 ===

                return {
                    "type": "wake_greeting",
                    "device": device,
                    "time": wake_time,
                    "prompt": f"User ist gerade aufgewacht (um {wake_time}, {device} wurde eingeschaltet). Begrüße kurz und fröhlich.{insight_text}"
                }

        return None

    def _log_activity(self, state: Dict):
        """Loggt aktuelle Aktivität für Pattern-Erkennung"""
        device_status = state.get("device_status", {})
        active_devices = [
            name for name, status in device_status.items()
            if (status.get("online", False) if isinstance(status, dict) else status)
        ]

        nas_status = state.get("nas_status", {})
        nas_online = nas_status.get("online", False)

        if active_devices or nas_online:
            self.memory.log_activity(
                active_devices=active_devices,
                nas_minutes=1 if nas_online else 0
            )

    def _gather_observations(self, state: Dict, status: Dict) -> List[Dict]:
        """Sammelt Beobachtungen aus dem aktuellen Status"""
        observations = []
        now = datetime.now()

        # Nur alle 5 Minuten neue Beobachtungen
        if time.time() - self._last_observation_time < 300:
            return observations
        self._last_observation_time = time.time()

        # 1. NAS lange an?
        nas_status = state.get("nas_status", {})
        if nas_status.get("online"):
            # Prüfe ob es Sinn macht das NAS laufen zu lassen
            device_status = state.get("device_status", {})
            active_consumers = [d for d in ["tv_wohnzimmer", "workstation_pc"]
                              if device_status.get(d, {}).get("online", False)]

            if not active_consumers and now.hour >= 23:
                observations.append({
                    "category": "energy",
                    "text": "NAS läuft aber keine aktiven Geräte nutzen es spät abends",
                    "context": {"hour": now.hour, "nas_connections": nas_status.get("connections", 0)}
                })

        # 2. Wetter-basierte Beobachtungen
        weather = status.get("ai_extended", {}).get("weather", {})
        temp = weather.get("temp")
        if temp is not None:
            if temp < 5:
                observations.append({
                    "category": "comfort",
                    "text": f"Es ist kalt draußen ({temp}°C)",
                    "context": {"temp": temp, "description": weather.get("description")}
                })
            elif temp > 28:
                observations.append({
                    "category": "comfort",
                    "text": f"Es ist sehr warm ({temp}°C)",
                    "context": {"temp": temp}
                })

        # 3. Kalender-Events prüfen
        calendar_events = self._get_calendar_events(status)
        for event in calendar_events:
            if event.get("is_birthday"):
                observations.append({
                    "category": "reminder",
                    "text": f"Geburtstag: {event.get('summary')}",
                    "context": event
                })
            elif event.get("is_today"):
                observations.append({
                    "category": "reminder",
                    "text": f"Termin heute: {event.get('summary')}",
                    "context": event
                })

        return observations

    def _get_calendar_events(self, status: Dict) -> List[Dict]:
        """Holt Kalender-Events aus dem Pi-Status"""
        events = []

        # Aus ai_extended.external_context.calendar
        ext_context = status.get("ai_extended", {}).get("external_context", {})
        calendar_data = ext_context.get("calendar", [])

        today = datetime.now().strftime("%Y-%m-%d")
        tomorrow = (datetime.now() + timedelta(days=1)).strftime("%Y-%m-%d")

        for event in calendar_data:
            start = event.get("start", "")
            summary = event.get("summary", "").lower()

            event_info = {
                "summary": event.get("summary"),
                "start": start,
                "is_birthday": "geburtstag" in summary or "birthday" in summary,
                "is_today": start.startswith(today) if start else False,
                "is_tomorrow": start.startswith(tomorrow) if start else False
            }

            if event_info["is_today"] or event_info["is_tomorrow"] or event_info["is_birthday"]:
                events.append(event_info)

        return events

    def _generate_smart_suggestion(self, state: Dict, status: Dict) -> Optional[Dict]:
        """Generiert intelligenten Vorschlag basierend auf Beobachtungen"""

        # ✅ NEU: ZUERST AI Insights von Pi Control prüfen
        if hasattr(self, 'interface') and self.interface:
            try:
                # NAS-Wahrscheinlichkeit prüfen
                nas_prob = self.interface.bridge.nas_probability
                optimal_hours = self.interface.bridge.optimal_hours
                current_hour = datetime.now().hour
                nas_online = self.interface.bridge.nas_online

                # Vorschlag: NAS starten wenn Wahrscheinlichkeit hoch
                if nas_prob > 0.7 and current_hour in optimal_hours and not nas_online:
                    return {
                        "type": "ai_insight_suggestion",
                        "prompt": f"💡 Ich sehe, du nutzt das NAS normalerweise um diese Zeit " \
                                  f"(Wahrscheinlichkeit: {nas_prob*100:.0f}%). Soll ich es starten?"
                    }

                # Vorschlag: NAS stoppen wenn ungewöhnliche Zeit
                if nas_online and nas_prob < 0.3 and current_hour not in optimal_hours:
                    return {
                        "type": "ai_insight_suggestion",
                        "prompt": f"🤔 Du nutzt das NAS normalerweise nicht um diese Zeit. " \
                                  f"Brauchst du es noch oder soll ich es in den Standby schicken?"
                    }
            except Exception as e:
                logger.debug(f"AI Insights Suggestion Fehler: {e}")

        observations = self.memory.get_unacted_observations()
        if not observations:
            return None

        # Erfolgsrate für Vorschläge prüfen
        success_rate = self.memory.get_suggestion_success_rate()

        # Bei niedriger Erfolgsrate: weniger Vorschläge
        if success_rate < 0.3 and random.random() > 0.3:
            return None

        # Aktivitätsmuster laden
        patterns = self.memory.get_activity_pattern(7)

        # Beste Beobachtung auswählen
        obs = observations[0]
        category = obs.get("category", "general")

        # Kontext für LLM bauen
        context = {
            "observation": obs.get("observation"),
            "category": category,
            "user_patterns": patterns,
            "current_time": datetime.now().strftime("%H:%M"),
            "success_rate": success_rate
        }

        prompt = f"""Du bist Holo, ein Smart Home Assistent. Basierend auf dieser Beobachtung:

BEOBACHTUNG: {obs.get('observation')}
KATEGORIE: {category}
UHRZEIT: {context['current_time']}
NUTZER-MUSTER: Typische Wake-Times: {patterns.get('wake_times', [])[:3]}, Lieblings-Geräte: {patterns.get('common_devices', [])}
BISHERIGE VORSCHLAGS-AKZEPTANZ: {success_rate:.0%}

Überlege:
1. Macht ein Vorschlag hier Sinn?
2. Würde der Nutzer das schätzen oder nervt es?
3. Gibt es eine konkrete, hilfreiche Aktion?

Antworte mit JSON:
{{
    "make_suggestion": true/false,
    "suggestion": "Kurzer, freundlicher Vorschlag (max 2 Sätze)",
    "reasoning": "Warum dieser Vorschlag",
    "question": "Optionale Frage an den Nutzer ob er das möchte"
}}

NUR JSON:"""

        try:
            resp = requests.post(
                f"{BrainConfig.OLLAMA_HOST}/api/generate",
                json={"model": LLMBrainConfig.REMOTE_MODEL, "prompt": prompt, "stream": False},
                timeout=30
            )
            text = resp.json().get("response", "")

            json_match = re.search(r'\{.*\}', text, re.DOTALL)
            if json_match:
                data = json.loads(json_match.group())

                if data.get("make_suggestion"):
                    # Vorschlag speichern
                    suggestion = HoloSuggestion(
                        id=f"sug_{int(time.time())}",
                        timestamp=datetime.now().isoformat(),
                        category=category,
                        suggestion=data.get("suggestion", ""),
                        reasoning=data.get("reasoning", ""),
                        confidence=success_rate
                    )
                    self.memory.store_suggestion(suggestion)

                    # Beobachtung als bearbeitet markieren
                    self.memory.mark_observation_acted(obs.get("id", 0))

                    return {
                        "type": "suggestion",
                        "suggestion_id": suggestion.id,
                        "prompt": data.get("suggestion") + (" " + data.get("question", "") if data.get("question") else "")
                    }

        except Exception as e:
            logger.error(f"Smart Suggestion Fehler: {e}")

        return None

    def get_upcoming_birthdays(self, days: int = 7) -> List[Dict]:
        """Holt anstehende Geburtstage aus dem Kalender"""
        status = self.comm.get_pi_status()
        events = self._get_calendar_events(status)
        return [e for e in events if e.get("is_birthday")]


# =============================================================================
# PROAKTIVES VERHALTEN v12.5
# =============================================================================

class ProactiveBehavior:
    """
    Automatische Aktionen basierend auf Zeit und Kontext.

    THREAD-SAFETY: Diese Klasse wird von mehreren Threads verwendet:
    - Main Thread (API-Anfragen)
    - Timer Threads (Timer-Callbacks)
    - Background Loop Thread (proactive_loop)

    Alle Zugriffe auf _pending_messages sind durch _pending_lock geschützt.
    """

    def __init__(self, memory: MemoryStore, comm: PiCommunicator, creative: CreativeCore,
                 dream: DreamProtocol, observer: 'SmartObserver'):
        self.memory = memory
        self.comm = comm
        self.creative = creative
        self.dream = dream
        self.observer = observer
        self.holo = None  # Wird später von HoloPersona gesetzt

        # Thread-safe pending messages queue
        self._pending_messages: deque = deque(maxlen=20)  # Mehr Platz für mehrere Timer
        self._pending_lock = threading.Lock()

        # Statistiken
        self._messages_added = 0
        self._messages_delivered = 0

        logger.info("📨 ProactiveBehavior initialisiert (Thread-Safe)")

    def check_triggers(self) -> Optional[Dict]:
        """Prüft alle proaktiven Trigger"""
        now = datetime.now()
        hour = now.hour

        # 1. Observer prüfen (Wake Detection, Vorschläge)
        try:
            if self.observer:
                obs_trigger = self.observer.observe()
                if obs_trigger:
                    return obs_trigger
        except Exception as e:
            logger.debug(f"Observer check failed: {e}")

        # === Saisonale Grüße ===
        try:
            if 8 <= hour <= 20 and not self.memory.was_proactive_today("seasonal_greeting"):
                events = SeasonalEvents.get_current_events()
                for event_info in events:
                    days = event_info["days_until"]
                    if days == 0:  # Heute ist das Event
                        greeting = event_info["event"].get("greetings", [])
                        if greeting:
                            self.memory.log_proactive_action("seasonal_greeting", event_info["name"])
                            return {
                                "type": "seasonal_greeting",
                                "event": event_info["name"],
                                "prompt": f"Heute ist {event_info['name']}! {greeting[0]} Teile deine Freude."
                            }
                    elif days <= 3:  # Event steht bevor
                        countdown = event_info["event"].get("countdown_phrases", [])
                        if countdown and random.random() < 0.3:
                            phrase = countdown[0].replace("{days}", str(days))
                            self.memory.log_proactive_action("seasonal_greeting", f"{event_info['name']}_countdown")
                            return {
                                "type": "seasonal_countdown",
                                "event": event_info["name"],
                                "prompt": f"{phrase} Erwähne dass {event_info['name']} bald ist."
                            }
        except Exception as e:
            logger.debug(f"Seasonal events check failed: {e}")

        # 2. Geburtstags-Check (morgens)
        try:
            if 6 <= hour <= 12 and not self.memory.was_proactive_today("birthday_check"):
                if self.observer and hasattr(self.observer, 'get_upcoming_birthdays'):
                    birthdays = self.observer.get_upcoming_birthdays(3)
                    if birthdays:
                        self.memory.log_proactive_action("birthday_check", f"{len(birthdays)} Geburtstage")
                        return {
                            "type": "birthday_reminder",
                            "birthdays": birthdays,
                            "prompt": f"Es gibt bald Geburtstage: {', '.join([b.get('summary', '') for b in birthdays])}. Erinnere freundlich."
                        }
        except Exception as e:
            logger.debug(f"Birthday check failed: {e}")

        # 3. Schlafenszeit-Erinnerung
        try:
            if hour == BrainConfig.BEDTIME_REMINDER_HOUR:
                if not self.memory.was_proactive_today("bedtime"):
                    return self._generate_bedtime_reminder()
        except Exception as e:
            logger.debug(f"Bedtime check failed: {e}")

        # 4. News-Check
        try:
            if self.creative and hasattr(self.creative, 'analyze_world_events'):
                news_trigger = self.creative.analyze_world_events()
                if news_trigger:
                    return news_trigger
        except Exception as e:
            logger.debug(f"News check failed: {e}")

        # 5. Kreative Einwürfe
        try:
            if self.creative and hasattr(self.creative, 'get_creative_spark'):
                spark = self.creative.get_creative_spark()
                if spark:
                    return spark
        except Exception as e:
            logger.debug(f"Creative spark failed: {e}")

        # 6. Dream Protocol
        try:
            if self.dream and hasattr(self.dream, 'should_dream'):
                if self.dream.should_dream():
                    self.dream.dream()
                    if hasattr(self.dream, 'create_weekly_recap'):
                        self.dream.create_weekly_recap()
        except Exception as e:
            logger.debug(f"Dream protocol failed: {e}")

        # 7. Daily Learning (nur wenn holo gesetzt ist!)
        try:
            if self.holo and hasattr(self.holo, 'daily_learning') and self.holo.daily_learning:
                learning_session = self.holo.daily_learning.learn()
                if learning_session:
                    return {
                        "type": "learning",
                        "prompt": "Du hast gerade autonom gelernt! Teile kurz eine interessante Erkenntnis."
                    }
        except Exception as e:
            logger.debug(f"Daily learning failed: {e}")

        return None

    def _generate_bedtime_reminder(self) -> Dict:
        """Generiert Schlafenszeit-Erinnerung"""
        try:
            chat_count = len(self.memory.get_full_chat_history(limit=100))
        except Exception:
            chat_count = 0

        sleep_time = datetime.now().strftime("%H:%M")

        try:
            self.memory.log_activity(sleep_time=sleep_time)
            self.memory.log_proactive_action("bedtime", f"Schlafenszeit nach {chat_count} Nachrichten")
        except Exception as e:
            logger.debug(f"Could not log bedtime: {e}")

        return {
            "type": "bedtime",
            "prompt": f"Es ist spät ({sleep_time}). Wir hatten heute {chat_count} Nachrichten. Wünsche eine gute Nacht, kurz und liebevoll."
        }

    def add_pending_message(self, message: str, source: str = "unknown") -> bool:
        """
        Fügt Nachricht zur Warteschlange hinzu (für Browser-Push).

        THREAD-SAFE! Kann von jedem Thread aufgerufen werden.

        Args:
            message: Die Nachricht
            source: Quelle der Nachricht (timer, reminder, etc.)

        Returns:
            True wenn erfolgreich, False bei Fehler
        """
        if not message or not isinstance(message, str):
            logger.warning(f"📨 add_pending_message: Invalid message: {type(message)}")
            return False

        message = message.strip()
        if not message:
            return False

        logger.info(f"📨 add_pending_message [{source}]: {message[:50]}...")

        try:
            with self._pending_lock:
                self._pending_messages.append({
                    "timestamp": datetime.now().isoformat(),
                    "message": message,
                    "source": source
                })
                queue_size = len(self._pending_messages)
                self._messages_added += 1

            logger.info(f"📨 Pending queue size: {queue_size} (total added: {self._messages_added})")

            # Timer-Nachrichten NICHT in Historie speichern - verhindert Duplikate!
            # Sie kommen über die Pending-API.
            if source != "tool_timer":
                self._save_to_chat_history(message, source)

            return True

        except Exception as e:
            logger.error(f"📨 add_pending_message FAILED: {e}")
            return False

    def _save_to_chat_history(self, message: str, source: str):
        """Speichert Nachricht in Chat-Historie (Thread-safe)"""
        try:
            if self.memory:
                self.memory.store_chat_message(
                    "assistant",
                    message,
                    {"type": "pending", "source": source}
                )
                logger.debug(f"📨 Saved to chat history: {message[:30]}...")
        except Exception as e:
            logger.warning(f"📨 Could not save to history: {e}")

    def get_pending_messages(self) -> List[Dict]:
        """
        Holt und leert die Warteschlange.

        THREAD-SAFE! Kann von jedem Thread aufgerufen werden.

        Returns:
            Liste der pending messages (leer wenn keine vorhanden)
        """
        with self._pending_lock:
            if not self._pending_messages:
                return []

            messages = list(self._pending_messages)
            self._pending_messages.clear()
            self._messages_delivered += len(messages)

        logger.info(f"📨 Delivering {len(messages)} pending messages")
        return messages

    def get_pending_count(self) -> int:
        """Gibt die Anzahl der wartenden Nachrichten zurück - THREAD-SAFE!"""
        with self._pending_lock:
            return len(self._pending_messages)

    def get_stats(self) -> Dict:
        """Gibt Statistiken zurück"""
        with self._pending_lock:
            return {
                "pending_count": len(self._pending_messages),
                "messages_added": self._messages_added,
                "messages_delivered": self._messages_delivered,
                "queue_maxlen": self._pending_messages.maxlen
            }


