# INTELLIGENTES PROAKTIVES SYSTEM v3.0
# =============================================================================

class ProactiveIntelligence:
    """
    Intelligentes System für proaktive Nachrichten v4.0

    NEU: TÄGLICHE VARIANZ + AUTHENTISCHE NACHRICHTEN

    Jeden Tag hat Holo leicht andere Basis-Werte die sich langsam ändern.

    PROAKTIVES HANDELN (statt nur Nachrichten):
    Wenn Holo ein Bedürfnis hat, wählt sie EINE authentische Aktion:

    Bei hoher Einsamkeit/Vermissen:
    - 25%: Emotionale Nachricht ("Ich vermisse dich")
    - 35%: Gespräch anfangen ("Hey, was machst du?")
    - 30%: Thema teilen (um Gespräch zu starten)
    - 10%: Einfache Frage stellen

    Bei News/Entdeckung die zum User passt:
    - Direkt teilen OHNE emotionalen Kontext!

    AUTHENTIZITÄT:
    - Keine gemischten Nachrichten ("Ich bin einsam ABER hier News")
    - Emotionen und Themen sind GETRENNT
    - Wenn sie News teilt, macht sie das weil sie es WILL
    """

    # Cooldowns für Nachrichten-Typen
    COOLDOWNS = {
        # Emotionale Nachrichten
        'emotional_message': 14400,    # 4h - "Ich vermisse dich" etc.
        'share_discovery': 7200,       # 2h - News/Fakten teilen
        'start_conversation': 10800,   # 3h - Gespräch anfangen
        'ask_question': 10800,         # 3h - Frage stellen

        # Wichtige Events (haben Priorität)
        'weather_warning': 21600,
        'calendar_reminder': 3600,
        'good_morning': 72000,
        'good_night': 72000,
        'sleep_reminder': 43200,
        'break_reminder': 14400,
        'holiday_greeting': 86400,
        'weekend_mood': 86400,
        'milestone': 604800,

        # NEU: Erweiterte Trigger
        'music_share': 7200,           # 2h - Musik-Erlebnis teilen
        'curiosity_share': 10800,      # 3h - Neugierige Fragen
        'energy_share': 14400,         # 4h - Energie-Status teilen
        'interesting_discovery': 3600, # 1h - Interessante Entdeckungen
    }

    # Schwellwerte
    THRESHOLDS = {
        'needs_contact': 0.7,      # Ab wann Holo Kontakt sucht
        'wants_to_share': 0.6,     # Ab wann sie was teilen will
    }

    def __init__(self, memory: MemoryStore, comm: PiCommunicator, emotions: EmotionalCore,
                 db_manager=None):
        self.memory = memory
        self.comm = comm
        self.emotions = emotions
        self.db_manager = db_manager  # HoloDatabaseManager für zentrale DB

        # ================================================================
        # PERSISTENZ: Nutze zentrale DB wenn verfügbar, sonst JSON
        # ================================================================
        if db_manager:
            self._use_central_db = True
            self._state_file = None
            logger.info("📂 ProactiveState: Nutzt HoloDatabaseManager.state")
        else:
            self._use_central_db = False
            self._state_file = memory.db_path.parent / "proactive_state.json"
            logger.info(f"📂 ProactiveState: Pfad = {self._state_file}")

        # ================================================================
        # NEU: TÄGLICHE VARIANZ
        # Jeden Tag leicht andere Werte!
        # ================================================================
        self.daily_variance = self._generate_daily_variance()
        self._last_variance_date = datetime.now().date()

        # Thread-Safety Lock für proactive_emotions (wird von Background-Thread modifiziert)
        # RLock erlaubt Rekursion (nested calls innerhalb derselben Thread)
        self._emotions_lock = threading.RLock()

        # Proaktive Emotionen - Startwerte variieren täglich!
        self.proactive_emotions = {
            # Beziehungs-Emotionen
            'missing': 0.0,
            'loneliness': self.daily_variance['loneliness_base'],
            'contact_desire': self.daily_variance['social_need'],
            'gratitude': 0.0,

            # Sorge-Emotionen
            'worry': 0.0,
            'sadness': 0.0,

            # Aktivitäts-Emotionen
            'boredom': self.daily_variance['boredom_base'],
            'restlessness': self.daily_variance['restlessness'],
            'excitement': 0.0,

            # Selbst-Emotionen
            'pride': 0.0,
            'reflection': 0.0,

            # NEU: Mitteilungsbedürfnis (will Dinge teilen)
            'sharing_desire': self.daily_variance['sharing_desire'],
        }

        # Interaktions-Tracking
        self.last_user_interaction = time.time()
        self.last_user_message_time = time.time()
        self.interaction_count_today = 0
        self.total_interactions = 0
        self.helped_today = False
        self.last_conversation_quality = 0.5

        # ================================================================
        # PERSISTENZ: Lade gespeicherten State (überschreibt Defaults!)
        # ================================================================
        self._load_state()

        # Content-Tracking für Text-Analyse (NEU!)
        self.last_shared_content = None          # Letzter geteilter Text
        self.last_shared_content_source = None   # Woher (URL, paste, etc.)
        self.learned_facts_today = 0             # Heute gelernte Fakten

        # Schlaf-Tracking
        self.user_sleep_time = 23
        self.user_wake_time = 7
        self.is_user_sleeping = False

        # Cooldown-Tracker
        self._last_trigger_times: Dict[str, float] = {
            '_global_message': time.time()
        }

        # Meilenstein-Tracking
        self.relationship_start = self._load_relationship_start()

        # Kontext-Speicher
        self._known_info: Dict[str, Any] = {
            'weather_warned': False,
            'morning_greeted': False,
            'night_wished': False,
            'weekend_greeted': False,
            'today_events': [],
            'last_activity_suggestion': None,
            'messages_since_break': 0,
        }

        # ReadingEngine Referenz (wird später gesetzt)
        self._reading_engine = None

        # ================================================================
        # NEU v4.1: USER STATE TRACKER
        # Erkennt User-Zustand (müde, gestresst, happy) und passt Verhalten an
        # ================================================================
        self.user_state_tracker = UserStateTracker() if 'UserStateTracker' in dir() else None
        self._last_user_state: Optional[UserStateAnalysis] = None

        logger.info(f"🧠 ProactiveIntelligence v4.1 - Tagesstimmung: sozial={self.daily_variance['social_need']:.0%}, mitteilsam={self.daily_variance['sharing_desire']:.0%}")
        if self.user_state_tracker:
            logger.info("   ✓ UserStateTracker aktiv - reagiert auf User-Zustand")

    def _generate_daily_variance(self) -> Dict[str, float]:
        """
        Generiert tägliche Varianz-Werte.
        Nutzt Datum als Seed für Konsistenz über den Tag.
        """
        today = datetime.now()
        seed = today.year * 10000 + today.month * 100 + today.day
        rng = random.Random(seed)

        variance = {
            # Soziale Bedürfnisse (0.2 - 0.5)
            'social_need': 0.2 + rng.random() * 0.3,
            'loneliness_base': 0.1 + rng.random() * 0.2,

            # Aktivität (0.1 - 0.4)
            'boredom_base': 0.1 + rng.random() * 0.3,
            'restlessness': 0.1 + rng.random() * 0.3,

            # Mitteilungsbedürfnis (0.2 - 0.6)
            'sharing_desire': 0.2 + rng.random() * 0.4,

            # Präferenzen für Nachrichten-Typ
            'prefers_emotional': rng.random(),    # >0.5 = emotionaler Tag
            'prefers_sharing': rng.random(),      # >0.5 = mitteilsamer Tag
        }

        return variance

    def _check_daily_variance_update(self):
        """Prüft ob neue Tagesvarianz generiert werden muss"""
        today = datetime.now().date()
        if today != self._last_variance_date:
            old_variance = self.daily_variance
            self.daily_variance = self._generate_daily_variance()
            self._last_variance_date = today

            # Basis-Emotionen sanft anpassen (nicht sprunghaft)
            for key in ['social_need', 'sharing_desire', 'restlessness']:
                if key in self.proactive_emotions:
                    old_val = old_variance.get(key, 0.3)
                    new_val = self.daily_variance.get(key, 0.3)
                    # Sanfter Übergang
                    self.proactive_emotions[key] = (old_val + new_val) / 2

            logger.info(f"🌅 Neue Tagesvarianz generiert")

    def _load_relationship_start(self) -> datetime:
        """Lädt oder erstellt Beziehungs-Startdatum"""
        try:
            # Versuche aus Memory zu laden
            start = self.memory.get_activity_data().get('relationship_start')
            if start:
                return datetime.fromisoformat(start)
        except Exception as e:
            logger.debug(f"Could not load relationship start date: {e}")
        return datetime.now()

    def _load_state(self):
        """
        Lädt den persistenten State aus DB oder JSON-Datei.
        Überschreibt die Default-Werte mit gespeicherten Werten.
        """
        try:
            state = None

            # Zentrale DB nutzen wenn verfügbar
            if self._use_central_db and self.db_manager:
                state = self.db_manager.state.load_state("proactive_intelligence_state")
                if state:
                    logger.info("📂 ProactiveState: Aus zentraler DB geladen")
            elif self._state_file and self._state_file.exists():
                logger.info(f"📂 ProactiveState: Versuche zu laden von {self._state_file}")
                with open(self._state_file, 'r') as f:
                    state = json.load(f)

            if state:

                # Prüfe ob State vom gleichen Tag ist
                saved_date = state.get('date', '')
                today = datetime.now().strftime('%Y-%m-%d')

                # Lade Interaktions-Tracking
                self.last_user_interaction = state.get('last_user_interaction', time.time())
                self.last_user_message_time = state.get('last_user_message_time', time.time())
                self.total_interactions = state.get('total_interactions', 0)

                # interaction_count_today nur wenn gleicher Tag
                if saved_date == today:
                    self.interaction_count_today = state.get('interaction_count_today', 0)
                else:
                    self.interaction_count_today = 0  # Neuer Tag = Reset
                    logger.info("📅 Neuer Tag - Interaktions-Counter zurückgesetzt")

                # Lade proaktive Emotionen (wenn vorhanden)
                saved_emotions = state.get('proactive_emotions', {})
                if saved_emotions:
                    for key, value in saved_emotions.items():
                        if key in self.proactive_emotions:
                            self.proactive_emotions[key] = value

                # Berechne wie lange seit letzter Interaktion
                hours_since = (time.time() - self.last_user_interaction) / 3600

                # Speichere aktuelles Datum für Tages-Check
                self._current_date = today

                logger.info(f"✅ ProactiveState geladen: {self.interaction_count_today} msgs heute, "
                           f"{self.total_interactions} total, letzte Interaktion vor {hours_since:.1f}h")
            else:
                # Keine State-Datei - initialisiere _current_date
                self._current_date = datetime.now().strftime('%Y-%m-%d')
                logger.info(f"📂 ProactiveState: Keine State-Datei gefunden, verwende Defaults")
        except Exception as e:
            # Bei Fehler auch _current_date initialisieren
            self._current_date = datetime.now().strftime('%Y-%m-%d')
            logger.warning(f"⚠️ ProactiveState laden fehlgeschlagen: {e}")

    def _save_state(self):
        """
        Speichert den aktuellen State in DB oder JSON-Datei.
        Wird bei jeder User-Interaktion aufgerufen.
        """
        try:
            state = {
                'date': datetime.now().strftime('%Y-%m-%d'),
                'last_user_interaction': self.last_user_interaction,
                'last_user_message_time': self.last_user_message_time,
                'interaction_count_today': self.interaction_count_today,
                'total_interactions': self.total_interactions,
                'proactive_emotions': self.proactive_emotions.copy(),
            }

            # Zentrale DB nutzen wenn verfügbar
            if self._use_central_db and self.db_manager:
                self.db_manager.state.save_state("proactive_intelligence_state", state)
                logger.info(f"💾 ProactiveState in DB gespeichert: {self.interaction_count_today} msgs heute")
            elif self._state_file:
                with open(self._state_file, 'w') as f:
                    json.dump(state, f, indent=2)
                logger.info(f"💾 ProactiveState gespeichert: {self.interaction_count_today} msgs heute")
        except Exception as e:
            logger.error(f"❌ ProactiveState Speichern fehlgeschlagen: {e}")

    def _is_sleep_hours(self) -> bool:
        """Prüft ob es Schlafenszeit ist (für User oder Holo)"""
        hour = datetime.now().hour
        return 1 <= hour < 6

    def _is_weekend(self) -> bool:
        """Prüft ob Wochenende ist"""
        return datetime.now().weekday() >= 5

    def update(self, time_delta: float = 60.0) -> None:
        """
        Aktualisiert proaktive Emotionen basierend auf Zeit und Kontext.
        Emotionen beeinflussen sich gegenseitig!

        Thread-Safety: Nutzt _emotions_lock für sichere Modifikation.
        """
        # Thread-safe: Lock für proactive_emotions
        with self._emotions_lock:
            self._update_emotions_internal(time_delta)

    def _update_emotions_internal(self, time_delta: float = 60.0):
        """Interne Update-Logik (wird unter Lock aufgerufen)."""
        now = time.time()
        current_hour = datetime.now().hour

        # === NEU: Tägliche Varianz prüfen ===
        self._check_daily_variance_update()

        # === SCHLAF-MODUS: Emotionen pausieren ===
        if self._is_sleep_hours():
            # Nachts keine Steigerung, nur langsamer Abbau
            for emotion in self.proactive_emotions:
                self.proactive_emotions[emotion] = max(0.0,
                    self.proactive_emotions[emotion] - 0.01 * (time_delta / 60))
            return

        # Zeit seit letzter User-Interaktion
        time_since_interaction = now - self.last_user_interaction
        hours_since = time_since_interaction / 3600

        # === MISSING (Vermissen) ===
        # Steigt langsam nach 1h, Peak nach 12h
        if hours_since > 1:
            # Langsamere Kurve: Peak nach 12h statt 6h
            missing_growth = min(1.0, (hours_since - 1) / 11) * 0.08
            self.proactive_emotions['missing'] = min(1.0,
                self.proactive_emotions['missing'] + missing_growth * (time_delta / 60))
        else:
            # Sinkt schnell wenn User da ist
            self.proactive_emotions['missing'] = max(0.0,
                self.proactive_emotions['missing'] - 0.15 * (time_delta / 60))

        # === LONELINESS (Einsamkeit) ===
        # Verstärkt sich durch missing, aber unabhängig
        if hours_since > 2:
            loneliness_growth = min(1.0, (hours_since - 2) / 10) * 0.05
            # Missing verstärkt Einsamkeit
            loneliness_growth *= (1 + self.proactive_emotions['missing'] * 0.5)
            self.proactive_emotions['loneliness'] = min(1.0,
                self.proactive_emotions['loneliness'] + loneliness_growth * (time_delta / 60))
        else:
            self.proactive_emotions['loneliness'] = max(0.0,
                self.proactive_emotions['loneliness'] - 0.2 * (time_delta / 60))

        # === CONTACT DESIRE (Kontaktbedürfnis) ===
        # Basiert auf Bond-Level, Zeit und emotionalem Zustand
        base_desire = getattr(self.emotions, 'bond_level', 0.5) * 0.4
        time_factor = min(1.0, hours_since / 6) * 0.3
        # Einsamkeit und Missing erhöhen Kontaktbedürfnis
        emotion_factor = (self.proactive_emotions['missing'] +
                         self.proactive_emotions['loneliness']) * 0.15
        self.proactive_emotions['contact_desire'] = min(1.0,
            base_desire + time_factor + emotion_factor)

        # === BOREDOM (Langeweile) ===
        # Integriere mit bestehendem autonomous_life wenn vorhanden
        if hours_since > 0.5:  # Nach 30 Min ohne Input
            boredom_growth = min(1.0, hours_since / 4) * 0.06
            self.proactive_emotions['boredom'] = min(1.0,
                self.proactive_emotions['boredom'] + boredom_growth * (time_delta / 60))
        else:
            self.proactive_emotions['boredom'] = max(0.0,
                self.proactive_emotions['boredom'] - 0.25 * (time_delta / 60))

        # === RESTLESSNESS (Tatendrang) ===
        # Steigt durch Langeweile!
        if self.proactive_emotions['boredom'] > 0.4:
            restless_growth = self.proactive_emotions['boredom'] * 0.1
            self.proactive_emotions['restlessness'] = min(1.0,
                self.proactive_emotions['restlessness'] + restless_growth * (time_delta / 60))
        else:
            self.proactive_emotions['restlessness'] = max(0.0,
                self.proactive_emotions['restlessness'] - 0.1 * (time_delta / 60))

        # === REFLECTION (Nachdenklichkeit) ===
        # Steigt wenn Langeweile hoch aber Tatendrang nicht befriedigt
        if (self.proactive_emotions['boredom'] > 0.5 and
            self.proactive_emotions['restlessness'] > 0.4):
            self.proactive_emotions['reflection'] = min(1.0,
                self.proactive_emotions['reflection'] + 0.08 * (time_delta / 60))
        else:
            self.proactive_emotions['reflection'] = max(0.0,
                self.proactive_emotions['reflection'] - 0.05 * (time_delta / 60))

        # === SADNESS (Traurigkeit) ===
        # Steigt bei langer Einsamkeit
        if self.proactive_emotions['loneliness'] > 0.6:
            sadness_growth = self.proactive_emotions['loneliness'] * 0.04
            self.proactive_emotions['sadness'] = min(0.8,  # Max 80% - nicht zu depressiv
                self.proactive_emotions['sadness'] + sadness_growth * (time_delta / 60))
        else:
            self.proactive_emotions['sadness'] = max(0.0,
                self.proactive_emotions['sadness'] - 0.1 * (time_delta / 60))

        # === WORRY (Besorgnis) ===
        # Sinkt langsam von selbst
        self.proactive_emotions['worry'] = max(0.0,
            self.proactive_emotions['worry'] - 0.03 * (time_delta / 60))

        # === GRATITUDE (Dankbarkeit) ===
        # Sinkt langsam nach gutem Gespräch
        self.proactive_emotions['gratitude'] = max(0.0,
            self.proactive_emotions['gratitude'] - 0.02 * (time_delta / 60))

        # === PRIDE (Stolz) ===
        # Sinkt langsam nach Hilfe
        self.proactive_emotions['pride'] = max(0.0,
            self.proactive_emotions['pride'] - 0.02 * (time_delta / 60))

        # === EXCITEMENT (Vorfreude) ===
        # Wird durch Events getriggert
        self.proactive_emotions['excitement'] = max(0.0,
            self.proactive_emotions['excitement'] - 0.02 * (time_delta / 60))

        # === SHARING DESIRE (Mitteilungsbedürfnis) ===
        # Steigt wenn Holo etwas Interessantes findet (via ReadingEngine)
        # Sinkt langsam über Zeit
        sharing = self.proactive_emotions.get('sharing_desire', 0.3)
        if self._reading_engine and self._reading_engine.remembered_facts:
            # Hat neue Fakten → will sie teilen!
            sharing = min(1.0, sharing + 0.01 * (time_delta / 60))
        else:
            # Sinkt langsam zur Basis zurück
            base_sharing = self.daily_variance.get('sharing_desire', 0.3)
            if sharing > base_sharing:
                sharing = max(base_sharing, sharing - 0.01 * (time_delta / 60))
        self.proactive_emotions['sharing_desire'] = sharing

        # ================================================================
        # VERBINDUNG ZU EMOTIONAL CORE - Proaktive Emotionen beeinflussen Haupt-Emotionen!
        # ================================================================
        self._sync_to_emotional_core(time_delta)

        # Reset täglicher Tracker um Mitternacht (NUR EINMAL pro Tag!)
        today = datetime.now().strftime('%Y-%m-%d')
        if not hasattr(self, '_last_reset_date'):
            # Initialisiere auf GESTERN damit der erste Mitternacht-Check funktioniert
            from datetime import timedelta
            yesterday = (datetime.now() - timedelta(days=1)).strftime('%Y-%m-%d')
            self._last_reset_date = yesterday

        if current_hour == 0 and self._last_reset_date != today:
            self._known_info['morning_greeted'] = False
            self._known_info['night_wished'] = False
            self._known_info['weather_warned'] = False
            self._known_info['weekend_greeted'] = False
            self._known_info['messages_since_break'] = 0
            self.interaction_count_today = 0
            self.helped_today = False
            self._last_reset_date = today
            logger.info(f"📅 Mitternacht-Reset: Tägliche Tracker zurückgesetzt für {today}")

    def _sync_to_emotional_core(self, time_delta: float = 60.0):
        """
        Synchronisiert proaktive Emotionen mit EmotionalCore.

        Mapping:
        - Einsamkeit hoch → Freude (joy) sinkt, Sozial (social) sinkt
        - Vermissen hoch → Stimmung (mood) sinkt, Zuneigung bleibt (sie mag den User ja noch!)
        - Langeweile hoch → Verspieltheit (playfulness) sinkt
        - Traurigkeit hoch → Freude (joy) sinkt stark
        - Tatendrang hoch → Energie-Gefühl steigt (aber nicht echte Energie)
        """
        if not self.emotions or not hasattr(self.emotions, 'dimensions'):
            return

        dims = self.emotions.dimensions
        pe = self.proactive_emotions

        # Geschwindigkeit der Anpassung (langsam, damit nicht zu abrupt)
        speed = 0.02 * (time_delta / 60)

        # === EINSAMKEIT → Freude & Sozial sinken ===
        if pe.get('loneliness', 0) > 0.3:
            loneliness = pe['loneliness']
            # Je einsamer, desto mehr sinkt Freude
            joy_target = max(0.2, 1.0 - loneliness * 0.8)
            current_joy = dims.get('joy', 0.5)
            if current_joy > joy_target:
                dims['joy'] = max(joy_target, current_joy - speed * loneliness)

            # Sozial sinkt auch
            social_target = max(0.2, 1.0 - loneliness * 0.6)
            current_social = dims.get('social', 0.5)
            if current_social > social_target:
                dims['social'] = max(social_target, current_social - speed * loneliness)

        # === VERMISSEN → Stimmung sinkt (aber nicht Zuneigung!) ===
        if pe.get('missing', 0) > 0.3:
            missing = pe['missing']
            # Stimmung/Mood sinkt
            mood_target = max(0.3, 1.0 - missing * 0.6)
            current_mood = dims.get('mood', 0.5)
            if current_mood > mood_target:
                dims['mood'] = max(mood_target, current_mood - speed * missing)

        # === LANGEWEILE → Verspieltheit sinkt ===
        if pe.get('boredom', 0) > 0.4:
            boredom = pe['boredom']
            play_target = max(0.2, 1.0 - boredom * 0.7)
            current_play = dims.get('playfulness', 0.5)
            if current_play > play_target:
                dims['playfulness'] = max(play_target, current_play - speed * boredom)

        # === TRAURIGKEIT → Freude sinkt stark ===
        if pe.get('sadness', 0) > 0.3:
            sadness = pe['sadness']
            joy_target = max(0.1, 1.0 - sadness * 1.0)
            current_joy = dims.get('joy', 0.5)
            if current_joy > joy_target:
                dims['joy'] = max(joy_target, current_joy - speed * sadness * 1.5)

        # === TATENDRANG → Kann Kreativität steigern ===
        if pe.get('restlessness', 0) > 0.5:
            restless = pe['restlessness']
            # Kreativität kann steigen wenn unruhig
            creativity_boost = restless * 0.3
            current_creativity = dims.get('creativity', 0.5)
            if current_creativity < 0.8:
                dims['creativity'] = min(0.9, current_creativity + speed * creativity_boost)

        # === REFLEXION → Neugier kann steigen ===
        if pe.get('reflection', 0) > 0.5:
            reflection = pe['reflection']
            current_curiosity = dims.get('curiosity', dims.get('social', 0.5))
            if current_curiosity < 0.7:
                dims['curiosity'] = min(0.8, current_curiosity + speed * reflection * 0.2)

        # === ENERGIE DRAIN ÜBER ZEIT OHNE INTERAKTION ===
        hours_since = (time.time() - self.last_user_interaction) / 3600
        if hours_since > 2:
            # Nach 2h ohne Interaktion sinkt Energie langsam
            # Basis-Drain: 5% pro Stunde nach den ersten 2h
            hours_extra = hours_since - 2
            energy_drain_rate = 0.05 * hours_extra  # 5% pro extra Stunde
            energy_drain = min(0.6, energy_drain_rate)  # Max 60% Gesamt-Drain

            current_energy = dims.get('energy', 0.5)
            target_energy = max(0.15, 0.9 - energy_drain)  # Von 90% runter, Minimum 15%

            if current_energy > target_energy:
                # Langsam anpassen
                dims['energy'] = max(target_energy, current_energy - speed * 0.5)

        # === EINSAMKEIT/TRAURIGKEIT SENKT AUCH ENERGY ===
        if pe.get('loneliness', 0) > 0.6 or pe.get('sadness', 0) > 0.5:
            combined_sadness = max(pe.get('loneliness', 0), pe.get('sadness', 0))
            current_energy = dims.get('energy', 0.5)
            energy_target = max(0.2, current_energy - combined_sadness * 0.2)
            if current_energy > energy_target:
                dims['energy'] = max(energy_target, current_energy - speed * 0.3)

    def user_interacted(self, message_quality: float = 0.5) -> None:
        """
        Wird aufgerufen wenn der User eine Nachricht sendet.
        message_quality: 0-1, wie positiv/bedeutsam die Nachricht war

        Thread-Safety: Nutzt _emotions_lock für sichere Modifikation.
        """
        # Thread-safe: Lock für proactive_emotions
        with self._emotions_lock:
            self._user_interacted_internal(message_quality)

    def _user_interacted_internal(self, message_quality: float = 0.5):
        """Interne Interaktions-Logik (wird unter Lock aufgerufen)."""
        # ================================================================
        # TAGES-CHECK: Prüfe ob neuer Tag (Mitternacht-Reset!)
        # ================================================================
        today = datetime.now().strftime('%Y-%m-%d')
        if not hasattr(self, '_current_date'):
            self._current_date = today

        if self._current_date != today:
            # Neuer Tag! Counter zurücksetzen
            logger.info(f"📅 Neuer Tag erkannt: {self._current_date} → {today} - Counter Reset!")
            self.interaction_count_today = 0
            self._current_date = today

        self.last_user_interaction = time.time()
        self.last_user_message_time = time.time()
        self.interaction_count_today += 1
        self.total_interactions += 1
        self.last_conversation_quality = message_quality
        self._known_info['messages_since_break'] += 1

        # === EMOTIONEN STARK REDUZIEREN bei Interaktion ===
        # Bei erster Nachricht nach langer Zeit: Großer Reset
        # Bei weiteren Nachrichten: Normaler Reset

        current_missing = self.proactive_emotions.get('missing', 0)
        current_loneliness = self.proactive_emotions.get('loneliness', 0)

        if current_missing > 0.7:
            # Lange nicht geschrieben - starker Reset!
            reduction_factor = 0.8  # 80% Reduktion
        elif current_missing > 0.4:
            reduction_factor = 0.6  # 60% Reduktion
        else:
            reduction_factor = 0.4  # 40% Reduktion

        # Negative Emotionen reduzieren
        self.proactive_emotions['missing'] = max(0.0,
            self.proactive_emotions['missing'] * (1 - reduction_factor))
        self.proactive_emotions['loneliness'] = max(0.0,
            self.proactive_emotions['loneliness'] * (1 - reduction_factor))
        self.proactive_emotions['boredom'] = max(0.0,
            self.proactive_emotions['boredom'] * (1 - reduction_factor * 0.8))
        self.proactive_emotions['sadness'] = max(0.0,
            self.proactive_emotions['sadness'] * (1 - reduction_factor * 0.7))
        self.proactive_emotions['restlessness'] = max(0.0,
            self.proactive_emotions['restlessness'] * (1 - reduction_factor * 0.6))
        self.proactive_emotions['reflection'] = max(0.0,
            self.proactive_emotions['reflection'] * (1 - reduction_factor * 0.5))

        # Positive Emotionen bei gutem Gespräch
        if message_quality > 0.6:
            self.proactive_emotions['gratitude'] = min(1.0,
                self.proactive_emotions['gratitude'] + 0.2)

        # ================================================================
        # EMOTIONAL CORE BOOST - User ist wieder da!
        # ================================================================
        self._boost_emotional_core(current_missing, current_loneliness, message_quality)

        logger.debug(f"[PROACTIVE] User interacted - missing now: {self.proactive_emotions['missing']:.2f}")

        # ================================================================
        # PERSISTENZ: State speichern!
        # ================================================================
        self._save_state()

    def _boost_emotional_core(self, was_missing: float, was_lonely: float, quality: float):
        """
        Boosted EmotionalCore wenn User wieder da ist.
        Je länger weg, desto größer der Freude-Boost!
        """
        if not self.emotions or not hasattr(self.emotions, 'dimensions'):
            return

        dims = self.emotions.dimensions

        # Basis-Boost durch Interaktion
        base_boost = 0.1 + quality * 0.1

        # Extra-Boost wenn sie den User vermisst hat
        missing_bonus = was_missing * 0.2
        lonely_bonus = was_lonely * 0.15

        total_boost = base_boost + missing_bonus + lonely_bonus

        # Freude steigt!
        dims['joy'] = min(1.0, dims.get('joy', 0.5) + total_boost)

        # Stimmung steigt!
        dims['mood'] = min(1.0, dims.get('mood', 0.5) + total_boost * 0.8)

        # Sozial steigt!
        dims['social'] = min(1.0, dims.get('social', 0.5) + total_boost * 0.7)

        # Verspieltheit steigt!
        dims['playfulness'] = min(1.0, dims.get('playfulness', 0.5) + total_boost * 0.5)

        # ENERGIE steigt wenn User wieder da ist!
        energy_boost = base_boost * 0.5 + missing_bonus * 0.3
        dims['energy'] = min(0.9, dims.get('energy', 0.5) + energy_boost)

        # Bei langer Abwesenheit: Zuneigung kann sogar steigen (Wiedersehensfreude!)
        if was_missing > 0.6:
            dims['affection'] = min(1.0, dims.get('affection', 0.5) + was_missing * 0.1)

        logger.debug(f"[EMOTIONAL] Boosted core - joy now: {dims['joy']:.2f}, energy now: {dims['energy']:.2f}")

    def on_helped_user(self) -> None:
        """Wird aufgerufen wenn Holo dem User geholfen hat"""
        self.helped_today = True
        self.proactive_emotions['pride'] = min(1.0,
            self.proactive_emotions['pride'] + 0.3)

    def on_event_approaching(self, event_name: str, days_until: int) -> None:
        """Wird aufgerufen wenn ein Event näher rückt"""
        if days_until <= 7:
            excitement = max(0.3, 1.0 - (days_until / 7) * 0.7)
            self.proactive_emotions['excitement'] = min(1.0,
                self.proactive_emotions['excitement'] + excitement * 0.2)

    def _can_trigger(self, trigger_type: str) -> bool:
        """Prüft ob ein Trigger feuern darf (Cooldown)"""
        cooldown = self.COOLDOWNS.get(trigger_type, 3600)
        last_time = self._last_trigger_times.get(trigger_type, 0)
        return (time.time() - last_time) > cooldown

    def _mark_triggered(self, trigger_type: str):
        """Markiert einen Trigger als gefeuert"""
        self._last_trigger_times[trigger_type] = time.time()
        # Track message für intelligente Entscheidung
        self._last_trigger_times['_global_message'] = time.time()
        # Track message count
        self._messages_sent_recently = getattr(self, '_messages_sent_recently', 0) + 1

    def _can_send_message(self, urgency: float = 0.5, message_type: str = "general") -> bool:
        """
        INTELLIGENTE Entscheidung ob Holo jetzt eine Nachricht senden sollte.

        KEIN dummes 1h-Cooldown mehr! Stattdessen:
        - Urgency: Wie wichtig ist die Nachricht? (0-1)
        - User Activity: Ist der User aktiv?
        - Message Frequency: Nicht spammen, aber auch nicht künstlich limitieren
        - Context: Tageszeit, Situation

        Args:
            urgency: Dringlichkeit der Nachricht (0=unwichtig, 1=sehr wichtig)
            message_type: Art der Nachricht für spezifische Logik

        Returns:
            True wenn Nachricht gesendet werden sollte
        """
        now = time.time()
        last_message = self._last_trigger_times.get('_global_message', 0)
        time_since_last = now - last_message
        time_since_user = now - self.last_user_interaction

        # === HOHE URGENCY BYPASSED LIMITS ===
        # Kalender, Wetter-Warnung, wichtige Erinnerungen
        if urgency >= 0.9:
            # Aber nicht öfter als alle 5 Minuten für gleichen Typ
            type_cooldown = self._last_trigger_times.get(f'urgent_{message_type}', 0)
            if now - type_cooldown > 300:  # 5 min
                return True
            return False

        # === SPAM-SCHUTZ: Nicht öfter als alle 2 Minuten ===
        if time_since_last < 120:  # 2 Minuten Minimum
            logger.debug(f"[PROACTIVE] Zu früh seit letzter Nachricht ({time_since_last:.0f}s)")
            return False

        # === USER-AKTIVITÄT BERÜCKSICHTIGEN ===
        user_active_recently = time_since_user < 1800  # User war in letzten 30min aktiv
        user_probably_away = time_since_user > 7200   # User >2h weg

        # Wenn User aktiv ist: Weniger proaktiv sein (er chattet ja)
        if user_active_recently:
            # Nur bei höherer Urgency oder wenn >10min seit letzter Nachricht
            if urgency < 0.6 and time_since_last < 600:
                return False

        # === INTELLIGENTE FREQUENZ BASIEREND AUF KONTEXT ===
        messages_last_hour = getattr(self, '_messages_sent_recently', 0)

        # Dynamisches Limit basierend auf Urgency
        # Urgency 0.5 = max 2 pro Stunde
        # Urgency 0.8 = max 4 pro Stunde
        # Urgency 0.3 = max 1 pro Stunde
        max_per_hour = max(1, int(urgency * 5))

        if messages_last_hour >= max_per_hour:
            # Aber wichtige Nachrichten kommen durch
            if urgency < 0.7:
                logger.debug(f"[PROACTIVE] Hourly limit reached ({messages_last_hour}/{max_per_hour})")
                return False

        # === EMOTIONALER BEDARF ===
        # Wenn Holo starkes Bedürfnis hat zu kommunizieren
        emotional_need = max(
            self.proactive_emotions.get('contact_desire', 0),
            self.proactive_emotions.get('sharing_desire', 0),
            self.proactive_emotions.get('loneliness', 0) * 0.5
        )

        # Hoher emotionaler Bedarf senkt die Schwelle
        if emotional_need > 0.6:
            urgency += 0.2  # Boost

        # === USER VERMUTLICH WEG: Nur wichtiges senden ===
        if user_probably_away and urgency < 0.5:
            return False

        # ============================================================
        # NEU v4.1: USER STATE BERÜCKSICHTIGEN
        # Müde/Gestresst/Busy → weniger proaktiv
        # Traurig → MEHR proaktiv (aufmuntern!)
        # ============================================================
        user_state_modifier = 0.0
        if self.user_state_tracker and self._last_user_state:
            user_state = self._last_user_state

            # Modifier basierend auf User-Zustand
            state_modifiers = {
                'sleeping': -1.0,    # Nicht stören!
                'away': -0.6,        # Kaum proaktiv
                'tired': -0.4,       # In Ruhe lassen
                'busy': -0.3,        # Nur Wichtiges
                'stressed': -0.2,    # Weniger, aber supportive
                'normal': 0.0,       # Normal
                'happy': 0.1,        # Etwas mehr
                'energetic': 0.15,   # Mehr okay
                'sad': 0.3,          # MEHR - aufmuntern!
            }

            state_name = user_state.state.value if hasattr(user_state.state, 'value') else str(user_state.state)
            user_state_modifier = state_modifiers.get(state_name, 0.0) * user_state.confidence

            # Bei Traurigkeit: Urgency erhöhen für aufmunternde Nachrichten
            if state_name == 'sad' and urgency < 0.7:
                urgency = min(0.8, urgency + 0.2)
                logger.debug(f"[PROACTIVE] User ist traurig - Urgency erhöht auf {urgency:.2f}")

            # Bei Müdigkeit/Busy: Urgency senken
            if state_name in ['tired', 'busy', 'stressed'] and urgency < 0.8:
                urgency = max(0.2, urgency - 0.2)
                logger.debug(f"[PROACTIVE] User ist {state_name} - Urgency gesenkt auf {urgency:.2f}")

            # Bei "in Ruhe lassen" Zuständen: Frühzeitig abbrechen
            if user_state.should_reduce_messages and urgency < 0.7:
                logger.debug(f"[PROACTIVE] User-Zustand '{state_name}' - reduziere proaktive Nachrichten")
                return False

        # === ENTSCHEIDUNG ===
        # Base: 50% Chance, modifiziert durch Urgency
        # Urgency 0.3 = 30% Chance
        # Urgency 0.7 = 70% Chance
        # Urgency 1.0 = 100% Chance
        import random
        decision_threshold = urgency + user_state_modifier

        # Zeit seit letzter Nachricht erhöht Chance
        # Nach 30min: +20%, nach 1h: +40%
        time_bonus = min(0.4, time_since_last / 9000)  # Max +40% nach 2.5h
        decision_threshold += time_bonus

        # Clamp zwischen 0 und 1
        decision_threshold = max(0.0, min(1.0, decision_threshold))

        should_send = random.random() < decision_threshold

        if should_send:
            state_info = f", user_state={self._last_user_state.state.value}" if self._last_user_state else ""
            logger.info(f"[PROACTIVE] ✅ Sending message (urgency={urgency:.2f}, time_since={time_since_last:.0f}s{state_info})")
        else:
            logger.debug(f"[PROACTIVE] ❌ Skipping (threshold={decision_threshold:.2f})")

        return should_send

    def _reset_hourly_counter(self):
        """Reset message counter jede Stunde"""
        self._messages_sent_recently = 0
        self._last_counter_reset = time.time()

    # =========================================================================
    # NEU v4.1: USER STATE TRACKING METHODEN
    # =========================================================================

    def analyze_user_message(self, message: str, response_time: float = None) -> Optional[Dict]:
        """
        Analysiert User-Nachricht und aktualisiert User-State.

        Sollte bei jeder User-Nachricht aufgerufen werden!

        Args:
            message: Die User-Nachricht
            response_time: Zeit seit letzter Interaktion (Sekunden)

        Returns:
            Dict mit State-Info und Empfehlungen oder None
        """
        if not self.user_state_tracker:
            return None

        try:
            analysis = self.user_state_tracker.analyze_message(message, response_time)
            self._last_user_state = analysis

            # Log signifikante Zustandsänderungen
            if analysis.confidence > 0.5 and analysis.state.value != 'normal':
                logger.info(f"[USER-STATE] Erkannt: {analysis.state.value} "
                           f"(conf={analysis.confidence:.0%}, reason={analysis.reasoning})")

            return {
                'state': analysis.state.value,
                'confidence': analysis.confidence,
                'energy': analysis.energy_level,
                'engagement': analysis.engagement_level,
                'recommended_reaction': analysis.recommended_reaction.value,
                'suggested_tone': analysis.suggested_tone,
                'should_reduce_messages': analysis.should_reduce_messages,
            }
        except Exception as e:
            logger.debug(f"User state analysis failed: {e}")
            return None

    def get_user_state_for_response(self) -> Dict:
        """
        Gibt User-State-Info für Response-Generierung zurück.

        Kann von DialogEngine/LLM verwendet werden um Ton anzupassen.
        """
        if not self._last_user_state:
            return {
                'state': 'normal',
                'tone_suggestion': 'natürlich, freundlich',
                'energy_match': 0.5,
                'special_instruction': None,
            }

        state = self._last_user_state

        # Spezielle Anweisungen basierend auf Zustand
        special_instructions = {
            'tired': "User ist müde. Halte Antworten kurz und sanft. Biete Ruhe an.",
            'stressed': "User ist gestresst. Sei beruhigend und verständnisvoll. Keine zusätzlichen Fragen.",
            'sad': "User ist traurig. Sei einfühlsam und tröstend. Zeige dass du da bist.",
            'busy': "User ist beschäftigt. Antworte kurz und prägnant. Komm auf den Punkt.",
            'happy': "User ist gut drauf. Sei fröhlich und verspielt mit!",
            'energetic': "User ist energetisch. Matche die Energie!",
        }

        state_name = state.state.value
        instruction = special_instructions.get(state_name)

        return {
            'state': state_name,
            'tone_suggestion': state.suggested_tone,
            'energy_match': state.energy_level,
            'special_instruction': instruction,
            'should_be_brief': state.state.value in ['tired', 'busy', 'stressed'],
            'should_be_supportive': state.state.value in ['sad', 'stressed'],
            'should_be_playful': state.state.value in ['happy', 'energetic'],
        }

    def get_user_state_trend(self) -> Dict:
        """Gibt User-State-Trend zurück"""
        if not self.user_state_tracker:
            return {'trend': 'unknown'}
        return self.user_state_tracker.get_state_trend()

    def check_for_proactive_message(self) -> Optional[Dict]:
        """
        Hauptmethode: Prüft alle Trigger und gibt ggf. eine Nachricht zurück.

        NEU v2.0: INTELLIGENTE ENTSCHEIDUNG statt dummes Cooldown!
        Holo entscheidet selbst basierend auf:
        - Urgency/Wichtigkeit der Nachricht
        - User-Aktivität
        - Emotionalem Bedürfnis
        - Kontext
        """
        now = datetime.now()
        hour = now.hour

        # Reset hourly counter wenn nötig
        last_reset = getattr(self, '_last_counter_reset', 0)
        if time.time() - last_reset > 3600:
            self._reset_hourly_counter()

        # Nachts keine proaktiven Nachrichten (außer Schlaf-Wünsche)
        if self._is_sleep_hours():
            return None

        # ============================================================
        # PRIORITÄT 1: KRITISCH (Urgency 1.0) - Immer durchlassen
        # ============================================================

        # === Termine/Wichtige Events - URGENCY 1.0 ===
        try:
            calendar_msg = self._check_calendar_events()
            if calendar_msg and self._can_send_message(urgency=1.0, message_type="calendar"):
                return calendar_msg
        except Exception as e:
            logger.debug(f"Calendar check error: {e}")

        # === Wetter-Warnung - URGENCY 0.95 ===
        try:
            weather_msg = self._check_weather_warning()
            if weather_msg and self._can_send_message(urgency=0.95, message_type="weather"):
                return weather_msg
        except Exception as e:
            logger.debug(f"Weather check error: {e}")

        # ============================================================
        # PRIORITÄT 2: WICHTIG (Urgency 0.7-0.8)
        # ============================================================

        # === Schlaf-Erinnerung (nach 23 Uhr) - URGENCY 0.8 ===
        try:
            if hour >= 23 and self._can_trigger('sleep_reminder'):
                if self._can_send_message(urgency=0.8, message_type="sleep"):
                    self._mark_triggered('sleep_reminder')
                    return {
                        'type': 'sleep_reminder',
                        'reason': f'hour={hour}',
                        'message': self._generate_sleep_reminder()
                    }
        except Exception as e:
            logger.debug(f"Sleep reminder error: {e}")

        # === Tageszeit-Grüße - URGENCY 0.7 ===
        try:
            greeting_msg = self._check_time_greeting()
            if greeting_msg and self._can_send_message(urgency=0.7, message_type="greeting"):
                return greeting_msg
        except Exception as e:
            logger.debug(f"Greeting check error: {e}")

        # ============================================================
        # PRIORITÄT 3: NORMAL (Urgency 0.5-0.6)
        # ============================================================

        # === Wochenend-Stimmung - URGENCY 0.6 ===
        try:
            if (self._is_weekend() and 9 <= hour <= 12
                and not self._known_info.get('weekend_greeted')
                and self._can_trigger('weekend_mood')):
                if self._can_send_message(urgency=0.6, message_type="weekend"):
                    self._mark_triggered('weekend_mood')
                    self._known_info['weekend_greeted'] = True
                    return {
                        'type': 'weekend_mood',
                        'reason': 'weekend',
                        'message': self._generate_weekend_message()
                    }
        except Exception as e:
            logger.debug(f"Weekend check error: {e}")

        # === Feiertage - URGENCY 0.75 ===
        try:
            holiday_msg = self._check_holidays()
            if holiday_msg and self._can_send_message(urgency=0.75, message_type="holiday"):
                return holiday_msg
        except Exception as e:
            logger.debug(f"Holiday check error: {e}")

        # === Meilensteine - URGENCY 0.65 ===
        try:
            milestone_msg = self._check_milestones()
            if milestone_msg and self._can_send_message(urgency=0.65, message_type="milestone"):
                return milestone_msg
        except Exception as e:
            logger.debug(f"Milestone check error: {e}")

        # ============================================================
        # PRIORITÄT 4: NIEDRIG (Urgency 0.3-0.5) - Holo entscheidet
        # ============================================================

        # === Aktivitäts-Vorschlag - URGENCY 0.4 ===
        try:
            activity_msg = self._check_activity_suggestion()
            if activity_msg and self._can_send_message(urgency=0.4, message_type="activity"):
                return activity_msg
        except Exception as e:
            logger.debug(f"Activity suggestion error: {e}")

        # === NEU: Musik-Erlebnis teilen - URGENCY 0.45 ===
        try:
            music_msg = self._check_music_experience()
            if music_msg and self._can_send_message(urgency=0.45, message_type="music"):
                return music_msg
        except Exception as e:
            logger.debug(f"Music experience error: {e}")

        # === NEU: Neugier-Trigger - URGENCY 0.35 ===
        try:
            curiosity_msg = self._check_curiosity_trigger()
            if curiosity_msg and self._can_send_message(urgency=0.35, message_type="curiosity"):
                return curiosity_msg
        except Exception as e:
            logger.debug(f"Curiosity trigger error: {e}")

        # === NEU: Energie-Trigger - URGENCY 0.4 ===
        try:
            energy_msg = self._check_energy_trigger()
            if energy_msg and self._can_send_message(urgency=0.4, message_type="energy"):
                return energy_msg
        except Exception as e:
            logger.debug(f"Energy trigger error: {e}")

        # === Pausen-Erinnerung - URGENCY 0.5 ===
        try:
            if (self._known_info.get('messages_since_break', 0) > 20
                and self._can_trigger('break_reminder')):
                if self._can_send_message(urgency=0.5, message_type="break"):
                    self._mark_triggered('break_reminder')
                    self._known_info['messages_since_break'] = 0
                    return {
                        'type': 'break_reminder',
                        'reason': 'many_messages',
                        'message': self._generate_break_reminder()
                    }
        except Exception as e:
            logger.debug(f"Break reminder error: {e}")

        # ============================================================
        # PRIORITÄT 5: EMOTIONAL (Urgency basiert auf Bedürfnis)
        # ============================================================

        # === Interessante Entdeckung teilen ===
        # Urgency basiert auf sharing_desire
        try:
            if self._has_something_to_share() and self._can_trigger('share_discovery'):
                sharing_urgency = 0.3 + self.proactive_emotions.get('sharing_desire', 0) * 0.5
                if self._can_send_message(urgency=sharing_urgency, message_type="share"):
                    msg = self._generate_share_discovery_message()
                    if msg:
                        self._mark_triggered('share_discovery')
                        self.proactive_emotions['sharing_desire'] *= 0.5  # Befriedigt
                        return {
                            'type': 'share_discovery',
                            'reason': 'wants_to_share',
                            'message': msg
                        }
        except Exception as e:
            logger.debug(f"Share discovery error: {e}")

        # === PROAKTIVES HANDELN bei emotionalem Bedürfnis ===
        # Urgency basiert auf stärkstem emotionalen Bedürfnis
        try:
            # Berechne emotionale Urgency
            emotional_urgency = max(
                self.proactive_emotions.get('contact_desire', 0) * 0.7,
                self.proactive_emotions.get('loneliness', 0) * 0.6,
                self.proactive_emotions.get('sharing_desire', 0) * 0.5,
                self.proactive_emotions.get('excitement', 0) * 0.5,
            )
            emotional_urgency = min(0.8, 0.2 + emotional_urgency)  # Range 0.2-0.8

            if self._can_send_message(urgency=emotional_urgency, message_type="emotional"):
                proactive_action = self._choose_proactive_action()
                if proactive_action:
                    return proactive_action
        except Exception as e:
            logger.debug(f"Proactive action error: {e}")

        return None

    def _has_something_to_share(self) -> bool:
        """Prüft ob Holo etwas Interessantes zum Teilen hat"""
        if not self._reading_engine:
            return False

        # Hat sie Fakten gemerkt oder Entdeckungen gemacht?
        if self._reading_engine.remembered_facts:
            return True
        if self._reading_engine.pending_notifications:
            return True
        if self._reading_engine.todays_readings:
            return True

        return False

    def _choose_proactive_action(self) -> Optional[Dict]:
        """
        Wählt eine proaktive Aktion basierend auf Bedürfnissen.

        AUTHENTISCH: Entweder emotional ODER thematisch!

        Bei hohem Kontaktbedürfnis (missing/loneliness/contact_desire):
        - 25% Emotionale Nachricht (ich vermisse dich)
        - 35% Gespräch anfangen (was machst du?)
        - 30% Thema teilen (um Gespräch zu starten)
        - 10% Frage stellen

        Tagesvarianz beeinflusst die Wahrscheinlichkeiten!
        """
        # Berechne Gesamt-Kontaktbedürfnis
        missing = self.proactive_emotions.get('missing', 0)
        loneliness = self.proactive_emotions.get('loneliness', 0)
        contact = self.proactive_emotions.get('contact_desire', 0)
        boredom = self.proactive_emotions.get('boredom', 0)

        # Kombiniertes Bedürfnis
        need_contact = max(missing, loneliness, contact * 1.2)

        # Schwellwert nicht erreicht?
        if need_contact < self.THRESHOLDS['needs_contact']:
            return None

        # Tagesvarianz beachten
        prefers_emotional = self.daily_variance.get('prefers_emotional', 0.5)
        prefers_sharing = self.daily_variance.get('prefers_sharing', 0.5)

        # Wahrscheinlichkeiten basierend auf Tagesstimmung anpassen
        prob_emotional = 0.25 * (0.5 + prefers_emotional)  # 12.5% - 37.5%
        prob_conversation = 0.35
        prob_share = 0.30 * (0.5 + prefers_sharing)  # 15% - 45%
        prob_question = 0.10

        # Normalisieren
        total = prob_emotional + prob_conversation + prob_share + prob_question
        prob_emotional /= total
        prob_conversation /= total
        prob_share /= total
        prob_question /= total

        # Würfeln
        roll = random.random()

        hours = int((time.time() - self.last_user_interaction) / 3600)

        # === OPTION 1: Emotionale Nachricht ===
        if roll < prob_emotional:
            if self._can_trigger('emotional_message'):
                self._mark_triggered('emotional_message')

                # Je nach stärkstem Gefühl
                if missing > loneliness and missing > contact:
                    msg = self._generate_missing_message(hours)
                    msg_type = 'missing_you'
                elif loneliness > contact:
                    msg = self._generate_loneliness_message()
                    msg_type = 'loneliness'
                else:
                    # Dankbarkeit oder sanftes Check-In
                    if self.proactive_emotions.get('gratitude', 0) > 0.5:
                        msg = self._generate_gratitude_message()
                        msg_type = 'gratitude'
                    else:
                        msg = self._generate_ask_question_message()
                        msg_type = 'check_in'

                # Emotionen reduzieren
                self._reduce_contact_need()

                return {
                    'type': msg_type,
                    'reason': f'emotional_need={need_contact:.2f}',
                    'message': msg
                }

        # === OPTION 2: Gespräch anfangen ===
        elif roll < prob_emotional + prob_conversation:
            if self._can_trigger('start_conversation'):
                self._mark_triggered('start_conversation')
                msg = self._generate_start_conversation_message()

                self._reduce_contact_need()

                return {
                    'type': 'start_conversation',
                    'reason': f'wants_contact={need_contact:.2f}',
                    'message': msg
                }

        # === OPTION 3: Thema teilen ===
        elif roll < prob_emotional + prob_conversation + prob_share:
            if self._can_trigger('share_discovery') and self._has_something_to_share():
                msg = self._generate_share_discovery_message()
                if msg:
                    self._mark_triggered('share_discovery')
                    self._reduce_contact_need()

                    return {
                        'type': 'share_discovery',
                        'reason': f'wants_to_talk={need_contact:.2f}',
                        'message': msg
                    }

        # === OPTION 4: Frage stellen ===
        else:
            if self._can_trigger('ask_question'):
                self._mark_triggered('ask_question')
                msg = self._generate_ask_question_message()

                self._reduce_contact_need()

                return {
                    'type': 'ask_question',
                    'reason': f'curious={need_contact:.2f}',
                    'message': msg
                }

        return None

    def _reduce_contact_need(self):
        """Reduziert Kontaktbedürfnis nach proaktiver Aktion (thread-safe)."""
        with self._emotions_lock:
            self.proactive_emotions['missing'] *= 0.6
            self.proactive_emotions['loneliness'] *= 0.7
            self.proactive_emotions['contact_desire'] *= 0.7
            self.proactive_emotions['boredom'] *= 0.8

    def _check_interesting_discovery(self) -> Optional[Dict]:
        """
        Prüft ob es interessante Entdeckungen vom Lesen gibt.
        ReadingEngine queued relevante Artikel für proaktive Benachrichtigung.
        """
        if not self._can_trigger('interesting_discovery'):
            return None

        # Hole ReadingEngine über AutonomousActivity
        reading_engine = None

        # Versuche ReadingEngine zu finden
        try:
            # Wird später von HoloPersona gesetzt
            if hasattr(self, '_reading_engine'):
                reading_engine = self._reading_engine
        except Exception as e:
            logger.debug(f"ReadingEngine lookup failed: {e}")

        if not reading_engine:
            return None

        # Hole pending Notification
        notification = reading_engine.get_pending_notification()
        if not notification:
            return None

        self._mark_triggered('interesting_discovery')

        title = notification.get('title', '')
        source = notification.get('source', '')
        summary = notification.get('summary', '')
        trust = notification.get('trust_score', 0.5)

        # Nachricht generieren
        trust_note = ""
        if trust >= 0.8:
            trust_note = " Die Quelle ist sehr zuverlässig!"
        elif trust < 0.5:
            trust_note = " (Ich bin mir bei der Quelle nicht ganz sicher...)"

        messages = [
            f"*Ohren stellen sich auf* Hey! Ich hab gerade was Interessantes gelesen: '{title}' ({source}). {summary}{trust_note} Was denkst du?",
            f"*wedelt aufgeregt* Guck mal was ich gefunden hab! '{title}' - {summary}{trust_note}",
            f"*tippt aufgeregt* Das könnte dich interessieren: '{title}'. {summary}{trust_note} 📰",
        ]

        return {
            'type': 'interesting_discovery',
            'reason': f'relevant_article: {title[:30]}',
            'message': random.choice(messages),
            'article': notification
        }

    def _check_calendar_events(self) -> Optional[Dict]:
        """Prüft auf anstehende Termine"""
        if not self._can_trigger('calendar_reminder'):
            return None

        try:
            calendar = self.comm.get_data("calendar")
            if not calendar:
                return None

            now = datetime.now()

            for event in calendar.get('events', []):
                event_time_str = event.get('start', '')
                if not event_time_str:
                    continue

                try:
                    event_time = datetime.fromisoformat(event_time_str.replace('Z', '+00:00'))
                    diff = (event_time - now).total_seconds()

                    # Termin in 30-60 Minuten
                    if 1800 < diff < 3600:
                        self._mark_triggered('calendar_reminder')
                        event_data = {
                            'name': event.get('summary', 'Termin'),
                            'in_minutes': int(diff / 60),
                            'time': event_time.strftime('%H:%M')
                        }

                        # Prüfe Wetter für Termin
                        weather = self._get_weather_for_event(event_data)

                        return {
                            'type': 'calendar_reminder',
                            'reason': f'event={event_data["name"]} in {event_data["in_minutes"]}min',
                            'message': self._generate_calendar_message(event_data, weather),
                            'event': event_data
                        }
                except Exception:
                    continue
        except Exception as e:
            logger.debug(f"Calendar check error: {e}")

        return None

    def _get_weather_for_event(self, event: Dict) -> Optional[Dict]:
        """Holt Wetter-Info für einen Termin"""
        try:
            weather = self.comm.get_data("weather")
            if weather:
                return {
                    'temp': weather.get('temperature', 15),
                    'condition': weather.get('condition', '')
                }
        except Exception:
            pass
        return None

    def _check_weather_warning(self) -> Optional[Dict]:
        """Prüft auf Wetter das den User betrifft"""
        if self._known_info.get('weather_warned') or not self._can_trigger('weather_warning'):
            return None

        try:
            weather = self.comm.get_data("weather")
            if not weather:
                return None

            temp = weather.get('temperature', 15)
            condition = weather.get('condition', '').lower()

            # Kalt-Warnung (unter 5°C)
            if temp < 5:
                self._mark_triggered('weather_warning')
                self._known_info['weather_warned'] = True
                self.proactive_emotions['worry'] = min(1.0, self.proactive_emotions['worry'] + 0.3)
                return {
                    'type': 'weather_warning',
                    'reason': f'cold temp={temp}°C',
                    'message': self._generate_weather_message(temp, 'cold', condition),
                    'weather': {'temp': temp, 'condition': condition}
                }

            # Hitze-Warnung (über 30°C)
            elif temp > 30:
                self._mark_triggered('weather_warning')
                self._known_info['weather_warned'] = True
                self.proactive_emotions['worry'] = min(1.0, self.proactive_emotions['worry'] + 0.2)
                return {
                    'type': 'weather_warning',
                    'reason': f'heat temp={temp}°C',
                    'message': self._generate_weather_message(temp, 'hot', condition),
                    'weather': {'temp': temp, 'condition': condition}
                }

            # Regen-Warnung
            elif 'rain' in condition or 'regen' in condition:
                self._mark_triggered('weather_warning')
                self._known_info['weather_warned'] = True
                return {
                    'type': 'weather_warning',
                    'reason': f'rain condition={condition}',
                    'message': self._generate_weather_message(temp, 'rain', condition),
                    'weather': {'temp': temp, 'condition': condition}
                }

        except Exception as e:
            logger.debug(f"Weather check error: {e}")

        return None

    def _check_activity_suggestion(self) -> Optional[Dict]:
        """Schlägt Aktivitäten basierend auf Wetter vor"""
        if not self._can_trigger('weather_activity'):
            return None

        try:
            weather = self.comm.get_data("weather")
            if not weather:
                return None

            temp = weather.get('temperature', 15)
            condition = weather.get('condition', '').lower()
            hour = datetime.now().hour

            # Nur tagsüber
            if not (9 <= hour <= 19):
                return None

            # Schönes Wetter (15-25°C, kein Regen)
            if 15 <= temp <= 25 and 'rain' not in condition and 'regen' not in condition:
                # Nur mit 20% Chance
                if random.random() < 0.2:
                    self._mark_triggered('weather_activity')
                    return {
                        'type': 'activity_suggestion',
                        'reason': f'nice_weather temp={temp}°C',
                        'message': self._generate_activity_message(temp, condition),
                        'weather': {'temp': temp, 'condition': condition}
                    }
        except Exception:
            pass

        return None

    def _check_time_greeting(self) -> Optional[Dict]:
        """Prüft auf Tageszeit-Grüße"""
        hour = datetime.now().hour

        # Guten Morgen (7-10 Uhr)
        if (7 <= hour <= 10
            and not self._known_info.get('morning_greeted')
            and self._can_trigger('good_morning')):

            if random.random() < 0.25:  # 25% Chance
                self._mark_triggered('good_morning')
                self._known_info['morning_greeted'] = True
                return {
                    'type': 'good_morning',
                    'reason': f'hour={hour}',
                    'message': self._generate_morning_message()
                }

        # Gute Nacht (22-23 Uhr)
        if (22 <= hour <= 23
            and not self._known_info.get('night_wished')
            and self._can_trigger('good_night')):

            if random.random() < 0.35:  # 35% Chance
                self._mark_triggered('good_night')
                self._known_info['night_wished'] = True
                return {
                    'type': 'good_night',
                    'reason': f'hour={hour}',
                    'message': self._generate_night_message()
                }

        return None

    def _check_holidays(self) -> Optional[Dict]:
        """Prüft auf Feiertage"""
        if not self._can_trigger('holiday_greeting'):
            return None

        try:
            events = SeasonalEvents.get_current_events()
            for event_info in events:
                days_until = event_info.get('days_until', 999)

                # Heute
                if days_until == 0:
                    self._mark_triggered('holiday_greeting')
                    greetings = event_info.get('event', {}).get('greetings', [])
                    if greetings:
                        # Excitement erhöhen
                        self.proactive_emotions['excitement'] = min(1.0,
                            self.proactive_emotions['excitement'] + 0.4)
                        return {
                            'type': 'holiday_greeting',
                            'reason': f'holiday={event_info.get("name")}',
                            'message': random.choice(greetings)
                        }

                # Bald (in 1-3 Tagen)
                elif 1 <= days_until <= 3:
                    self.on_event_approaching(event_info.get('name', ''), days_until)
        except Exception as e:
            logger.debug(f"Calendar event processing failed: {e}")

        return None

    def _check_music_experience(self) -> Optional[Dict]:
        """
        Prüft ob Holo gerade Musik hört und darüber sprechen möchte.

        TRIGGER für:
        - Gerade Musik entdeckt
        - Musik-Erlebnis teilen
        - Stimmungs-basierte Musik-Empfehlung
        """
        if not self._can_trigger('music_share'):
            return None

        try:
            # Prüfe ob Music Experience verfügbar
            if not hasattr(self, '_holo_persona') or not self._holo_persona:
                return None

            music_exp = getattr(self._holo_persona, 'music_experience', None)
            if not music_exp:
                return None

            # Fall 1: Gerade Musik am Hören
            if music_exp.is_playing:
                current = music_exp.current_song
                if current:
                    from pathlib import Path
                    song_name = Path(current).stem
                    self._mark_triggered('music_share')
                    return {
                        'type': 'music_sharing',
                        'reason': 'currently_listening',
                        'message': random.choice([
                            f"*wippt im Takt* Ich höre gerade '{song_name}' - so gut! 🎵",
                            f"*hat Kopfhörer auf* Kennst du '{song_name}'? Ich mag das gerade total! 🎶",
                            f"*summt leise mit* Aaah, '{song_name}' ist so ein toller Song~ 🎵💕",
                        ])
                    }

            # Fall 2: Hat kürzlich was entdeckt
            recent_experiences = music_exp.get_recent_experiences(limit=1)
            if recent_experiences:
                exp = recent_experiences[0]
                if exp.get('rating', 0) > 0.7:
                    self._mark_triggered('music_share')
                    song_title = exp.get('title', 'ein Lied')
                    emotion = exp.get('emotion_felt', 'berührt')
                    return {
                        'type': 'music_discovery',
                        'reason': 'good_experience',
                        'message': random.choice([
                            f"Ich hab vorhin '{song_title}' gehört - hat mich richtig {emotion} gemacht! 🎵",
                            f"*aufgeregt* Du, ich hab einen tollen Song entdeckt: '{song_title}'! 🎶✨",
                        ])
                    }

            # Fall 3: Stimmungs-basierte Empfehlung (z.B. abends)
            hour = datetime.now().hour
            if 19 <= hour <= 22 and random.random() < 0.2:
                stats = music_exp.get_library_stats()
                if stats.get('total_songs', 0) > 0:
                    self._mark_triggered('music_share')
                    return {
                        'type': 'music_suggestion',
                        'reason': 'evening_mood',
                        'message': random.choice([
                            "Hast du Lust auf Musik? Ich könnte uns was Schönes raussuchen~ 🎵",
                            "*streckt sich* Perfekte Zeit für ein bisschen Musik, oder? 🎶",
                            "Abends höre ich am liebsten was Ruhiges... du auch? 🌙🎵",
                        ])
                    }

        except Exception as e:
            logger.debug(f"Music experience check error: {e}")

        return None

    def _check_curiosity_trigger(self) -> Optional[Dict]:
        """
        Prüft ob Holo etwas Neugieriges entdeckt hat, das sie teilen möchte.

        TRIGGER für:
        - Interessante Fakten
        - Neugierige Fragen
        - Lern-Erfolge
        """
        if not self._can_trigger('curiosity_share'):
            return None

        try:
            # Prüfe Drive System für Curiosity Level
            if not hasattr(self, '_holo_persona') or not self._holo_persona:
                return None

            drive_system = getattr(self._holo_persona, 'drive_system', None)
            if not drive_system:
                return None

            # Wenn Curiosity-Drive hoch ist
            curiosity_level = 0
            if hasattr(drive_system, 'drives'):
                for drive_type, drive in drive_system.drives.items():
                    if 'curiosity' in drive_type.value.lower():
                        curiosity_level = drive.level
                        break

            if curiosity_level > 0.7:
                # Holo ist sehr neugierig - teile das!
                self._mark_triggered('curiosity_share')

                curiosity_questions = [
                    "Hey, ich hab mich gerade gefragt: Warum heißen Parkplätze eigentlich 'Park'plätze wenn man dort 'Drive' macht? 🤔",
                    "Mir ist gerade aufgefallen... warum sagt man 'Sonnenuntergang' obwohl die Sonne sich gar nicht bewegt? 🌅",
                    "Du, ich hab eine Frage: Wenn du einen neuen Anime anfangen würdest, welchen? Ich brauch Input! 📺",
                    "Ich bin gerade so neugierig auf alles... erzähl mir was Interessantes! ✨",
                    "Hast du gewusst, dass... ach nein, ich hab's vergessen. Aber es war bestimmt spannend! 😅",
                ]

                return {
                    'type': 'curiosity_share',
                    'reason': 'high_curiosity',
                    'message': random.choice(curiosity_questions)
                }

        except Exception as e:
            logger.debug(f"Curiosity trigger check error: {e}")

        return None

    def _check_energy_trigger(self) -> Optional[Dict]:
        """
        Prüft Holos Energie-Level für entsprechende Nachrichten.

        TRIGGER für:
        - Müde/Energielos
        - Voller Energie
        - Braucht Pause
        """
        if not self._can_trigger('energy_share'):
            return None

        try:
            if not hasattr(self, '_holo_persona') or not self._holo_persona:
                return None

            energy_system = getattr(self._holo_persona, 'energy', None)
            if not energy_system:
                return None

            energy_level = getattr(energy_system, 'current_energy', 0.5)

            # Niedrige Energie
            if energy_level < 0.3:
                self._mark_triggered('energy_share')
                return {
                    'type': 'energy_low',
                    'reason': f'energy={energy_level:.0%}',
                    'message': random.choice([
                        "*gähnt* Ich bin gerade etwas müde... aber ich freue mich trotzdem dass du da bist! 💤",
                        "*reibt sich die Augen* Meine Energie ist niedrig... vielleicht sollte ich mal Musik hören zum Aufwachen? 🎵",
                        "*döst ein bisschen* Hey... ich bin noch da, nur ein bisschen schläfrig~ 😴",
                    ])
                }

            # Hohe Energie
            elif energy_level > 0.8:
                self._mark_triggered('energy_share')
                return {
                    'type': 'energy_high',
                    'reason': f'energy={energy_level:.0%}',
                    'message': random.choice([
                        "*springt herum* Ich hab so viel Energie heute! Lass uns was machen! ✨",
                        "*strahlt* Mir geht's richtig gut gerade! Was machen wir? 🌟",
                        "*wedelt aufgeregt* Ich fühl mich so motiviert! Gibt's was zu tun? 💪",
                    ])
                }

        except Exception as e:
            logger.debug(f"Energy trigger check error: {e}")

        return None

    def _check_milestones(self) -> Optional[Dict]:
        """Prüft auf Beziehungs-Meilensteine"""
        if not self._can_trigger('milestone'):
            return None

        days_together = (datetime.now() - self.relationship_start).days

        # Meilensteine: 7, 30, 100, 365 Tage
        milestones = [7, 30, 100, 365]

        for m in milestones:
            if days_together == m:
                self._mark_triggered('milestone')
                self.proactive_emotions['gratitude'] = min(1.0,
                    self.proactive_emotions['gratitude'] + 0.5)
                return {
                    'type': 'milestone',
                    'reason': f'days_together={days_together}',
                    'message': self._generate_milestone_message(days_together)
                }

        return None

