                self.fuzzy_matcher = AdvancedFuzzyMatcher() if AdvancedFuzzyMatcher else None
                self.sentiment_analyzer = AdvancedSentimentAnalyzer() if AdvancedSentimentAnalyzer else None
                self.entity_extractor = EntityExtractor() if EntityExtractor else None
                self.dialogue_act_classifier = DialogueActClassifier() if DialogueActClassifier else None
                self.anti_repetition = AntiRepetitionTracker() if AntiRepetitionTracker else None
                logger.info("🧠 NLP v5.1 aktiviert (Vector, Fuzzy, Sentiment, NER, LLM-Routing)")
