    def remember_emotional_moment(self, trigger: str, emotion: str,
                                   intensity: float, valence: float,
                                   context: str = ""):
        """
        Speichert eine emotionale Erinnerung.

        Args:
            trigger: Was die Emotion ausgelöst hat
            emotion: Art der Emotion (freude, trauer, etc.)
            intensity: Stärke (0-1)
            valence: Positiv/Negativ (-1 bis +1)
            context: Zusätzlicher Kontext

        Returns:
            Die gespeicherte EmotionalMemory oder None
        """
        if not hasattr(self, 'emotional_memory_store') or not self.emotional_memory_store:
            return None

        return self.emotional_memory_store.add_memory(
            trigger, emotion, intensity, valence, context
        )

    def find_similar_memories(self, trigger: str) -> List:
        """
        Findet ähnliche emotionale Erinnerungen.

        Args:
            trigger: Auslöser zum Suchen

        Returns:
            Liste ähnlicher EmotionalMemory
        """
        if not hasattr(self, 'emotional_memory_store') or not self.emotional_memory_store:
            return []

        return self.emotional_memory_store.find_similar(trigger)

    def get_strongest_memories(self, limit: int = 5) -> List:
        """
        Gibt die stärksten emotionalen Erinnerungen zurück.
        """
        if not hasattr(self, 'emotional_memory_store') or not self.emotional_memory_store:
            return []

        return self.emotional_memory_store.get_strongest(limit)

