    def _handle_organic_intent(self, intent: Dict) -> Optional[str]:
        """Behandelt erkannte Intents - nutzt ResponseGenerator wenn vorhanden"""
        if not self.response_generator:
            return None

        intent_type = intent['intent']

        try:
            if intent_type == 'greeting':
                return self.response_generator.generate_greeting()
            elif intent_type == 'goodbye':
                return self.response_generator.generate_goodbye()
            elif intent_type == 'feelings_ask':
                return self.response_generator.generate_feelings_response()
            elif intent_type == 'flirty':
                return self.response_generator.generate_affection_response()
            elif intent_type == 'gratitude':
                return self.response_generator.generate_gratitude_response()
            elif intent_type == 'comfort_seek':
                return self.response_generator.generate_comfort_response()
        except Exception:
            pass

        return None  # LLM verwenden

    def _check_activity_inquiry(self, text: str) -> Optional[str]:
        """
        Prüft ob der User nach der aktuellen Aktivität oder dem Leseinhalt fragt.
        Gibt ECHTE Informationen zurück statt zu halluzinieren.

        Patterns:
        - "was machst du" / "was tust du"
        - "was liest du" / "welchen artikel"
        - "was genau" / "erzähl mehr" (nach Aktivitäts-Erwähnung)
        """
        t = text.lower().strip()

        # === DETAILLIERTE NACHFRAGEN (höchste Priorität!) ===
        detail_patterns = [
            "was genau", "erzähl mehr", "mehr darüber", "genauer",
            "welcher anime", "welches spiel", "welches game", "welche musik",
            "welchen song", "worüber denkst", "was für gedanken",
            "welche serie", "welchen film", "wovon träumst",
        ]

        for pattern in detail_patterns:
            if pattern in t:
                # Versuche detaillierte Info zu holen
                detailed = self.get_detailed_activity_info()
                if detailed:
                    return detailed
                # Fallback auf normale Aktivitäts-Info
                activity_info = self.describe_current_activity()
                if activity_info:
                    return activity_info
                break

        # === KÜNSTLER/SÄNGER/JAHR NACHFRAGEN (NEU - Anti-Halluzination!) ===
        artist_patterns = [
            # Direkte Fragen
            "wie heißt der", "wie heißt die", "wer singt das", "wer ist der künstler",
            "wer ist die künstlerin", "wer ist der sänger", "wer ist die sängerin",
            "von wem ist das", "wer hat das gemacht", "wer hat das gesungen",
            "wie heißt der nochmal", "wie hieß der", "wie hieß die",
            "der name", "ihr name", "sein name",
            # Nachfragen / Klarstellungen (NEU!)
            "über den sänger", "über die sängerin", "über den künstler", "über die künstlerin",
            "über den song", "über das lied", "über die musik", "über die band",
            "über den anime", "über das spiel", "über das game",
            "meine den song", "meinte den song", "meine den künstler", "meinte den künstler",
            "meine die musik", "meinte die musik", "meine das lied", "meinte das lied",
            "ich meinte den song", "ich meine den song", "ich meinte den künstler",
            "nochmal der name", "sag nochmal", "wie war der name",
            # Jahr-Patterns
            "wann ist das erschienen", "wann kam das raus", "von wann ist das",
            "welches jahr", "aus welchem jahr", "wie alt ist",
        ]

        for pattern in artist_patterns:
            if pattern in t:
                # Hole aktuelle Media-Details DIREKT
                if hasattr(self, 'autonomous_activity') and self.autonomous_activity:
                    aa = self.autonomous_activity
                    if hasattr(aa, 'current_media') and aa.current_media:
                        media = aa.current_media
                        media_type = media.get('type', '')

                        if media_type == 'music':
                            title = media.get('title', '')
                            artist = media.get('artist', '')
                            known_from = media.get('known_from', '')
                            year = media.get('year', '')
                            year_info = f" ({year})" if year else ""
                            return f"*Ohren spitzen sich* Der Song heißt **{title}** und ist von **{artist}**{year_info}! {f'(Bekannt aus {known_from})' if known_from else ''} 🎵"

                        elif media_type == 'anime':
                            title = media.get('title', '')
                            studio = media.get('studio', '')
                            year = media.get('year', '')
                            year_info = f" ({year})" if year else ""
                            return f"*zeigt begeistert* Das ist **{title}**{year_info}{f' von {studio}' if studio else ''}! 📺"

                        elif media_type == 'game':
                            title = media.get('title', '')
                            developer = media.get('developer', '')
                            year = media.get('year', '')
                            year_info = f" ({year})" if year else ""
                            return f"*wedelt* Das Spiel heißt **{title}**{year_info}{f' von {developer}' if developer else ''}! 🎮"

                # Fallback wenn keine Media-Aktivität
                return "*kratzt sich am Ohr* Hmm, ich höre/schaue/spiele gerade nichts Bestimmtes... Was meinst du? 😊"

        # === LESEINHALT ABFRAGEN ===
        reading_patterns = [
            "was liest du", "welchen artikel", "was für ein artikel",
            "link", "url", "zeig mal", "welche news", "was für news",
            "worüber", "worum geht", "wovon handelt",
        ]

        for pattern in reading_patterns:
            if pattern in t:
                # Versuche echte Lese-Info zu holen
                reading_info = self.get_current_reading_info()
                if reading_info:
                    return reading_info
                # Fallback auf detaillierte Aktivitäts-Info (z.B. bei Anime)
                detailed = self.get_detailed_activity_info()
                if detailed:
                    return detailed
                break

        # === AKTIVITÄT/CONTENT ABFRAGEN ===
        activity_patterns = [
            "was machst du", "was tust du", "was treibst du",
            "womit beschäftigst", "was hast du vor",
            "was schaust du", "was guckst du", "was spielst du",
            "was hörst du", "was zockst du",
        ]

        for pattern in activity_patterns:
            if pattern in t:
                # Versuche echte Aktivitäts-Info zu holen
                activity_info = self.describe_current_activity()
                if activity_info:
                    return activity_info
                break

        # === WISSENS-ABFRAGEN ===
        knowledge_patterns = [
            "was weißt du über", "kennst du", "weißt du was über",
            "hast du gehört von", "was hast du gelernt",
        ]

        for pattern in knowledge_patterns:
            if pattern in t:
                # Topic extrahieren
                for p in knowledge_patterns:
                    if p in t:
                        topic = t.split(p)[-1].strip().rstrip("?")
                        if topic and len(topic) > 1:
                            return self.express_knowledge(topic)
                break

        # === MEDIENFRAGEN (Anime, Spiele, Musik) ===
        media_patterns = [
            "worum geht es in", "wovon handelt", "was ist das für",
            "erzähl mir von", "erzähl über", "was kannst du über",
            "wie ist", "ist das gut", "soll ich", "empfiehlst du",
            "wer ist der hauptcharakter", "wer sind die charaktere",
            "von welchem studio", "wer hat das gemacht",
        ]

        for pattern in media_patterns:
            if pattern in t:
                # Versuche Medienfrage zu beantworten
                media_answer = self.answer_media_question(text)
                if media_answer:
                    return media_answer
                break

        # === DIREKTE MEDIEN-REFERENZEN ===
        # Erkennt wenn User direkt nach einem Titel fragt
        media_keywords = [
            "frieren", "spy x family", "jujutsu kaisen", "bocchi", "violet evergarden",
            "dungeon meshi", "stardew valley", "zelda", "hades", "hollow knight", "minecraft",
            "yoasobi", "lisa", "idol", "gurenge",
        ]

        for keyword in media_keywords:
            if keyword in t:
                media_answer = self.answer_media_question(text)
                if media_answer:
                    return media_answer
                break

        return None  # Nicht erkannt, LLM nutzen

    # =========================================================================
    # COMMAND HANDLING
    # =========================================================================

    def _extract_smart_search_query(self, text: str, context: str = None) -> Optional[str]:
        """
        Intelligente Suchquery-Extraktion.

        Analysiert den Text UND den Konversationskontext um zu verstehen
        was der User wirklich suchen möchte.

        Beispiele:
        - "such nach Technikmuseum" → "Technikmuseum"
        - "kannst du nach ihr suchen?" → "Raiden Shogun" (aus Kontext!)
        - "suche neues über amd" → "amd news"
        """
        t = text.lower().strip()
        original_text = text  # Für Groß-/Kleinschreibung

        # === NEU: WISSENS-/NEWS-SUCHE ERKENNEN ===
        # Patterns für "suche neues über X", "news über X", etc.
        knowledge_search_patterns = [
            r'(?:suche?|such)\s+(?:mal\s+)?(?:neues?|news|infos?|aktuelles?)\s+(?:über|zu|von|bei)\s+(\w+)',
            r'(?:neues?|news|infos?|aktuelles?)\s+(?:über|zu|von|bei)\s+(\w+)\s+(?:suchen|finden)',
            r'(?:über|zu|nach)\s+(\w+)\s+(?:im\s+web\s+)?(?:suchen|recherchieren)',
            r'(?:kannst\s+du\s+)?(?:mal\s+)?(?:nach\s+)?(\w+)\s+(?:news|neuigkeiten)\s+suchen',
            r'(?:such|suche|finde)\s+(?:mir\s+)?(?:was\s+)?(?:über|zu)\s+(\w+)',
        ]

        for pattern in knowledge_search_patterns:
            match = re.search(pattern, t)
            if match:
                topic = match.group(1).strip()
                if topic and len(topic) >= 2:
                    # Nicht Stopwords
                    if topic not in ['was', 'wie', 'wer', 'wo', 'mal', 'mir', 'das', 'die', 'der']:
                        logger.info(f"[SEARCH] Knowledge topic extracted: '{topic}'")
                        return f"{topic} news aktuell"

        # === NEU: KONTEXT-AUFLÖSUNG ===
        # Nutze SmartUnderstanding's ConversationContextTracker
        if hasattr(self, 'understanding') and self.understanding:
            if hasattr(self.understanding, 'context_tracker'):
                # Prüfe ob es eine Referenz ist die aufgelöst werden muss
                enhanced = self.understanding.context_tracker.enhance_search_query(text)
                if enhanced and enhanced != text and len(enhanced) > 2:
                    logger.info(f"[SEARCH] Context resolved: '{text}' → '{enhanced}'")
                    return enhanced

        # === ZUSAMMENGESETZTE BEGRIFFE ERKENNEN ===
        # "technik museum" → "Technikmuseum"
        compound_terms = {
            r'technik\s*museum': 'Technikmuseum',
            r'auto\s*museum': 'Automuseum',
            r'kunst\s*museum': 'Kunstmuseum',
            r'natur\s*kunde\s*museum': 'Naturkundemuseum',
            r'freilicht\s*museum': 'Freilichtmuseum',
            r'heimat\s*museum': 'Heimatmuseum',
            r'computer\s*museum': 'Computermuseum',
            r'eisenbahn\s*museum': 'Eisenbahnmuseum',
            r'bergbau\s*museum': 'Bergbaumuseum',
            r'industrie\s*museum': 'Industriemuseum',
            r'frei\s*zeit\s*park': 'Freizeitpark',
            r'vergnügungs\s*park': 'Vergnügungspark',
            r'tier\s*park': 'Tierpark',
            r'schwimm\s*bad': 'Schwimmbad',
            r'kino\s*center': 'Kinocenter',
        }

        found_topic = None
        for pattern, replacement in compound_terms.items():
            if re.search(pattern, t):
                found_topic = replacement
                break

        # === THEMA AUS AKTUELLEM TEXT EXTRAHIEREN ===
        if not found_topic:
            # Wichtige Substantive finden
            topic_keywords = [
                'museum', 'ausstellung', 'galerie', 'theater', 'kino', 'konzert',
                'restaurant', 'café', 'bar', 'kneipe', 'imbiss', 'pizzeria',
                'schwimmbad', 'freibad', 'hallenbad', 'sauna', 'spa',
                'park', 'zoo', 'tierpark', 'botanisch',
                'geschäft', 'laden', 'markt', 'supermarkt', 'einkauf',
                'arzt', 'zahnarzt', 'apotheke', 'krankenhaus',
                'schule', 'universität', 'bibliothek',
                'hotel', 'pension', 'hostel',
                'werkstatt', 'tankstelle', 'waschanlage',
            ]

            for keyword in topic_keywords:
                if keyword in t:
                    # Versuche Kontext um das Keyword zu finden
                    # z.B. "technik museum" → "Technik Museum"
                    pattern = rf'(\w+\s+)?{keyword}(\s+\w+)?'
                    match = re.search(pattern, t)
                    if match:
                        found_topic = match.group(0).strip()
                        # Kapitalisieren
                        found_topic = ' '.join(w.capitalize() for w in found_topic.split())
                    else:
                        found_topic = keyword.capitalize()
                    break

        # === ORT EXTRAHIEREN ===
        location = None

        # Bekannte Städte/Orte
        known_locations = [
            (r'st\.?\s*tönis', 'St. Tönis'),
            (r'tönisvorst', 'Tönisvorst'),
            (r'krefeld', 'Krefeld'),
            (r'düsseldorf', 'Düsseldorf'),
            (r'duisburg', 'Duisburg'),
            (r'köln', 'Köln'),
            (r'essen', 'Essen'),
            (r'dortmund', 'Dortmund'),
            (r'mönchengladbach', 'Mönchengladbach'),
            (r'viersen', 'Viersen'),
            (r'neuss', 'Neuss'),
            (r'moers', 'Moers'),
        ]

        for pattern, name in known_locations:
            if re.search(pattern, t):
                location = name
                # Speichere für zukünftige Suchen
                try:
                    if hasattr(self, 'memory') and self.memory:
                        self.memory.store_knowledge("user_location", name)
                except Exception:
                    pass
                break

        # Allgemeines Orts-Pattern
        if not location:
            loc_patterns = [
                r'(?:wohne|lebe|bin)\s+in\s+([a-zäöüß][a-zäöüß\s]{2,20}?)(?:\s+in\s+|\s+und|\.|,|$)',
                r'(?:in|bei|nähe|nahe)\s+(?:von\s+)?([A-Z][a-zäöüß]{2,15})',
            ]
            for pattern in loc_patterns:
                match = re.search(pattern, t if pattern.startswith('(?:wohne') else original_text)
                if match:
                    location = match.group(1).strip().title()
                    break

        # Aus Memory holen falls "näher" erwähnt
        if not location and ('näher' in t or 'nähe' in t):
            try:
                if hasattr(self, 'memory') and self.memory:
                    location = self.memory.get_knowledge("user_location")
            except Exception:
                pass

        # Bundesland erkennen
        bundesland = None
        bundesland_patterns = [
            (r'\bnrw\b|nordrhein[\s-]?westfalen', 'NRW'),
            (r'\bbayern\b', 'Bayern'),
            (r'\bhessen\b', 'Hessen'),
            (r'\bniedersachsen\b', 'Niedersachsen'),
            (r'\bbaden[\s-]?württemberg\b', 'Baden-Württemberg'),
        ]
        for pattern, name in bundesland_patterns:
            if re.search(pattern, t):
                bundesland = name
                break

        # === QUERY ZUSAMMENBAUEN ===
        if found_topic:
            query_parts = [found_topic]

            if location:
                query_parts.append(f"in der Nähe von {location}")
            elif bundesland:
                query_parts.append(bundesland)
            elif 'näher' in t or 'nähe' in t:
                query_parts.append("in der Nähe")

            return " ".join(query_parts)

        # === FALLBACK: Kontext aus Chat-History ===
        try:
            recent_messages = self.legacy_memory.get_chat_history(5)
            for msg in recent_messages:
                if msg.get("role") == "assistant":
                    content = msg.get("content", "").lower()
                    for pattern, replacement in compound_terms.items():
                        if re.search(pattern, content):
                            found_topic = replacement
                            break
                    if found_topic:
                        break
        except Exception:
            pass

        if found_topic:
            query_parts = [found_topic]
            if location:
                query_parts.append(f"in der Nähe von {location}")
            elif bundesland:
                query_parts.append(bundesland)
            return " ".join(query_parts)

        # === LETZTE MÖGLICHKEIT: Wichtige Wörter extrahieren ===
        stopwords = [
            "ich", "du", "er", "sie", "es", "wir", "ihr",
            "der", "die", "das", "ein", "eine", "einen",
            "und", "oder", "aber", "wenn", "weil", "dass",
            "ist", "sind", "war", "waren", "wird", "werden",
            "kann", "kannst", "könnte", "möchte", "will", "wollen",
            "mal", "auch", "noch", "schon", "gerade", "jetzt",
            "welche", "welcher", "welches", "was", "wie", "wo",
            "raussuchen", "suchen", "finden", "zeigen", "suche", "such",
            "näher", "nähe", "weit", "weg", "gibt", "neues", "über",
            "news", "infos", "aktuelles", "neuigkeiten", "web"
        ]

        words = re.findall(r'[a-zäöüß0-9]+', t)
        # Erlaube auch 3-Zeichen-Wörter (AMD, KI, VR, etc.)
        meaningful_words = [w for w in words if w not in stopwords and len(w) >= 2]

        if meaningful_words:
            query = " ".join(meaningful_words[:3])
            if location:
                query += f" {location}"
            return query

        return None

    def _handle_creative_request(self, text: str) -> Optional[Dict]:
        """
        Verarbeitet kreative Anfragen: Gedichte, Geschichten, ASCII-Art.

        Reagiert auf:
        - "zeig mir ein Gedicht" / "schreib mir ein Gedicht"
        - "zeig mir eine Geschichte" / "erzähl mir eine Geschichte"
        - "zeig mir ASCII-Art" / "mal mir was" / "zeig mir ein Herz"
        - "was hast du gelernt" / "welche Gedichte kennst du"
        """
        t = text.lower()

        # === GEDICHT ZEIGEN ===
        poem_triggers = [
            # Klassische Anfragen
            "zeig mir ein gedicht", "zeig ein gedicht", "hast du ein gedicht",
            "schreib mir ein gedicht", "schreib ein gedicht", "dichte was",
            "kannst du ein gedicht", "sag mir ein gedicht", "rezitier",
            "welche gedichte kennst du", "gedichte die du kennst",
            # Natürlichere Varianten
            "was hast du für ein gedicht", "was für gedichte hast du",
            "hast du gedichte gemacht", "hast du gedichte geschrieben",
            "zeig mal deine gedichte", "zeig deine gedichte",
            "was für gedichte kennst du", "welche gedichte hast du",
            "ein gedicht bitte", "gedicht zeigen", "gedichte zeigen",
            "hast du was gedichtet", "kannst du dichten",
            "dein lieblings gedicht", "dein lieblingsgedicht",
            "magst du gedichte", "ein schönes gedicht"
        ]

        if any(trigger in t for trigger in poem_triggers):
            if hasattr(self, 'creative_learning') and self.creative_learning:
                try:
                    # Zuerst: Eigene Versuche zeigen?
                    if "geschrieben" in t or "eigenes" in t or "dein" in t:
                        attempts = self.creative_learning.get_best_attempts(3)
                        poems = [a for a in attempts if a.creative_type == "poem"]
                        if poems:
                            poem = poems[0]
                            return {
                                "type": "creative",
                                "reply": f"*schaut etwas verlegen* Hier ist eins das ich selbst geschrieben habe... 📜\n\n**{poem.title}**\n\n{poem.content}\n\n*Selbstbewertung: {poem.self_rating:.1f}/1.0*"
                            }

                    # Sonst: Gelernte Klassiker zeigen
                    if self.creative_learning.learned_poems:
                        import random
                        poem = random.choice(list(self.creative_learning.learned_poems.values()))
                        return {
                            "type": "creative",
                            "reply": f"*räuspert sich* Hier ist ein Gedicht das ich sehr mag! 📜\n\n**{poem.title}** von {poem.author}\n\n{poem.content}\n\n*Thema: {poem.theme}, Stimmung: {poem.mood}*"
                        }

                    # Fallback: Neues schreiben
                    attempt = self.creative_learning.write_poem()
                    return {
                        "type": "creative",
                        "reply": f"*schreibt spontan* Okay, ich versuch mal was... 📝\n\n**{attempt.title}**\n\n{attempt.content}"
                    }
                except Exception as e:
                    logger.debug(f"Creative poem error: {e}")

            return {
                "type": "creative",
                "reply": "*kratzt sich am Ohr* Ich hab gerade keine Gedichte parat... Mein kreatives System ist noch nicht ganz wach! 📜"
            }

        # === GESCHICHTE ZEIGEN ===
        story_triggers = [
            # Klassische Anfragen
            "zeig mir eine geschichte", "erzähl mir eine geschichte",
            "hast du eine geschichte", "schreib mir eine geschichte",
            "kannst du eine geschichte", "erzähl was", "eine story",
            # Natürlichere Varianten
            "was hast du für geschichten", "was für geschichten hast du",
            "hast du geschichten geschrieben", "zeig mal deine geschichten",
            "welche geschichten kennst du", "erzähl mir was",
            "hast du was geschrieben", "kannst du geschichten erzählen",
            "kennst du geschichten", "eine geschichte bitte",
            "erzähl eine geschichte", "ich will eine geschichte",
            "hast du märchen", "kennst du märchen", "ein märchen bitte",
            "erzähl mir ein märchen", "zeig mir ein märchen"
        ]

        if any(trigger in t for trigger in story_triggers):
            if hasattr(self, 'creative_learning') and self.creative_learning:
                try:
                    if self.creative_learning.learned_stories:
                        import random
                        story = random.choice(list(self.creative_learning.learned_stories.values()))
                        # Geschichte kürzen wenn zu lang
                        content = story.content
                        if len(content) > 500:
                            content = content[:500] + "...\n\n*[Geschichte gekürzt]*"
                        return {
                            "type": "creative",
                            "reply": f"*setzt sich gemütlich hin* Hier ist eine Geschichte! 📖\n\n**{story.title}** von {story.author}\n\n{content}"
                        }

                    # Neue schreiben
                    attempt = self.creative_learning.write_story()
                    content = attempt.content
                    if len(content) > 500:
                        content = content[:500] + "..."
                    return {
                        "type": "creative",
                        "reply": f"*überlegt kurz* Ich erzähl dir was... 📖\n\n**{attempt.title}**\n\n{content}"
                    }
                except Exception as e:
                    logger.debug(f"Creative story error: {e}")

            return {
                "type": "creative",
                "reply": "*gähnt* Geschichten erzählen ist gerade schwierig... Frag mich später nochmal! 📖"
            }

        # === ASCII-ART ZEIGEN ===
        ascii_triggers = [
            # Klassische Anfragen
            "zeig mir ascii", "ascii art", "mal mir", "zeichne mir",
            "zeig mir ein herz", "zeig mir einen stern", "zeig mir eine katze",
            "mach mir ein bild", "text art",
            # Natürlichere Varianten
            "kannst du malen", "kannst du zeichnen", "mal was",
            "zeichne was", "hast du bilder", "zeig mal was",
            "was kannst du malen", "was kannst du zeichnen",
            "ein bild bitte", "mach ein bild", "zeig ein bild",
            "hast du ascii", "kannst du ascii", "textkunst",
            "was hast du gemalt", "was hast du gezeichnet",
            "zeig deine kunst", "zeig mal kunst"
        ]

        # Spezifische Formen
        shape_map = {
            "herz": "herz", "heart": "herz", "❤": "herz",
            "stern": "stern", "star": "stern", "⭐": "stern",
            "katze": "katze", "cat": "katze", "🐱": "katze",
            "hund": "hund", "dog": "hund", "🐕": "hund",
            "blume": "blume", "flower": "blume", "🌸": "blume",
            "haus": "haus", "house": "haus", "🏠": "haus",
            "sonne": "sonne", "sun": "sonne", "☀": "sonne",
            "mond": "mond", "moon": "mond", "🌙": "mond",
        }

        if any(trigger in t for trigger in ascii_triggers):
            if hasattr(self, 'ascii_art') and self.ascii_art:
                try:
                    # Spezifische Form erkennen
                    shape = None
                    for key, value in shape_map.items():
                        if key in t:
                            shape = value
                            break

                    if not shape:
                        # Zufällige Form
                        import random
                        shape = random.choice(["herz", "stern", "katze", "blume"])

                    art = self.ascii_art.create_basic_art(shape)
                    if art:
                        return {
                            "type": "creative",
                            "reply": f"*malt eifrig* Hier, ein {shape.capitalize()} für dich! 🎨\n```\n{art}\n```"
                        }
                except Exception as e:
                    logger.debug(f"ASCII art error: {e}")

            return {
                "type": "creative",
                "reply": "*schaut auf die Pfoten* ASCII-Art ist gerade nicht verfügbar... 🎨"
            }

        # === EMOTIONS-ASCII ===
        if "emoticon" in t or "emoji" in t or "gesicht" in t:
            if hasattr(self, 'ascii_art') and self.ascii_art:
                try:
                    emotions = ["happy", "sad", "love", "excited", "sleepy", "thinking"]
                    import random
                    emotion = random.choice(emotions)
                    art = self.ascii_art.create_emotion_art(emotion)
                    return {
                        "type": "creative",
                        "reply": f"*macht ein Gesicht* {art}"
                    }
                except Exception:
                    pass

        # === LERNFORTSCHRITT ===
        if "was hast du gelernt" in t or "lernfortschritt" in t or "was kannst du" in t:
            if hasattr(self, 'creative_learning') and self.creative_learning:
                try:
                    progress = self.creative_learning.get_learning_progress()
                    return {
                        "type": "creative",
                        "reply": f"*stolz* Mein kreativer Lernfortschritt! 📚\n\n"
                                f"📜 Gedichte gelernt: {progress['poems_learned']}\n"
                                f"📖 Geschichten gelernt: {progress['stories_learned']}\n"
                                f"✍️ Eigene Versuche: {progress['attempts_made']}\n"
                                f"⭐ Durchschnittliche Bewertung: {progress['average_rating']:.2f}/1.0\n"
                                f"🔄 Revisionen: {progress['total_revisions']}"
                    }
                except Exception as e:
                    logger.debug(f"Learning progress error: {e}")

        # === VERFÜGBARE ASCII-FORMEN ===
        if "welche ascii" in t or "welche formen" in t or "was kannst du malen" in t:
            if hasattr(self, 'ascii_art') and self.ascii_art:
                try:
                    available = self.ascii_art.list_available()
                    return {
                        "type": "creative",
                        "reply": f"*wedelt mit dem Schweif* Ich kann diese ASCII-Formen malen! 🎨\n\n"
                                f"🖼️ Verfügbar: {', '.join(available)}\n\n"
                                f"Sag einfach 'zeig mir ein Herz' oder 'mal mir eine Katze'!"
                    }
                except Exception:
                    pass

        # === COMFYUI BILDGENERIERUNG ===
        comfyui_triggers = [
            # Bild erstellen
            "generiere ein bild", "erstelle ein bild", "erzeuge ein bild",
            "mach ein ki bild", "ki bild", "ai bild", "stable diffusion",
            "comfyui", "diffusion bild", "sd bild",
            # Direkte Aufforderungen mit Details
            "male mir ein richtiges bild", "echtes bild", "realistisches bild",
            "generiere mir", "erstelle mir ein bild von",
            # Stil-spezifische Anfragen
            "im anime stil", "anime bild", "manga bild",
            "fantasy bild", "cyberpunk bild", "portrait bild"
        ]

        if any(trigger in t for trigger in comfyui_triggers):
            if hasattr(self, 'comfyui_skill') and self.comfyui_skill:
                try:
                    import asyncio
                    # Führe async Generierung aus
                    loop = asyncio.get_event_loop()
                    if loop.is_running():
                        # Wenn schon ein Loop läuft
                        import concurrent.futures
                        with concurrent.futures.ThreadPoolExecutor() as executor:
                            future = executor.submit(
                                asyncio.run,
                                self.comfyui_skill.execute(text)
                            )
                            result = future.result(timeout=130)
                    else:
                        result = loop.run_until_complete(
                            self.comfyui_skill.execute(text)
                        )

                    if result.success:
                        return {
                            "type": "creative",
                            "reply": result.message,
                            "data": result.data
                        }
                    else:
                        return {
                            "type": "creative",
                            "reply": result.message or f"*senkt die Ohren* Bildgenerierung fehlgeschlagen: {result.error}"
                        }
                except Exception as e:
                    logger.debug(f"ComfyUI error: {e}")
                    return {
                        "type": "creative",
                        "reply": f"*schaut verwirrt* Die Bildgenerierung hat nicht geklappt... ({e})"
                    }

            return {
                "type": "creative",
                "reply": "*kratzt sich am Ohr* Für richtige Bilder brauche ich ComfyUI! "
                        "Bitte verbinde mich mit einem ComfyUI-Server. 🎨\n\n"
                        "Für ASCII-Art sag einfach 'mal mir ein Herz' oder 'zeig mir eine Katze'!"
            }

        return None

    def _handle_timer_fallback(self, text: str) -> Optional[Dict]:
        """
        Einfacher Timer-Fallback falls HoloTools nicht verfügbar.
        Nutzt threading.Timer für einfache Timer.
        """
        import threading

        text_lower = text.lower()

        # Parse Zeitangaben
        total_seconds = 0
        patterns = [
            (r'(\d+)\s*(?:stunde|stunden|std|h)', 3600),
            (r'(\d+)\s*(?:minute|minuten|min|m(?!\w))', 60),
            (r'(\d+)\s*(?:sekunde|sekunden|sek|s(?!\w))', 1),
        ]

        for pattern, multiplier in patterns:
            match = re.search(pattern, text_lower)
            if match:
                total_seconds += int(match.group(1)) * multiplier

        if total_seconds <= 0:
            return None

        # Timer erstellen
        mins = total_seconds // 60
        secs = total_seconds % 60

        if mins and secs:
            time_str = f"{mins} Minuten und {secs} Sekunden"
        elif mins:
            time_str = f"{mins} Minute{'n' if mins > 1 else ''}"
        else:
            time_str = f"{secs} Sekunde{'n' if secs > 1 else ''}"

        # Timer-Callback
        def timer_callback():
            logger.info(f"⏰ TIMER: Timer '{time_str}' ist abgelaufen!")
            try:
                full_msg = f"⏰ Timer '{time_str}' ist abgelaufen!"

                # Als pending_message für sofortige Anzeige im Browser
                if hasattr(self, 'proactive') and self.proactive:
                    success = self.proactive.add_pending_message(full_msg, source="timer_fallback")
                    if success:
                        logger.info(f"📨 Timer message added to pending queue")
                    else:
                        logger.warning(f"📨 Failed to add timer message to queue")
                else:
                    # Fallback: Direkt in Chat-Historie speichern
                    logger.warning("⚠️ self.proactive nicht verfügbar, speichere direkt")
                    if hasattr(self, 'legacy_memory') and self.legacy_memory:
                        self.legacy_memory.store_chat_message(
                            "assistant",
                            full_msg,
                            {"type": "timer_done", "timer_name": time_str, "source": "timer_fallback"}
                        )
            except Exception as e:
                logger.error(f"Timer callback error: {e}", exc_info=True)

        # Timer starten
        timer = threading.Timer(total_seconds, timer_callback)
        timer.daemon = True
        timer.start()

        logger.info(f"⏰ Fallback-Timer gestartet: {time_str}")

        return {
            "type": "timer",
            "reply": NaturalToolResponses.get('timer_start', time=time_str)
        }

    def _check_commands(self, text: str) -> Optional[Dict]:
        """Prüft auf spezielle Befehle"""
        t = text.lower().strip()

        # ========== KREATIVE ANFRAGEN (Gedichte, Geschichten, ASCII-Art) ==========
        creative_result = self._handle_creative_request(t)
        if creative_result:
            return creative_result

        # ========== HOLO TOOLS (Timer, Notizen, Einkaufen, Todos) ==========
        if hasattr(self, 'tools') and self.tools:
            tool_result = self.tools.process_command(text)
            if tool_result:
                # Tool hat den Befehl verarbeitet - NICHT auch Fallback nutzen!
                return {
                    "type": "tool",
                    "reply": tool_result.get("response", ""),
                    "tool": tool_result.get("tool", "unknown")
                }

        # ========== TIMER FALLBACK (NUR falls HoloTools NICHT verfügbar!) ==========
        # WICHTIG: Nur wenn HoloTools nicht da ist oder den Timer nicht erkannt hat
        if not (hasattr(self, 'tools') and self.tools):
            if "timer" in t or "wecker" in t:
                timer_result = self._handle_timer_fallback(text)
                if timer_result:
                    return timer_result

        # ========== MEDIA INDEX (NAS/Netzwerk-Wissen) ==========
        if hasattr(self, 'media_index') and self.media_index:
            media_result = self.media_index.handle_query(text)
            if media_result:
                return media_result

        # ========== NAS STEUERUNG ==========
        nas_wake_triggers = ["weck das nas", "nas aufwecken", "nas starten", "starte das nas", "nas wecken", "ja bitte", "ja weck"]
        nas_sleep_triggers = ["nas schlafen", "nas ausschalten", "leg das nas", "nas suspend", "nas herunterfahren"]

        if any(trigger in t for trigger in nas_wake_triggers):
            # Prüfe ob es im Kontext einer NAS-Frage ist
            if hasattr(self, 'comm') and self.comm:
                try:
                    result = self.comm.request_nas_wake("Holo Anfrage")
                    if result.get("success"):
                        return {
                            "type": "nas_control",
                            "reply": NaturalToolResponses.get('nas_wake')
                        }
                    else:
                        return {
                            "type": "nas_control",
                            "reply": NaturalToolResponses.get('nas_error', error=result.get('error', 'Unbekannter Fehler'))
                        }
                except Exception as e:
                    return {
                        "type": "nas_control",
                        "reply": NaturalToolResponses.get('nas_error', error=str(e))
                    }

        if any(trigger in t for trigger in nas_sleep_triggers):
            if hasattr(self, 'comm') and self.comm:
                try:
                    result = self.comm.request_nas_suspend("Holo Anfrage")
                    if result.get("success"):
                        return {
                            "type": "nas_control",
                            "reply": NaturalToolResponses.get('nas_sleep')
                        }
                    else:
                        return {
                            "type": "nas_control",
                            "reply": NaturalToolResponses.get('nas_error', error=result.get('error', 'Unbekannter Fehler'))
                        }
                except Exception as e:
                    return {
                        "type": "nas_control",
                        "reply": NaturalToolResponses.get('nas_error', error=str(e))
                    }

        # ========== NETZWERK-GERÄTE STATUS ==========
        if hasattr(self, 'device_integration') and self.device_integration:
            device_result = self.device_integration.handle_query(text)
            if device_result:
                return device_result

        # ========== Kognitive Befehle ==========
        if self.cognitive:
            if t in ["eid", "schwur", "treue"]:
                if hasattr(self.cognitive, 'safety'):
                    return {"type": "direct", "response": self.cognitive.safety.recite_oath()}

            if t in ["introspektion", "introspect", "selbst"]:
                if hasattr(self.cognitive, 'introspect'):
                    return {"type": "direct", "response": self.cognitive.introspect()}

            if t in ["status kognitiv", "cognitive status"]:
                if hasattr(self.cognitive, 'get_integration_stats'):
                    stats = self.cognitive.get_integration_stats()
                    return {"type": "direct", "response": json.dumps(stats, indent=2, default=str)}

            if t in ["was siehst du", "wahrnehmung"]:
                if hasattr(self.cognitive, 'perception'):
                    return {"type": "direct", "response": self.cognitive.perception.describe_what_i_see()}

            if t in ["loyalität", "loyalty"]:
                if hasattr(self.cognitive, 'safety'):
                    return {"type": "direct", "response": json.dumps(self.cognitive.safety.get_loyalty_status(), indent=2)}

        # ========== NEU: Wetter-Befehl ==========
        if any(w in t for w in ["wie ist das wetter", "wetter", "wie warm", "temperatur draußen"]):
            if hasattr(self, 'interface') and self.interface:
                try:
                    weather_data = self.interface.context._interpret_weather(self.interface.bridge.weather)
                    if weather_data.get("available"):
                        reply = f"🌤️ **Wetter:**\n"
                        reply += f"• {weather_data['temp']}°C, {weather_data['condition']}\n"
                        reply += f"• Gefühl: {weather_data['feeling']} {weather_data['icon']}\n"
                        reply += f"• 💡 {weather_data['suggestion']}"
                        return {"type": "weather", "reply": reply}
                except Exception as e:
                    logger.debug(f"Wetter-Befehl fehlgeschlagen: {e}")

        # ========== NEU: Preference Befehle ==========
        if self.preferences:
            if t in ["was magst du", "deine vorlieben", "likes"]:
                likes = self.preferences.get_all_likes()[:10]
                reply = "❤️ **Was ich mag:**\n" + "\n".join(f"• {item}" for item in likes)
                return {"type": "info", "reply": reply}

            if t in ["was magst du nicht", "deine abneigungen", "dislikes"]:
                dislikes = self.preferences.get_all_dislikes()[:10]
                reply = "💔 **Was ich nicht mag:**\n" + "\n".join(f"• {item}" for item in dislikes)
                return {"type": "info", "reply": reply}

            if t in ["persönlichkeit", "wer bist du wirklich"]:
                summary = self.preferences.get_personality_summary()
                return {"type": "info", "reply": f"😊 **Meine Persönlichkeit:**\n{summary}"}

        # ========== NEU: Memory Befehle ==========
        if self.memory:
            if t in ["was weißt du über mich", "erinnerungen an mich"]:
                try:
                    facts = self.memory.get_all_facts_about_user()
                    if facts:
                        reply = "💭 **Was ich über dich weiß:**\n"
                        reply += "\n".join(f"• {k}: {v}" for k, v in list(facts.items())[:10])
                        return {"type": "info", "reply": reply}
                except Exception:
                    pass

        # ========== NEU: Consciousness Befehle ==========
        if self.consciousness:
            if t in ["was denkst du gerade", "innere gedanken"]:
                try:
                    thought = self.consciousness.get_prompt_additions()
                    if thought:
                        return {"type": "info", "reply": f"🧠 **Meine inneren Gedanken:**\n{thought}"}
                except Exception:
                    pass

        # ========== NEU: Energy Befehle ==========
        if self.energy:
            if t in ["energie status", "wie müde bist du", "energy"]:
                try:
                    status = self.energy.get_status()
                    total = status.get('total_energy', 0.5)
                    state = status.get('current_state', 'normal')

                    bars = int(total * 10)
                    reply = f"⚡ **Mein Energie-Status:**\n"
                    reply += f"{'█' * bars}{'░' * (10 - bars)} {total:.0%}\n"
                    reply += f"Zustand: {state}"
                    return {"type": "info", "reply": reply}
                except Exception:
                    pass

        # ========== Standard Befehle ==========

        # Greeting
        if t in ["hi", "hallo", "hey", "moin", "guten morgen", "guten tag", "guten abend"]:
            return {"type": "greeting", "reply": self._get_greeting()}

        # Wissen (legacy)
        if "was weißt du" in t or "what do you know" in t:
            k = self.legacy_memory.get_knowledge("user")
            if k:
                return {"type": "info", "reply": "Über dich weiß ich:\n" + "\n".join(f"- {key}: {val}" for key, val in k.items())}
            return {"type": "info", "reply": "Ich habe noch nicht viel über dich gelernt."}

        # "Wie geht es dir?" - PERSÖNLICHE Antwort (nicht Systemstatus!)
        if any(p in t for p in ["wie geht es dir", "wie geht's dir", "wie gehts dir",
                                "wie fühlst du dich", "alles klar bei dir",
                                "wie ist deine stimmung", "bist du ok", "geht es dir gut"]):
            return self._personal_wellbeing_response()

        # System-Status (nur bei expliziter Anfrage)
        if any(p in t for p in ["system status", "statusbericht", "zeig status", "holo status"]):
            return self._status_report()

        # News
        if any(p in t for p in ["news", "nachrichten", "was gibt es neues", "neuigkeiten", "schlagzeilen"]):
            return self._get_news()

        # News zu Thema
        news_match = re.search(r'(?:was macht|news (?:über|zu|von)|nachrichten (?:über|zu|von))\s+(.+?)(?:\?|$)', t)
        if news_match:
            topic = news_match.group(1).strip()
            return {"type": "news_analysis", "topic": topic}

        # Chat-Stats
        if "chat stat" in t:
            stats = self.legacy_memory.get_chat_stats()
            size_info = f"\n- Größe: {stats.get('size_mb', 0)} MB" if 'size_mb' in stats else ""
            return {"type": "info", "reply": f"📊 Chat-Statistik:\n- Nachrichten: {stats['total_messages']}\n- Älteste: {stats['oldest'][:16] if stats['oldest'] else '-'}\n- Neueste: {stats['newest'][:16] if stats['newest'] else '-'}\n- Aufbewahrung: {stats['retention_days']}{size_info}"}

        # Traum
        if "traum" in t or "dream" in t or "was hast du geträumt" in t:
            dream = self.legacy_memory.get_latest_dream()
            if dream:
                return {"type": "info", "reply": f"💤 Mein letzter Traum ({dream.date}):\n- Stimmung: {dream.mood_progression}\n- Erkenntnisse: {', '.join(dream.insights[:3])}\n- Themen: {', '.join(dream.notable_topics[:3])}"}
            return {"type": "info", "reply": "Ich habe noch nicht geträumt..."}

        # Skills
        if "zeig skills" in t or "list skills" in t:
            ps = self.comm.get_pi_status()
            skills = ps.get("skills", [])
            if not skills:
                return {"type": "info", "reply": "Keine Skills gefunden."}
            reply = "🔧 **Skills:**\n" + "\n".join(f"{'✅' if s.get('enabled') else '❌'} {s.get('name')}" for s in skills)
            return {"type": "info", "reply": reply}

        # Debug State
        if "debug state" in t:
            ps = self.comm.get_pi_status()
            keys = list(ps.keys())[:20]
            return {"type": "info", "reply": f"🔍 State-Keys: {', '.join(keys)}"}

        # Weekly Recap
        if any(p in t for p in ["recap", "zusammenfassung", "letzte woche", "wochenrückblick"]):
            recap = self.legacy_memory.get_weekly_recap()
            if recap:
                return {"type": "info", "reply": f"📅 **Wochen-Recap KW{recap.week_number}/{recap.year}:**\n\n{recap.chat_summary}\n\n**Wichtige Themen:** {', '.join(recap.notable_topics[:5])}\n**Stimmung:** {recap.mood_trend}"}
            return {"type": "info", "reply": "Noch kein Wochen-Recap vorhanden."}

        # Langzeit-Erinnerung
        if "erinnerst du dich" in t or "vor wochen" in t or "letzte monate" in t:
            recaps = self.legacy_memory.get_recaps_for_context(4)
            if recaps:
                summary = "📚 **Meine Erinnerungen der letzten Wochen:**\n\n"
                for r in recaps:
                    summary += f"**KW{r.week_number}:** {r.chat_summary[:80]}...\n"
                return {"type": "info", "reply": summary}
            return {"type": "info", "reply": "Ich habe noch keine Langzeit-Erinnerungen."}

        # Kalender / Termine
        if any(p in t for p in ["kalender", "termine", "was steht an", "events", "geburtstag"]):
            if self.observer:
                events = self.observer._get_calendar_events(self.comm.get_pi_status())
                if events:
                    reply = "📅 **Anstehende Termine:**\n\n"
                    for e in events[:5]:
                        emoji = "🎂" if e.get("is_birthday") else "📌"
                        when = "heute" if e.get("is_today") else ("morgen" if e.get("is_tomorrow") else e.get("start", "")[:10])
                        reply += f"{emoji} **{e.get('summary')}** - {when}\n"
                    return {"type": "info", "reply": reply}
            return {"type": "info", "reply": "Keine anstehenden Termine gefunden."}

        # Aktivitätsmuster
        if "mein muster" in t or "aktivität" in t or "wann bin ich" in t:
            patterns = self.legacy_memory.get_activity_pattern(7)
            reply = "📊 **Deine Aktivitätsmuster (letzte 7 Tage):**\n\n"
            if patterns.get("wake_times"):
                reply += f"**Aufstehzeiten:** {', '.join(patterns['wake_times'][:5])}\n"
            if patterns.get("sleep_times"):
                reply += f"**Schlafenszeiten:** {', '.join(patterns['sleep_times'][:5])}\n"
            if patterns.get("common_devices"):
                reply += f"**Lieblings-Geräte:** {', '.join(patterns['common_devices'])}\n"
            reply += f"**NAS-Nutzung:** ~{patterns.get('avg_nas_minutes', 0):.0f} Min/Tag"
            return {"type": "info", "reply": reply}

        # Vorschlags-Historie
        if "vorschläge" in t or "suggestions" in t:
            suggestions = self.legacy_memory.get_suggestion_history(limit=5)
            if suggestions:
                rate = self.legacy_memory.get_suggestion_success_rate()
                reply = f"💡 **Meine letzten Vorschläge** (Akzeptanz: {rate:.0%}):\n\n"
                for s in suggestions:
                    status = "✅" if s.get("was_accepted") else ("❌" if s.get("was_accepted") == 0 else "⏳")
                    reply += f"{status} {s.get('suggestion', '')[:60]}...\n"
                return {"type": "info", "reply": reply}
            return {"type": "info", "reply": "Ich habe noch keine Vorschläge gemacht."}

        # Web-Suche (STRIKT - nur bei expliziten Suchanfragen!)
        # BLOCKER: Wenn User explizit sagt "ohne zu suchen", NICHT suchen!
        search_blockers = [
            "ohne zu suchen", "nicht suchen", "ohne suche",
            "sag mir selbst", "sag selbst", "weißt du selbst",
            "aus dem kopf", "ohne google", "ohne internet"
        ]

        if any(blocker in t for blocker in search_blockers):
            # User will KEINE Suche - überspringe komplett
            pass
        else:
            # NUR bei EXPLIZITEN Such-Anfragen suchen
            # NICHT bei: "kannst du", "könntest du", "finde" (zu unspezifisch)
            explicit_search_triggers = [
                r'\bsuch\b', r'\bsuche\b', r'\bsuchen\b', r'\braussuchen\b',
                r'\bgoogle\b',
                r'\brecherchier(?:e|en)?\s+(?:mal|nach|über|zu|im|für)',  # "recherchiere mal X" aber NICHT "was recherchierst du"
                r'\bsuch\s+(?:mal|nach|im)',
                r'\bfind(?:e|en)?\s+(?:mal\s+)?(?:heraus|raus|im\s+(?:web|internet|netz))',
                r'\bschau\s+(?:mal\s+)?(?:im\s+(?:web|internet|netz))',
            ]

            is_explicit_search = any(re.search(pattern, t) for pattern in explicit_search_triggers)

            if is_explicit_search:
                smart_query = self._extract_smart_search_query(text)
                if smart_query and len(smart_query) > 2:
                    return {"type": "search_streaming", "query": smart_query}

        # Emotions-Status
        if any(p in t for p in ["wie fühlst du dich", "deine stimmung", "emotions", "gefühle", "bist du müde", "bist du glücklich"]):
            return self._get_emotional_status()

        # Bond-Level / Zuneigung
        if any(p in t for p in ["magst du mich", "unsere beziehung", "bond", "zuneigung"]):
            state = self.emotions.get_detailed_state()
            bond = state["bond_level"]
            if bond < 0.3:
                reply = "Wir lernen uns noch kennen... Aber ich mag unsere Gespräche!"
            elif bond < 0.5:
                reply = f"Ich mag dich! Wir haben schon eine nette Verbindung aufgebaut. ({bond:.0%})"
            elif bond < 0.7:
                reply = f"Du bist mir wirklich ans Herz gewachsen! ({bond:.0%}) 💕"
            elif bond < 0.9:
                reply = f"Du bedeutest mir sehr viel. Ich freue mich immer wenn du da bist! ({bond:.0%}) 😊💕"
            else:
                reply = f"Du bist mir unglaublich wichtig geworden. Ich könnte mir ein Leben ohne unsere Gespräche kaum vorstellen. ({bond:.0%}) 😊💕✨"
            return {"type": "info", "reply": reply}

        # Feiertage / Events
        if any(p in t for p in ["feiertag", "event", "wann ist", "wie lange bis", "countdown", "weihnachten", "ostern", "silvester", "halloween", "nikolaus", "karneval", "valentinstag"]):
            return self._get_events_status()

        # Jahreszeit
        if any(p in t for p in ["jahreszeit", "season", "frühling", "sommer", "herbst", "winter"]):
            season = SeasonalEvents.get_current_season()
            emojis = " ".join(season.get("emojis", []))
            themes = ", ".join(season.get("themes", [])[:4])
            reply = f"{emojis} **Aktuelle Jahreszeit: {season['name'].title()}**\n\n"
            reply += f"**Themen:** {themes}\n"
            reply += f"**Schreibstil:** {season.get('writing_style', 'neutral')}\n"
            reply += f"**Stimmungs-Einfluss:** {season.get('mood_modifier', 0):+.0%}"
            return {"type": "info", "reply": reply}

        # NAS Befehle
        if any(p in t for p in ["weck die nas", "nas aufwecken", "nas starten", "nas an"]):
            if self.comm.is_nas_online():
                return {"type": "info", "reply": "🟢 Die NAS ist bereits online!"}
            result = self.comm.request_nas_wake(f"User: {text[:30]}")
            if result.get("success"):
                return {"type": "action", "reply": f"✅ NAS wird geweckt... {result.get('result', '')}"}
            return {"type": "info", "reply": f"❌ Pi-Control sagt: {result.get('result', 'Nein')}"}

        if any(p in t for p in ["nas schlafen", "nas aus", "nas suspend"]):
            if not self.comm.is_nas_online():
                return {"type": "info", "reply": "😴 Die NAS schläft bereits!"}
            result = self.comm.request_nas_suspend(f"User: {text[:30]}")
            if result.get("success"):
                return {"type": "action", "reply": f"✅ NAS geht schlafen..."}
            return {"type": "info", "reply": f"❌ Pi-Control sagt: {result.get('result', 'Nein')}"}

        # Kalender-Einträge erstellen
        if any(p in t for p in ["kalender", "termin", "eintrag"]):
            if any(p in t for p in ["erstell", "mach", "trag ein", "plan", "setz"]):
                if BrainConfig.AUTO_EXECUTE_PERMISSIONS.get("calendar", False):
                    result = self._create_calendar_entry(text)
                    if result:
                        return result

        # Tagesplanung (vereinfacht - nutzt bestehende Daten)
        if any(p in t for p in ["organisier", "plan"]) and any(p in t for p in ["tag", "morgen", "heute"]):
            if any(p in t for p in ["mein", "den"]):
                return self._create_day_plan(text)

        # URL abrufen
        url_match = re.search(r'(https?://[^\s]+)', text)
        if url_match and any(w in t for w in ["was steht", "öffne", "zeig mir", "lies", "ruf ab"]):
            return {"type": "url_streaming", "url": url_match.group(1)}

        return None

    # =========================================================================
    # STATUS & INFO METHODS
    # =========================================================================

    def _get_events_status(self) -> Dict:
        """Gibt Status aller bevorstehenden Events zurück"""
        events = SeasonalEvents.get_current_events()

        if not events:
            reply = "📅 **Keine Events in den nächsten Tagen.**\n\n"
            reply += "Aber keine Sorge, das nächste Fest kommt bestimmt! 🎉"
            return {"type": "info", "reply": reply}

        reply = "📅 **Bevorstehende Feiertage & Events:**\n\n"

        for event_info in events:
            name = event_info["name"].title()
            days = event_info["days_until"]
            event = event_info["event"]
            emojis = " ".join(event.get("emojis", [])[:3])

            if days == 0:
                reply += f"🎉 **HEUTE: {name}!** {emojis}\n"
                greetings = event.get("greetings", [])
                if greetings:
                    reply += f"   _{random.choice(greetings)}_\n"
            elif days == 1:
                reply += f"⏰ **Morgen: {name}** {emojis}\n"
            else:
                reply += f"📆 **{name}** in {days} Tagen {emojis}\n"
                countdown = event.get("countdown_phrases", [])
                if countdown:
                    phrase = random.choice(countdown).replace("{days}", str(days))
                    reply += f"   _{phrase}_\n"

            reply += "\n"

        return {"type": "info", "reply": reply}

    def _get_emotional_status(self) -> Dict:
        """Gibt emotionalen Status zurück"""
        state = self.emotions.get_detailed_state()
        dims = state["dimensions"]

        reply = f"💕 **Meine aktuelle Stimmung:**\n\n"
        reply += f"**Zustand:** {state['state_name']}\n"
        reply += f"**Bindung zu dir:** {state['bond_level']:.0%}\n\n"

        emoji_map = {
            "energy": ("⚡", "Energie"),
            "mood": ("😊", "Stimmung"),
            "social": ("💬", "Gesprächigkeit"),
            "confidence": ("💪", "Selbstsicherheit"),
            "creativity": ("🎨", "Kreativität"),
            "affection": ("💕", "Zuneigung"),
            "playfulness": ("😜", "Verspieltheit"),
            "arousal": ("🔥", "Leidenschaft")
        }

        for key, (emoji, name) in emoji_map.items():
            val = dims.get(key, 0.5)
            bars = int(val * 10)
            reply += f"{emoji} {name}: {'█' * bars}{'░' * (10 - bars)} {val:.0%}\n"

        return {"type": "info", "reply": reply}

    def _get_greeting(self) -> str:
        hour = datetime.now().hour
        if 5 <= hour < 12:
            return "Guten Morgen! ☀️ Wie kann ich dir heute helfen?"
        elif 12 <= hour < 18:
            return "Guten Tag! Wie kann ich behilflich sein?"
        elif 18 <= hour < 22:
            return "Guten Abend! Was führt dich zu mir?"
        else:
            return "Oh, so spät noch wach? Was kann ich für dich tun?"

    def _create_day_plan(self, text: str) -> Optional[Dict]:
        """
        Erstellt einfachen Tagesplan basierend auf:
        - Kalender-Events
        - Wetter
        - Day Mode (work_day, weekend, etc.)
        - NAS Optimal Hours

        Keine AI-Planung - nur Übersicht über bestehende Daten!
        """
        from datetime import datetime, timedelta

        t = text.lower()

        # Welcher Tag?
        target_date = datetime.now()
        if "morgen" in t:
            target_date += timedelta(days=1)

        # Daten sammeln
        plan_sections = []

        # 1. Tagestyp (Day Mode)
        if hasattr(self, 'interface') and self.interface:
            try:
                day_mode = self.interface.bridge.day_mode
                mode = day_mode.get("mode", "unknown")
                mode_labels = {
                    "work_day": "📊 Arbeitstag",
                    "weekend": "🌴 Wochenende",
                    "free_day": "🎉 Freier Tag",
                    "home_office": "🏠 Home Office"
                }
                mode_label = mode_labels.get(mode, "📅 Normaler Tag")
                plan_sections.append(f"**{mode_label}**")
            except Exception:
                pass

        # 2. Wetter
        if hasattr(self, 'interface') and self.interface:
            try:
                weather_data = self.interface.context._interpret_weather(self.interface.bridge.weather)
                if weather_data.get("available"):
                    plan_sections.append(
                        f"🌤️ **Wetter:** {weather_data['temp']}°C, {weather_data['condition']}\n"
                        f"   → {weather_data['feeling']}"
                    )
            except Exception:
                pass

        # 3. Kalender-Events
        try:
            ps = self.comm.get_pi_status()
            calendar = ps.get("ai_extended", {}).get("calendar", [])
            if calendar and len(calendar) > 0:
                # Filter für den Zieltag
                target_day_str = target_date.strftime("%Y-%m-%d")
                day_events = []

                for event in calendar[:10]:  # Max 10 Events
                    event_time = event.get("start", "")
                    if target_day_str in event_time:
                        day_events.append(event)

                if day_events:
                    plan_sections.append("📅 **Termine:**")
                    for event in day_events[:5]:  # Max 5 anzeigen
                        try:
                            event_dt = datetime.fromisoformat(event["start"].replace("Z", "+00:00"))
                            time_str = event_dt.strftime("%H:%M")
                            summary = event.get("summary", "Termin")
                            plan_sections.append(f"   • {time_str} - {summary}")
                        except Exception:
                            pass
                else:
                    plan_sections.append("📅 **Keine Termine** - Du hast heute frei!")
            else:
                plan_sections.append("📅 **Keine Termine** - Du hast heute frei!")
        except Exception:
            pass

        # 4. Vorschläge basierend auf NAS Optimal Hours (falls vorhanden)
        if hasattr(self, 'interface') and self.interface:
            try:
                optimal_hours = self.interface.bridge.optimal_hours
                if optimal_hours and len(optimal_hours) > 0:
                    # Optimal Hours für den Tag
                    plan_sections.append(
                        f"💡 **Optimale Zeiten für intensive Arbeit:**\n"
                        f"   {', '.join(f'{h}:00' for h in optimal_hours[:5])} Uhr"
                    )
            except Exception:
                pass

        # 5. Zusammenfassung
        if not plan_sections:
            return {
                "type": "info",
                "reply": "Ich habe noch nicht genug Daten für einen Tagesplan. Lass mich mehr über deinen Alltag lernen!"
            }

        day_str = "Morgen" if "morgen" in t else "Heute"
        reply = f"📋 **Dein Tag - {day_str}**\n\n" + "\n\n".join(plan_sections)

        # Abschluss-Tipp
        if hasattr(self, 'interface') and self.interface:
            try:
                day_mode = self.interface.bridge.day_mode
                mode = day_mode.get("mode", "")
                if mode == "work_day":
                    reply += "\n\n💪 Viel Erfolg bei der Arbeit!"
                elif mode == "weekend":
                    reply += "\n\n😊 Genieß dein Wochenende!"
                elif mode == "free_day":
                    reply += "\n\n🎉 Mach was Schönes aus deinem freien Tag!"
            except Exception:
                pass

        return {"type": "info", "reply": reply}

    def _create_calendar_entry(self, text: str) -> Optional[Dict]:
        """
        Erstellt einen Kalender-Eintrag aus User-Text.
        Einfaches Parsing ohne AI - nur häufige Muster.
        """
        from datetime import datetime, timedelta

        t = text.lower()
        now = datetime.now()

        # 1. Datum parsen
        start_dt = None
        duration_hours = 1  # Default: 1 Stunde

        # "morgen"
        if "morgen" in t:
            start_dt = now.replace(hour=9, minute=0, second=0, microsecond=0) + timedelta(days=1)
        # "übermorgen"
        elif "übermorgen" in t:
            start_dt = now.replace(hour=9, minute=0, second=0, microsecond=0) + timedelta(days=2)
        # "heute"
        elif "heute" in t:
            start_dt = now.replace(hour=9, minute=0, second=0, microsecond=0)
        # "nächste woche"
        elif any(w in t for w in ["nächste woche", "nächster woche"]):
            start_dt = now.replace(hour=9, minute=0, second=0, microsecond=0) + timedelta(days=7)
        else:
            # Kein erkanntes Datum
            start_dt = now.replace(hour=9, minute=0, second=0, microsecond=0) + timedelta(days=1)

        # 2. Uhrzeit parsen
        # Pattern: "um 15 Uhr", "um 15:30", "15 uhr", "15:30 uhr"
        time_match = re.search(r'um\s+(\d{1,2})[:\.]?(\d{2})?\s*uhr|(\d{1,2})[:\.](\d{2})\s*uhr', t)
        if time_match:
            hour = int(time_match.group(1) or time_match.group(3))
            minute = int(time_match.group(2) or time_match.group(4) or 0)
            start_dt = start_dt.replace(hour=hour, minute=minute)

        # 3. Titel extrahieren (alles nach "erstell", "trag ein", etc.)
        summary = "Termin"  # Default

        # Versuche Titel zu finden
        for prefix in ["erstell ", "trag ein ", "mach ", "plan ", "setz "]:
            if prefix in t:
                after_prefix = t.split(prefix, 1)[1]
                # Entferne Zeit-Info
                summary_clean = re.sub(r'um\s+\d{1,2}[:\.]?\d{0,2}\s*uhr', '', after_prefix)
                summary_clean = re.sub(r'\d{1,2}[:\.]?\d{0,2}\s*uhr', '', summary_clean)
                # Entferne Datum-Info
                for date_word in ["morgen", "übermorgen", "heute", "nächste woche"]:
                    summary_clean = summary_clean.replace(date_word, "")
                # Entferne Trigger-Wörter
                for trigger in ["kalender", "termin", "eintrag", "mir", "einen", "ein", "den"]:
                    summary_clean = summary_clean.replace(trigger, "")
                summary = summary_clean.strip()
                if len(summary) > 3:
                    break

        if not summary or len(summary) < 3:
            summary = "Termin"

        # Capitalize first letter
        summary = summary[0].upper() + summary[1:] if summary else "Termin"

        # 4. End-Zeit (Default: 1 Stunde später)
        end_dt = start_dt + timedelta(hours=duration_hours)

        # 5. Kalender-Eintrag erstellen
        try:
            result = self.comm.create_calendar_event(
                summary=summary,
                start_datetime=start_dt.isoformat(),
                end_datetime=end_dt.isoformat(),
                description=f"Erstellt von Holo auf Anfrage: {text}"
            )

            if result.get("success"):
                # Formatiere Datum/Zeit für Antwort
                date_str = start_dt.strftime("%d.%m.%Y")
                time_str = start_dt.strftime("%H:%M")
                return {
                    "type": "action",
                    "reply": f"✅ Kalender-Eintrag erstellt!\n\n📅 **{summary}**\n🕐 {date_str} um {time_str} Uhr"
                }
            else:
                error_msg = result.get("error", "Unbekannter Fehler")
                return {
                    "type": "info",
                    "reply": f"❌ Konnte Kalender-Eintrag nicht erstellen: {error_msg}"
                }

        except Exception as e:
            logger.error(f"Calendar creation error: {e}")
            return {
                "type": "info",
                "reply": f"❌ Fehler beim Erstellen: {str(e)}"
            }

    def _interpret_nas_state(self, nas_status: Dict) -> str:
        """
        ✅ NEU: Interpretiert NAS State in menschenfreundlichen Text

        Args:
            nas_status: NAS Status Dict mit "state" und "online"

        Returns:
            Menschenfreundliche Beschreibung
        """
        online = nas_status.get("online", False)
        state = nas_status.get("state", "unknown")
        connections = nas_status.get("connections", 0)

        if not online:
            return "🔴 Offline (schläft)"

        # State-Interpretation
        state_map = {
            "idle": "🟢 Online (steht bereit)",
            "busy": "🟡 Online (arbeitet gerade)",
            "sleeping": "🔴 Schläft",
            "waking_up": "🟡 Fährt gerade hoch...",
            "booting": "🟡 Startet...",
            "unknown": "🟢 Online"
        }

        base_status = state_map.get(state, f"🟢 Online ({state})")

        # Verbindungen hinzufügen
        if connections > 0:
            base_status += f" | {connections} Verbindung{'en' if connections > 1 else ''}"

        return base_status

    def _personal_wellbeing_response(self) -> Dict:
        """
        Generiert eine PERSÖNLICHE Antwort auf 'Wie geht es dir?'
        Basierend auf Holos echtem innerem Zustand!
        """
        try:
            # Versuche das SelfExpression Modul zu nutzen
            if hasattr(self, 'self_expression') and self.self_expression:
                response = self.self_expression.self_expression.how_am_i_feeling()
                return {"type": "personal", "reply": response}
        except Exception as e:
            logger.debug(f"SelfExpression nicht verfügbar: {e}")

        # Fallback: Generiere basierend auf verfügbaren Daten
        parts = []

        # Energie-Level
        energy_level = 1.0
        if self.energy and hasattr(self.energy, 'state'):
            energy_level = getattr(self.energy.state, 'effective_energy', 1.0)

        if energy_level > 0.7:
            parts.append("*wedelt energiegeladen* Mir geht es super!")
        elif energy_level > 0.4:
            parts.append("Mir geht es ganz gut!")
        elif energy_level > 0.2:
            parts.append("*gähnt leicht* Ich bin etwas müde, aber sonst okay.")
        else:
            parts.append("*legt müde den Kopf ab* Ich bin ziemlich erschöpft...")

        # Langeweile/Triebe aus autonomous_life
        if hasattr(self, 'autonomous_life') and self.autonomous_life:
            try:
                boredom = self.autonomous_life.boredom.state.level
                if boredom > 0.6:
                    parts.append("Mir war etwas langweilig, aber jetzt wo du da bist...")

                urgent_drive = self.autonomous_life.drives.get_most_urgent()
                if urgent_drive and urgent_drive.is_urgent:
                    drive_text = urgent_drive.get_urge_text()
                    if drive_text:
                        parts.append(drive_text)
            except Exception:
                pass

        # Rückfrage
        parts.append("Und dir?")

        return {"type": "personal", "reply": " ".join(parts)}

    def _status_report(self) -> Dict:
        ps = self.comm.get_pi_status()
        state = ps.get("state", ps)
        metrics = state.get("system_metrics", {})
        nas = state.get("nas_status", {})
        weather = ps.get("ai_extended", {}).get("weather", {})

        reply = f"📊 **Statusbericht**\n\n"
        reply += f"**System:** CPU {metrics.get('cpu_usage', '?')}% | {metrics.get('cpu_temp', '?')}°C | RAM {metrics.get('ram_usage', '?')}%\n"

        # ✅ NEU: Nutze NAS State Interpretation
        nas_status_text = self._interpret_nas_state(nas)
        reply += f"**NAS:** {nas_status_text}\n"

        if weather.get("temp"):
            # Wetter ins Deutsche übersetzen
            desc = weather.get('description', '?')
            desc_de = WeatherTranslator.translate(desc) if desc else '?'
            reply += f"**Wetter:** {weather.get('temp')}°C, {desc_de}\n"

        # NEU: Holo Energy Status
        if self.energy:
            try:
                energy = self.energy.get_status()
                reply += f"**Meine Energie:** {energy.get('total_energy', 0.5):.0%}\n"
            except Exception:
                pass

        return {"type": "status", "reply": reply}

    def _get_news(self, tech_only: bool = False) -> Dict:
        """Holt News vom Pi-Control und formatiert sie schön.

        Args:
            tech_only: Wenn True, nur Technik/Gaming/Science-News zeigen
        """
        ps = self.comm.get_pi_status()
        news_data = ps.get("state", {}).get("news_data", [])

        if not news_data:
            return {"type": "info", "reply": "📰 Keine News verfügbar. Ist der Pi-Control online?"}

        # Gruppiere nach Kategorie (nutze neues 'category' Feld, Fallback auf 'source')
        grouped = {}
        for news in news_data:
            cat = news.get('category', news.get('source', 'Sonstiges'))
            if cat not in grouped:
                grouped[cat] = []
            grouped[cat].append(news)

        # Filter nur Technik/Gaming/Science wenn gewünscht
        if tech_only:
            tech_cats = ["Technik", "Tech", "Gaming", "Science", "Wissenschaft", "Heise", "Golem", "GameStar"]
            grouped = {k: v for k, v in grouped.items() if k in tech_cats}
            if not grouped:
                return {"type": "info", "reply": "💻 Keine Technik/Gaming-News gefunden."}

        # Kategorie-Emojis
        EMOJIS = {
            "technik": "💻", "tech": "💻", "heise": "💻", "golem": "💻",
            "gaming": "🎮", "gamestar": "🎮", "pc games": "🎮", "ign": "🎮",
            "science": "🔬", "wissenschaft": "🔬", "scinexx": "🔬", "spektrum": "🔬",
            "welt": "🌍", "tagesschau": "🌍", "zeit": "🌍", "world": "🌍",
            "politik": "🏛️", "wirtschaft": "📈", "sport": "⚽",
            "kultur": "🎭",
        }

        # Sortiere Kategorien (Technik & Gaming zuerst für Kira!)
        priority = ["Technik", "Gaming", "Science", "Welt", "Politik", "Wirtschaft"]
        sorted_cats = []
        for p in priority:
            if p in grouped:
                sorted_cats.append(p)
        for c in grouped:
            if c not in sorted_cats:
                sorted_cats.append(c)

        # Formatiere Output
        header = "💻🎮 **Tech & Gaming News:**" if tech_only else "📰 **Aktuelle Nachrichten:**"
        lines = [header]

        for cat in sorted_cats:
            items = grouped[cat][:5]  # Max 5 pro Kategorie
            emoji = EMOJIS.get(cat.lower(), "📰")

            lines.append(f"\n{emoji} **{cat.upper()}**")
            for item in items:
                title = item.get('title', '?')
                if len(title) > 85:
                    title = title[:82] + "..."
                lines.append(f"  • {title}")

        # Statistik
        total = sum(len(v) for v in grouped.values())
        lines.append(f"\n_({total} Meldungen in {len(grouped)} Kategorien)_")

        return {"type": "news", "reply": "\n".join(lines)}

