    def _gather_context(self) -> Dict:
        ctx = {"timestamp": datetime.now().isoformat(), "hour": datetime.now().hour}
        ctx["pi_status"] = self.comm.get_pi_status()
        ctx["heartbeat_ok"] = ctx["pi_status"].get("_heartbeat_ok", False)
        self.learning.observe(ctx)

        # HoloEnergySystem Update (Zeit-basierte Energie-Berechnung)
        if self.energy and hasattr(self.energy, 'update'):
            try:
                # Wetter für Energy-Kontext
                weather = ctx["pi_status"].get("ai_extended", {}).get("weather", {})
                energy_context = {"weather": weather} if weather else {}

                # Update ruft intern die Zeit-basierte Berechnung auf
                self.energy.update(energy_context)

                # Cache Wetter für späteren Gebrauch
                self._last_weather = weather
            except Exception as e:
                logger.debug(f"Energy update error in gather_context: {e}")

        return ctx

    def _find_memories(self, query: str) -> List:
        kws = self.learning._extract_keywords(query)
        if kws:
            return self.legacy_memory.search_episodes(max(kws, key=len), 3)
        return []

    def _on_tool_notification(self, notification: Dict):
        """
        Callback für Tool-Benachrichtigungen (Timer abgelaufen, etc.)

        THREAD-SAFE: Wird von Timer-Threads aufgerufen!

        WICHTIG: add_pending_message() speichert bereits in Chat-Historie!
        Deshalb hier NICHT nochmal speichern!
        """
        if not notification or not isinstance(notification, dict):
            logger.warning(f"🔔 Invalid notification: {type(notification)}")
            return

        try:
            msg = notification.get("message", "")
            tool = notification.get("tool", "timer")

            if not msg:
                logger.warning(f"🔔 Empty notification message from {tool}")
                return

            # Tool-Name schöner machen
            tool_names = {
                "timer": "Timer",
                "reminder": "Erinnerung",
                "alarm": "Alarm",
                "note": "Notiz",
                "todo": "Aufgabe",
                "unknown": "Benachrichtigung",
            }
            tool_display = tool_names.get(tool.lower(), tool.title())

            logger.info(f"🔔 Tool-Notification [{tool_display}]: {msg[:50]}...")

            # Format für Nachricht basierend auf Tool-Typ
            if tool.lower() == "timer":
                display_msg = f"⏰ {msg}"
            elif tool.lower() == "reminder":
                display_msg = f"🔔 {msg}"
            elif tool.lower() == "alarm":
                display_msg = f"⏰🔊 {msg}"
            else:
                display_msg = f"[{tool_display}] {msg}"

            # === NUR ALS PROAKTIVE NACHRICHT SPEICHERN ===
            # add_pending_message() speichert auch in Chat-Historie!
            if hasattr(self, 'proactive') and self.proactive:
                success = self.proactive.add_pending_message(display_msg, source=f"tool_{tool}")
                if success:
                    logger.info(f"📨 Pending message hinzugefügt: {display_msg[:30]}...")
                else:
                    logger.warning(f"📨 Failed to add pending message")
                    # Fallback: Direkt in Chat-Historie
                    self._fallback_save_notification(display_msg, tool)
            else:
                logger.warning(f"⚠️ proactive nicht verfügbar, nutze Fallback")
                self._fallback_save_notification(display_msg, tool)

            # An Browser senden (wenn verfügbar)
            if hasattr(self, 'pending_notifications') and isinstance(self.pending_notifications, list):
                self.pending_notifications.append({
                    "type": "tool_notification",
                    "tool": tool,
                    "message": msg,
                    "timestamp": datetime.now().isoformat()
                })
                # Limit: Max 50 pending notifications
                if len(self.pending_notifications) > 50:
                    self.pending_notifications.pop(0)

            # Optional: An Pi senden für Audio-Feedback
            if hasattr(self, 'comm') and self.comm:
                try:
                    self.comm.send_notification(f"🔔 {msg}")
                except Exception as e:
                    logger.debug(f"Could not send to Pi: {e}")

        except Exception as e:
            logger.error(f"Tool notification error: {e}", exc_info=True)

    def _fallback_save_notification(self, message: str, tool: str):
        """Fallback: Speichert Notification direkt in Chat-Historie"""
        try:
            if hasattr(self, 'legacy_memory') and self.legacy_memory:
                self.legacy_memory.store_chat_message(
                    "assistant",
                    message,
                    {"type": "tool_notification", "tool": tool, "fallback": True}
                )
                logger.debug(f"📨 Fallback save: {message[:30]}...")
        except Exception as e:
            logger.error(f"Fallback save failed: {e}")

    def _on_autonomous_thought(self, thought: str):
        """Callback wenn das autonome System einen Gedanken hat"""
        try:
            logger.debug(f"💭 Autonomer Gedanke: {thought[:50]}...")

            # === LIFE LOG: Gedanke speichern ===
            energy_level = None
            mood = None
            if hasattr(self, 'energy') and self.energy:
                try:
                    status = self.energy.get_status()
                    energy_level = status.get('total_energy', 0.5)
                except Exception:
                    pass
            if hasattr(self, 'emotions') and self.emotions:
                try:
                    mood = self.emotions.get_dominant_mood()
                except Exception:
                    pass

            self.legacy_memory.log_life_event(
                category="thought",
                event_type="autonomous",
                description=thought[:200],
                details={"full_thought": thought},
                energy_level=energy_level,
                mood=str(mood) if mood else None
            )

            # Speichere in innerem Monolog wenn vorhanden
            if hasattr(self, 'consciousness') and self.consciousness:
                if hasattr(self.consciousness, 'inner_monologue'):
                    try:
                        self.consciousness.inner_monologue.add_thought(thought)
                    except Exception:
                        pass

        except Exception as e:
            logger.debug(f"Autonomous thought callback error: {e}")

    def _on_autonomous_contact(self, message: str):
        """Callback wenn das autonome System den User kontaktieren will"""
        try:
            logger.info(f"📨 Autonomer Kontaktwunsch: {message[:50]}...")

            # === LIFE LOG: Kontaktwunsch speichern ===
            self.legacy_memory.log_life_event(
                category="social",
                event_type="contact_wish",
                description=f"Möchte User kontaktieren: {message[:100]}",
                details={"full_message": message}
            )

            # Speichere als pending message
            if hasattr(self, 'pending_autonomous_messages'):
                self.pending_autonomous_messages.append({
                    "message": message,
                    "timestamp": datetime.now().isoformat(),
                    "source": "autonomous_life"
                })
            else:
                self.pending_autonomous_messages = [{
                    "message": message,
                    "timestamp": datetime.now().isoformat(),
                    "source": "autonomous_life"
                }]

        except Exception as e:
            logger.error(f"Autonomous contact callback error: {e}")

