    def get_life_log(self, hours: int = None, days: int = None,
                     category: str = None, limit: int = 100) -> Dict:
        """
        Holt Holos Life-Log - eine Aufzeichnung ihres autonomen Lebens.

        Args:
            hours: Zeitraum in Stunden (z.B. 24)
            days: Zeitraum in Tagen (z.B. 7 für Woche, 30 für Monat)
            category: Optional - nur Events dieser Kategorie
                     (thought, activity, emotion, curiosity, boredom,
                      dream, idle, social, learning, creative)
            limit: Max Anzahl Events (default: 100)

        Returns:
            Dict mit events, summary und statistics

        Beispiele:
            holo.get_life_log(hours=24)           # Letzter Tag
            holo.get_life_log(days=7)             # Letzte Woche
            holo.get_life_log(days=30)            # Letzter Monat
            holo.get_life_log(days=365)           # Letztes Jahr
            holo.get_life_log(category="thought") # Nur Gedanken
        """
        try:
            events = self.legacy_memory.get_life_history(
                category=category,
                hours=hours,
                days=days,
                limit=limit
            )
            summary = self.legacy_memory.get_life_summary(hours=hours, days=days)

            return {
                "events": events,
                "summary": summary,
                "total_events": len(events),
                "categories_found": list(set(e.get("category") for e in events if e.get("category"))),
                "filter_category": category,
                "time_filter": f"{days} Tage" if days else f"{hours} Stunden" if hours else "Alle"
            }
        except Exception as e:
            logger.debug(f"Life log error: {e}")
            return {"events": [], "summary": {}, "total_events": 0}

