    def process_smart_home_command(self, text: str) -> Dict:
        """
        Verarbeitet Smart Home Befehle über natürliche Sprache.

        Args:
            text: Natürlichsprachlicher Befehl, z.B. "Mach das Licht in der Küche an"

        Returns:
            Dict mit success, message, etc.
        """
        if not hasattr(self, 'interface') or not self.interface:
            return {"success": False, "message": "Smart Home Interface nicht verfügbar"}

        try:
            result = self.interface.process_text(text)
            return {
                "success": result.success,
                "message": result.result if result.success else result.reason,
                "executed": result.executed
            }
        except Exception as e:
            return {"success": False, "message": f"Fehler: {e}"}

