    def self_learn_from_interaction(self, user_reaction: float,
                                     self_feeling: float = None,
                                     authenticity: float = None):
        """
        Lässt Holo aus einer Interaktion lernen.

        Rufe das nach jeder Antwort auf!

        Args:
            user_reaction: 0-1, wie hat User reagiert (0=negativ, 1=positiv)
            self_feeling: 0-1, wie fühlt sich Holo (auto-detected wenn None)
            authenticity: 0-1, wie authentisch war die Antwort (auto-detected wenn None)
        """
        if not hasattr(self, 'self_awareness') or not self.self_awareness:
            return

        # Auto-detect self_feeling basierend auf Emotionen
        if self_feeling is None:
            if hasattr(self, 'emotions') and self.emotions:
                self_feeling = getattr(self.emotions, 'current_mood', 0.5)
            else:
                self_feeling = 0.6

        # Auto-detect authenticity
        if authenticity is None:
            authenticity = 0.7  # Default: meist authentisch

        try:
            self.self_awareness.learn_from_interaction(
                user_reaction=user_reaction,
                self_feeling=self_feeling,
                authenticity=authenticity
            )
        except Exception as e:
            logger.debug(f"Self-learning error: {e}")

        # Cognitive Enhancement lernt auch aus der Interaktion
        if hasattr(self, 'cognitive_enhancement') and self.cognitive_enhancement:
            try:
                # Hole letzte User-Nachricht und Holo-Antwort aus der History
                user_msg = ""
                holo_response = ""
                if hasattr(self, 'conversation_history') and self.conversation_history:
                    for msg in reversed(self.conversation_history[-4:]):
                        if msg.get('role') == 'user' and not user_msg:
                            user_msg = msg.get('content', '')
                        elif msg.get('role') == 'assistant' and not holo_response:
                            holo_response = msg.get('content', '')

                if user_msg:
                    self.cognitive_enhancement.learn_from_interaction(
                        user_message=user_msg,
                        holo_response=holo_response,
                        was_successful=(user_reaction >= 0.5)
                    )
            except Exception as e:
                logger.debug(f"Cognitive enhancement learning error: {e}")

    def generate_creative_goal(self) -> Optional[str]:
        """
        Generiert ein kreatives neues Ziel aus Holos Erfahrungen.

        Returns:
            Beschreibung des neuen Ziels oder None
        """
        if not hasattr(self, 'self_awareness') or not self.self_awareness:
            return None

        # Sammle Topics aus verschiedenen Quellen
        topics = []

        # Aus Curiosity
        if hasattr(self, 'learning') and self.learning:
            if hasattr(self.learning, 'curiosity_topics'):
                topics.extend([t.topic for t in self.learning.curiosity_topics[:10]])

        # Aus Memory
        if hasattr(self, 'legacy_memory') and self.legacy_memory:
            try:
                knowledge = self.legacy_memory.get_knowledge()
                if isinstance(knowledge, dict):
                    for fact in knowledge.get('facts', [])[:5]:
                        topics.append(str(fact))
            except Exception:
                pass

        if len(topics) < 2:
            return None

        try:
            goal = self.self_awareness.generate_creative_goals(topics)
            if goal:
                return goal.description
        except Exception as e:
            logger.debug(f"Creative goal error: {e}")

        return None

