    def evaluate_web_source(self, url: str) -> Dict:
        """
        Bewertet eine Web-Quelle kritisch.

        Args:
            url: Die URL der Quelle

        Returns:
            Dict mit trust_score, is_trustworthy, reason

        Example:
            >>> holo.evaluate_web_source("https://www.tagesschau.de/news")
            {"trust_score": 0.85, "is_trustworthy": True, "reason": "Seriöse Nachrichtenquelle"}
        """
        if not hasattr(self, 'web_curiosity') or not self.web_curiosity:
            return {"url": url, "trust_score": 0.5, "is_trustworthy": True, "reason": "Nicht bewertet"}

        try:
            return self.web_curiosity.evaluate_source(url)
        except Exception as e:
            logger.debug(f"Source evaluation error: {e}")
            return {"url": url, "trust_score": 0.5, "is_trustworthy": True, "reason": "Fehler"}

    def learn_web_fact(self, content: str, topic: str, source_url: str,
                       related_topics: List[str] = None) -> Dict:
        """
        Lernt einen neuen Fakt aus dem Web - MIT kritischer Prüfung!

        Args:
            content: Der Fakt
            topic: Hauptthema
            source_url: Woher kommt die Info
            related_topics: Verwandte Themen

        Returns:
            Dict mit trust_score, status, holos_response, new_interest
        """
        if not hasattr(self, 'web_curiosity') or not self.web_curiosity:
            return {"content": content, "trust_score": 0.5, "status": "unverified"}

        try:
            result = self.web_curiosity.learn_fact(content, topic, source_url, related_topics)

            # === LIFE LOG: Web-Recherche dokumentieren ===
            self.legacy_memory.log_life_event(
                category="curiosity",
                event_type="web_learning",
                description=f"Neues über '{topic}' gelernt (Trust: {result.get('trust_score', 0.5):.0%})",
                details={
                    "topic": topic,
                    "content": content[:200],
                    "source": source_url,
                    "trust_score": result.get("trust_score"),
                    "status": result.get("status"),
                    "new_interest": result.get("new_interest")
                }
            )

            return result
        except Exception as e:
            logger.debug(f"Learn fact error: {e}")
            return {"content": content, "trust_score": 0.5, "status": "error"}

