    def save_webpage(self, url: str, title: str = None, category: str = "gespeichert") -> Dict:
        """
        Speichert eine Webseite für später.

        Für Befehle wie:
        - "Speicher diese Seite: [url]"
        - "Merk dir diesen Link: [url]"
        - "Kannst du diese Seite speichern?"

        Args:
            url: Die URL der Seite
            title: Optionaler Titel
            category: Kategorie (default: "gespeichert")

        Returns:
            Dict mit Ergebnis
        """
        if not hasattr(self, 'autonomous_activity') or not self.autonomous_activity:
            return {'success': False, 'error': 'ReadingEngine nicht verfügbar'}

        if not self.autonomous_activity.reading_engine:
            return {'success': False, 'error': 'ReadingEngine nicht initialisiert'}

        try:
            result = self.autonomous_activity.reading_engine.save_webpage(url, title, category)

            # Holo-Style Antwort generieren
            if result.get('success'):
                result['holo_response'] = f"*wedelt zufrieden* Alles klar! Ich hab mir '{result.get('title', 'die Seite')[:30]}...' gemerkt! ({result.get('content_length', 0)} Zeichen) 📚😊"
            else:
                result['holo_response'] = f"*Ohren legen sich an* Hmm, das hat nicht geklappt: {result.get('error', 'Unbekannter Fehler')} 😕"

            return result
        except Exception as e:
            logger.debug(f"save_webpage error: {e}")
            return {'success': False, 'error': str(e)}

