    def get_storage_status(self) -> Dict:
        """
        Gibt kompletten Speicher-Status zurück.

        Zeigt beide Datenbanken:
        - Core-DB (holo_brain_v12.db): Chat, Reflexionen, Träume
        - Knowledge-DB (holo_knowledge.db): Readings, Fakten

        Für Fragen wie:
        - "Wie viel Speicher verwendest du?"
        - "Wie viele Nachrichten hast du gespeichert?"
        - "Zeig mir deinen Speicher-Status"

        Returns:
            Dict mit Chat- und Reading-Statistiken
        """
        status = {
            'core_db': {
                'name': 'holo_brain_v12.db',
                'purpose': 'Chat, Reflexionen, Träume, Persönlichkeit',
                'max_gb': BrainConfig.MAX_CORE_STORAGE_GB,
            },
            'knowledge_db': {
                'name': 'holo_knowledge.db',
                'purpose': 'Artikel, Fakten, News',
                'max_gb': BrainConfig.MAX_KNOWLEDGE_STORAGE_GB,
            },
            'chat': {},
            'readings': {},
            'total': {}
        }

        # Chat-Statistiken (Core-DB)
        try:
            chat_info = self.memory.get_chat_storage_info()
            status['chat'] = chat_info
            status['core_db']['used_mb'] = chat_info.get('size_mb', 0)
        except Exception:
            status['chat'] = {'error': 'Nicht verfügbar'}

        # Reading-Statistiken (Knowledge-DB)
        if hasattr(self, 'autonomous_activity') and self.autonomous_activity:
            if self.autonomous_activity.reading_engine:
                try:
                    reading_status = self.autonomous_activity.reading_engine.get_status()
                    status['readings'] = reading_status
                    status['knowledge_db']['used_mb'] = reading_status.get('storage', {}).get('used_mb', 0)
                except Exception:
                    status['readings'] = {'error': 'Nicht verfügbar'}

        # Gesamt
        core_mb = status.get('core_db', {}).get('used_mb', 0)
        knowledge_mb = status.get('knowledge_db', {}).get('used_mb', 0)
        status['total'] = {
            'used_mb': round(core_mb + knowledge_mb, 2),
            'used_gb': round((core_mb + knowledge_mb) / 1024, 2),
            'core_db_mb': core_mb,
            'knowledge_db_mb': knowledge_mb,
            'max_total_gb': BrainConfig.MAX_CORE_STORAGE_GB + BrainConfig.MAX_KNOWLEDGE_STORAGE_GB,
        }

        return status

